WordHunterWoW_QuestEN = WordHunterWoW_QuestEN or {}
WordHunterWoW_QuestEN[54210] = { title = "Chapter 4 A End", description = "I'm glad we can count on you {name}.", objectives = "" }
WordHunterWoW_QuestEN[54211] = { title = "Putting the Gob in Gob Squad", description = "Yo! We gotta get the rest of the Gob Squad back if we wanna fix the A.F.M.O.D.!\n\nSo, our mech got trashed. It was rough. The rest of the Gob Squad are hidin' out there, waiting for word when it's safe.\n\nTake this tracker. It'll tell ya when you're getting close to one of the squad. When you get real close, you should see 'em.\n\nThat'll tell any of the squad nearby that it's safe to come outta hidin' and come back here.\n\nWith the right goblins and parts, we'll be killing Alliance in no time!", objectives = "Rescue the Gob Squad.", progress = "You didn't blow up the Gob Squad tracker, did you?", completion = "I gotta tell ya, it feels good to get the gang back." }
WordHunterWoW_QuestEN[54212] = { title = "Re-rebuilding the A.F.M.O.D.", description = "Alright, so, we're goin' after the Alliance through this crazy fog. We gotta retake Zo'bal ruins up ahead.\n\nWe can do that real easy if we fix up our mech, A.F.M.O.D. - a flying mech of death! \n\nThe Alliance wrecked it in their initial attack and took a bunch of its parts. Get those parts back and we'll have this thing fixed in no time!", objectives = "Recover 10 A.F.M.O.D. parts from Gilnean Ambushers and Night Elf Sentinels.", progress = "You got the parts? We'll figure out what goes where when it's all done.", completion = "Great! We'll get this thing fixed in no time." }
WordHunterWoW_QuestEN[54213] = { title = "It's Alive!", description = "We got the A.F.M.O.D. repaired and it works perfectly! Eh, except that it's got no power.\n\nPrincess Talanji seems like she can help us out with this. Ask her if she can give the mech a jumpstart!\n\nOnce we're set, we can use this thing to mow down the Alliance, take back Zul'jan ruins, and push forward to blow up that fleet!", objectives = "Speak with Talanji to power up the A.F.M.O.D.", progress = "Uh, can we get this thing started or what?", completion = "Hahaha! Now it's time to show these guys how we roll." }
WordHunterWoW_QuestEN[54224] = { title = "The Battle of Zul'jan Ruins", description = "General Rakera has pushed forward with de army. Raal and his forces are still grounded until we remove dis fog.\n\nYou must pilot de A.F.M.O.D. and help our forces retake Zul'jan ruins. Only den can we move ahead to stop de Alliance and dis fog.\n\nRokhan, and I will join you. De Alliance must see dat our victory is swift and decisive. \n\nI would have our enemies cower before us when dey meet dere ends. Such is de price for defiling our lands.", objectives = "Pilot the A.F.M.O.D. and retake Zul'jan ruins.", completion = "De last time I was in Zul'jan, we had an army cobbled together from our allies in Nazmir.\n\nNow, we have de full force of my empire and de Horde. Let us march forward!" }
WordHunterWoW_QuestEN[54225] = { title = "Mission Report: The Great Seal", description = "Your followers have sent a report regarding the mission at The Great Seal.\n\nIt details that the mission was a success and that a Mission Command Table has been constructed.\n\nDeliver the report to Nathanos Blightcaller aboard The Banshee's Wail.", objectives = "Deliver the mission report to Nathanos Blightcaller.", progress = "Do you have news regarding the mission to The Great Seal?", completion = "It seems the mission at The Great Seal was a success. Well done, <name>." }
WordHunterWoW_QuestEN[54231] = { title = "Outpost Upgrade: The Great Seal", description = "The mission at The Great Seal was a success. Well done, {name}.\n\nA Mission Command Table is now ready for use.\n\nTravel to The Great Seal and see that the troops quality of work is up to our standard.", objectives = "Inspect the Mission Command Table at The Great Seal." }
WordHunterWoW_QuestEN[54236] = { title = "Naga Attack!", description = "", objectives = "" }
WordHunterWoW_QuestEN[54237] = { title = "Togoth Cruelarm", description = "", objectives = "" }
WordHunterWoW_QuestEN[54239] = { title = "Mission Report: Zul'jan Ruins", description = "Your followers have sent a report regarding the mission at Zul'jan Ruins.\n\nIt details that the mission was a success and that the power of the Loa has increased, allowing for Boons to persist longer.\n\nDeliver the report to Nathanos Blightcaller aboard The Banshee's Wail.", objectives = "Deliver the mission report to Nathanos Blightcaller.", progress = "Do you have news regarding the mission to Zul'jan Ruins?", completion = "It seems the mission at Zul'jan Ruins was a success. Well done, <name>." }
WordHunterWoW_QuestEN[54240] = { title = "Outpost Upgrade: Zul'jan Ruins", description = "The mission at Zul'jan Ruins was a success. Well done, {name}.\n\nThe Boons of the Loa are now more powerful and will be granted whenever you are in Zandalar.\n\nTravel to the Zul'jan Ruins and honor an altar of your choice.", objectives = "Choose a Loa Boon from the altars at Zul'jan Ruins." }
WordHunterWoW_QuestEN[54243] = { title = "Gobliteration", description = "", objectives = "" }
WordHunterWoW_QuestEN[54244] = { title = "We Have Them Cornered", description = "General Rakera has already begun mobilizing our forces to our next target: Zalamar.\n\nOnce we destroy de Alliance dere, we can push forward to de coast and destroy de source of dis fog.\n\nDe Alliance will have nowhere to hide. We will surround their fleet and end dis war, once for all.\n\nDey will wish dey never stepped foot in Nazmir.\n\nCome. We shall ride together to Zalamar and ensure our victory!", objectives = "Ride with Princess Talanji and Rokhan to Zalamar.", progress = "We must move!", completion = "We have de Alliance forces cornered. We must finish dem off." }
WordHunterWoW_QuestEN[54245] = { title = "Azerite Altercation", description = "", objectives = "" }
WordHunterWoW_QuestEN[54246] = { title = "Azerite Altercation", description = "", objectives = "" }
WordHunterWoW_QuestEN[54249] = { title = "Zandalari Justice", description = "We must wipe out whatever is left of de Alliance in Zalamar. Den we can find de source of dis fog and dere fleet.\n\nRokhan will scout ahead to find dis Telaamon. He appears to be de general leading de forces here.\n\nI need you to go in and wipe out de Alliance forces within Zalamar so dat we can crush dem once and for all.\n\nFind Rokhan in Zalamar after dey have been weakened.", objectives = "Defeat 15 Alliance forces within Zalamar.", progress = "We must keep up de pressure on de Alliance.", completion = "I be dealin' with de Alliance down here. I woulda thought dey be bringin' more soldiers ta de party." }
WordHunterWoW_QuestEN[54251] = { title = "The Ambassador", description = "", objectives = "" }
WordHunterWoW_QuestEN[54253] = { title = "Bombs Away", description = "", objectives = "" }
WordHunterWoW_QuestEN[54254] = { title = "Bombs Away", description = "", objectives = "" }
