WordHunterWoW_QuestEN[54451] = { title = "Baubles from the Seekers", description = "We Tortollan's appreciate all the help you've given us.\n\nPlease take these supplies as a token of our gratitude, and a promise of more to come, should you continue to help us.", objectives = "Speak with Collector Kojo.", completion = "We Tortollan's appreciate all the help you've given us.\n\nPlease take these supplies as a token of our gratitude, and a promise of more to come, should you continue to help us." }
WordHunterWoW_QuestEN[54453] = { title = "Supplies from Magni", description = "Champion of Azeroth, I appreciate all the help you've given us.\n\nPlease take these supplies as a token of my  gratitude, and a promise of more to come, should you continue to help.", objectives = "Speak with Magni Bronzebeard in Silithus for your reward.", completion = "Champion of Azeroth, I appreciate all the help you've given us.\n\nPlease take these supplies as a token of my  gratitude, and a promise of more to come, should you continue to help." }
WordHunterWoW_QuestEN[54454] = { title = "Supplies from the 7th Legion", description = "<name>, thanks to your efforts against the Horde, our forces have been able to secure additional resources from the battlefield.\n\nThe more you continue to dominate the battlefield the more resources our forces can spare.", objectives = "Speak with Vindicator Jaelaana at Boralus Harbor in Tiragarde Sound.", completion = "<name>, thanks to your efforts against the Horde, our forces have been able to secure additional resources from the battlefield.\n\nThe more you continue to dominate the battlefield the more resources our forces can spare." }
WordHunterWoW_QuestEN[54455] = { title = "Supplies from the Honorbound", description = "<name>, thanks to your efforts against the Alliance, our forces have been able to secure additional resources from the battlefield.\n\nThe more you continue to dominate the battlefield the more resources our forces can spare.", objectives = "Speak with Ransa Greyfeather in the Port of Zandalar for your reward.", completion = "<name>, thanks to your efforts against the Alliance, our forces have been able to secure additional resources from the battlefield.\n\nThe more you continue to dominate the battlefield the more resources our forces can spare." }
