WordHunterWoW_QuestEN[54457] = { title = "Supplies from Storm's Wake", description = "We appreciate all the help you've given us, may the tides watch over you.\n\nPlease take these supplies as a token of our gratitude, and a promise of more to come, should you continue to help us.", objectives = "Speak with Sister Lilyana at Brennadam in Stormsong Valley.", completion = "We appreciate all the help you've given us, may the tides watch over you.\n\nPlease take these supplies as a token of our gratitude, and a promise of more to come, should you continue to help us." }
WordHunterWoW_QuestEN[54458] = { title = "Supplies from the Proudmoore Admiralty", description = "The Proudmoore Admiralty appreciates all the help you've given us.\n\nPlease take these supplies as a token of our gratitude, and a promise of more to come, should you continue to help us.", objectives = "Speak with Provisioner Fray in Boralus Harbor for your reward.", completion = "The Proudmoore Admiralty appreciates all the help you've given us.\n\nPlease take these supplies as a token of our gratitude, and a promise of more to come, should you continue to help us." }
WordHunterWoW_QuestEN[54459] = { title = "He Who Walks in the Light", description = "Shaw reports that Zandalari scouts have been dispatched to alert of our \"full assault\". \n\nWe did it, {name}. The Horde and Zandalari will throw their armies at our forces within Nazmir.\n\nWe cannot let their sacrifice be in vain. We must get back to Boralus and let Halford know it's time to strike.\n\nCome, I'll create a portal for us to leave, once we say one final word to Telaamon.", objectives = "Return to Halford Wyrmbane within Boralus.", completion = "Telaamon's sacrifice will be remembered, but for now, we must move." }
WordHunterWoW_QuestEN[54460] = { title = "Supplies from Talanji's Expedition", description = "Thanks mon, de expedition appreciates all de help you've given us.\n\nTake dese supplies as a token of our thanks, and a promise of more to come, if you continue to help us.", objectives = "Speak with Provisioner Lija at the Zul'jan Ruins for your reward.", completion = "Thanks mon, de expedition appreciates all de help you've given us.\n\nTake dese supplies as a token of our thanks, and a promise of more to come, if you continue to help us." }
