WordHunterWoW_QuestEN[54485] = { title = "Battle of Dazar'alor", description = "Our naval forces are ready to sail for Zuldazar. By the time we're there, the Horde and Zandalari forces should be in Nazmir.\n\nKeeshan and Kelsey checked on the bombs placed within Zuldazar harbor. They're primed and ready to destroy the Zandalari fleet.\n\nGather any of your allies and prepare to set sail for Zuldazar. \n\nWe will strike down the Zandalari and remove the Horde's most powerful ally from this war.", objectives = "Defeat King Rastakhan in the Battle of Dazar'alor raid.", progress = "We must move, there is no more time.", completion = "We have achieved victory, but at a grave cost. Mekkatorque is dead, frozen within a device from his mech.\n\nLady Jaina is being tended to by our best healers. She is badly wounded, but should survive.\n\nAs for Telaamon... our scouts found his body torn to shreds. Every last soldier sent to Nazmir was killed.\n\nBut we did it. The Zandalari fleet is decimated, and King Rastakhan is dead.\n\nOur war with the Horde is almost over. King Anduin will wish to speak with us soon." }
WordHunterWoW_QuestEN[54488] = { title = "Zul'aki the Headhunter", description = "", objectives = "" }
WordHunterWoW_QuestEN[54494] = { title = "Expanding our Influence", description = "As we expand the War Effort on the enemy continent we are finding ideal locations to establish new outposts, and even upgrade our current ones.\n\nOnce secure, these outposts will allow us to utilize a new flight network to quickly and easily navigate the area.", objectives = "Talk to Ransa Greyfeather.", completion = "I have many Scouting Reports and Outpost Upgrades available for you to purchase. These will allow you to unlock new outposts, flight paths and upgrades on both continents.\n\nOnce you have chosen a Scouting Report or Outpost Upgrade, use your Mission Command Table and instruct your troops to complete the mission." }
