WordHunterWoW_QuestEN[54510] = { title = "Mischief Managed", description = "Thank you for returning this artifact to us, {name}. Now that we have the Abyssal Scepter, the fleet can advance without fear of the seas being turned against us.\n\nPlease report our success to High Commander Wyrmbane.", objectives = "Report to High Commander Wyrmbane in Boralus.", completion = "Excellent! The Horde having access to the Abyssal Scepter was a point of concern for us. Now that we've recovered it, not only can we move forward with our final plans, we've once more strengthened our friendship with the Kul Tirans." }
