WordHunterWoW_QuestEN[54518] = { title = "Zero Zeppelins", description = "The Horde zeppelins proved to be problematic for our forces here. I tried to construct something quickly, but while the weapon had power, it didn't have the range necessary to take them out.\n\nThe Lord Admiral has provided us with an expedient solution to the problem!\n\nUse this jury-rigged hand cannon on the zeppelins. A quick application of high energy and heat will cause thermal shock and critical failure!\n\nTo simplify, blow them up while they're grounded!", objectives = "Destroy Horde Zeppelins in Anglepoint Wharf.", progress = "If you could take out those Zeppelins before they can thaw and fly out of range, we'd be assured of victory!", completion = "Ha! The Horde's air forces aren't so superior now, are they?" }
WordHunterWoW_QuestEN[54519] = { title = "Squad Goals", description = "My patrol squad fought off the Horde so Galeheart and I could fly free. I have to stay with the Lord Admiral, so I can't look for them on my own. With any luck, they're out there fighting and waiting for reinforcements.\n\nWell, we're here to help save them. Would you find the rest of my patrol squad for me?", objectives = "Find the members of Taelia's patrol squad.", completion = "They fought like Outriggers when the Horde showed up. True Kul Tiran steel, one and all. \n\nI'll see to it the injured are protected until we can get out and I'll give the able-bodied ones some blades. \n\nI imagine they'll want to repay the Horde for the loss of their friend." }
