WordHunterWoW_QuestEN[54576] = { title = "Gnomeregan's Finest", description = "The leaders of the Alliance have agreed to fund an elite gnomish aerial task force.\n\nAnd you have been chosen to lead the test team for the Gnomish Elite Aerial Rangers. I have assembled some of the finest tinkers and soldiers from Gnomeregan, who are now under your command.\n\nThe three of them are already here in New Tinkertown. Introduce yourself and assemble them.", objectives = "Speak with the three members of your G.E.A.R. team.", progress = "Speak up, soldier!", completion = "Time to give you all your briefing." }
WordHunterWoW_QuestEN[54577] = { title = "Shadowed Halls and Dusty Cogs", description = "An elite aerial unit wouldn't be complete without the newest innovations in flying machine technology.\n\nThere's just one small problem.\n\nThe innovative new engine we built was left behind when we evacuated Gnomeregan. We need that prototype if we want these bombers to safely get off the ground!", objectives = "Find the Prototype Arcane Engine within the Engineering Labs of Gnomeregan.", progress = "Did you find the engine?", completion = "Excellent! I've sent Tinkerbow and Autoblast ahead to prepare for the engine for installation." }
WordHunterWoW_QuestEN[54578] = { title = "Branchlord Aldrus", description = "", objectives = "" }
WordHunterWoW_QuestEN[54579] = { title = "The Gnome Behind the Trogg", description = "If I just attach the core of this to the input module here... Amplify the matched frequency here...\n\n<Tinkerbow mumbles a few more things while she attaches the communication device to the console.>\n\nFlip the switch, Commander! Just make sure it's the right one. The left one is the self-destruct switch. Or was that reversed...", objectives = "Help Tinkerbow get the machine working.", progress = "Yes?", completion = "Give me just a second to trace the origin of the signal..." }
WordHunterWoW_QuestEN[54580] = { title = "A Tundra Conundrum", description = "While you were in Gnomeregan, we received a distress signal from Fizzcrank Airstrip in Borean Tundra. This seems like the perfect opportunity to show off what G.E.A.R. can do!\n\nI've sent the rest of your squad ahead. Meet them out there.", objectives = "Speak with Cog Captain Winklespring at Fizzcrank Airstrip in Borean Tundra.", completion = "Oh, Commander! We arrived shortly before you. The airmen here just finished explaining the situation." }
WordHunterWoW_QuestEN[54581] = { title = "Now With More Mechanical Fowl", description = "The gnomes here report that troggs came down from the north and started attacking everygnome and everything.\n\nSo now it's our job to fix this situation! And luckily, I have the perfect plan for it. We need to calibrate the bomber's gun, and doing so on the ground is much less risky than up in the air.\n\nGive it a go, Commander!", objectives = "Kill 10 Ironbound Brutes or Scrapthrowers." }
WordHunterWoW_QuestEN[54582] = { title = "Smarter Than Your Average Trogg", description = "<Cog Captain Winklespring's voice springs to life over your personal communication system.>\n\nOne of the recon pilots did a scouting run over the station. She reported that there seems to be a trogg on the top level that is larger and smarter than the others. He's somehow managed to get one of the Defendo-Tanks for the station working in his favor.\n\nTake him out!", objectives = "Kill Krugg the Smart.", progress = "Have you found out anything?", completion = "The big trogg was holding this? I think I have an idea..." }
