WordHunterWoW_QuestEN[54610] = { title = "Paragon of the Tortollan Seekers", description = "Your allies among the Tortollan Seekers have requested your presence. They wish to reward you for your continued efforts on their behalf.", objectives = "Speak with Collector Kojo.", completion = "Greetings, Archmage.\n\nFor some time now you have been a paragon in your efforts for the Seekers. Our gratitude goes beyond anything mere words can define.\n\nTake these trophies as a token of our gratitude. The more you aid us, the more we can provide you." }
WordHunterWoW_QuestEN[54611] = { title = "Paragon of the Champions of Azeroth", description = "A grateful Magni Bronzebeard has requested your presence. He wishes to reward you for your exceptional aid.", objectives = "Speak with Magni Bronzebeard in Silithus for your reward.", completion = "Greetings, Archdruid.\n\nFor some time now you have been a paragon in your efforts to aid Azeroth. My gratitude goes beyond anything mere words can define.\n\nTake these trophies as a token of my gratitude. The more you aid Azeroth, the more I can provide you." }
WordHunterWoW_QuestEN[54612] = { title = "Blood and Ashes", description = "", objectives = "" }
WordHunterWoW_QuestEN[54613] = { title = "Twice-Exiled", description = "Elementals of all sorts are bursting free of their bonds across the Highlands.\n\nReturn them to the primordial chaos from whence they came.You will receive:", objectives = "Kill 12 Burning, Cresting, Rumbling, or Thundering Exiles or Guardians in Arathi Highlands." }
WordHunterWoW_QuestEN[54614] = { title = "Executing Exorcisms", description = "Even in death, the Alliance foolishly clings to Horde territory.\n\nDrive their vengeful ghosts from the ruins of Stromgarde before their foulness spreads.You will receive:", objectives = "Kill 12 Vengeful Ghosts in Stromgarde." }
WordHunterWoW_QuestEN[54615] = { title = "The League Will Lose", description = "Even with the fall of Stromgarde, the League of Arathor continues to operate in the Highlands.\n\nThe northern farmland will belong to the Horde. Go, and defeat the humans.You will receive:", objectives = "Kill 12 League of Arathor at Dabyrie's Farmstead." }
WordHunterWoW_QuestEN[54616] = { title = "Boulderfist Beatdown", description = "If the Boulderfist ogres will not join the Horde, there is no place for them in Arathi.\n\nYou know what must be done.You will receive:", objectives = "Kill 12 Boulderfist clan ogres in Arathi Highlands." }
WordHunterWoW_QuestEN[54617] = { title = "Sins of the Syndicate", description = "As if the League of Arathor was not trouble enough, Syndicate agents still slither down from the Alterac mountains to drive off honest Horde laborers.\n\nPunish them.You will receive:", objectives = "Kill 12 Syndicate members at Go'Shek Farm." }
WordHunterWoW_QuestEN[54618] = { title = "Paragon of the 7th Legion", description = "Commanders of the 7th Legion forces have requested your presence.  They wish to reward you for your exceptional efforts.", objectives = "Speak with Vindicator Jaelaana at Boralus Harbor in Tiragarde Sound.", completion = "Huntmaster, thanks to your efforts against the Horde, our forces have been able to secure additional resources from the battlefield.\n\nThe more you continue to dominate the battlefield the more resources our forces can spare." }
WordHunterWoW_QuestEN[54619] = { title = "Wiping Out the Witherbark", description = "The bloodthirsty Witherbark tribe has always refused to join the Horde... and now that the Horde holds Arathi, we will succeed where the Alliance has failed.\n\nDrive the forest trolls from the Highlands.You will receive:", objectives = "Kill 12 Witherbark tribe trolls in Arathi Highlands." }
WordHunterWoW_QuestEN[54620] = { title = "Death to The Defilers", description = "Even with the destruction of Undercity, the Defilers continue to combat our hold on the Arathi Highlands.\n\nThe farmland at Go'Shek will belong to the Alliance once more. Go, and defeat the Forsaken.You will receive:", objectives = "Kill 12 Defilers at Go'Shek Farm." }
WordHunterWoW_QuestEN[54621] = { title = "Twice-Exiled", description = "Elementals of all sorts are bursting free of their bonds across the Highlands.\n\nReturn them to the primordial chaos from whence they came.You will receive:", objectives = "Kill 12 Burning, Cresting, Rumbling, or Thundering Exiles or Guardians in Arathi Highlands." }
WordHunterWoW_QuestEN[54622] = { title = "Executing Exorcisms", description = "Even in death, the Horde foolishly clings to Alliance territory.\n\nDrive their vengeful ghosts from the ruins of Ar'gorok before their foulness spreads.You will receive:", objectives = "Kill 12 Vengeful Ghosts in Ar'gorok." }
WordHunterWoW_QuestEN[54623] = { title = "Boulderfist Beatdown", description = "The Boulderfist ogres have plagued Arathi since the Second War, and they still remain.\n\nYou know what must be done.You will receive:", objectives = "Kill 12 Boulderfist clan ogres in Arathi Highlands." }
WordHunterWoW_QuestEN[54624] = { title = "Sins of the Syndicate", description = "As if the Defilers were not trouble enough, Syndicate agents still slither down from the Alterac mountains to drive off honest Alliance farmers.\n\nPunish them.You will receive:", objectives = "Kill 12 Syndicate members at Dabyrie's Farmstead." }
WordHunterWoW_QuestEN[54625] = { title = "Wiping Out the Witherbark", description = "The Witherbark tribe has a long and bloody history in the highlands of Arathi.\n\nShow them how much bloodier it can get.You will receive:", objectives = "Kill 12 Witherbark tribe trolls in Arathi Highlands." }
WordHunterWoW_QuestEN[54626] = { title = "Paragon of the Honorbound", description = "Commanders of the Honorbound forces have requested your presence.  They wish to reward you for your exceptional efforts.", objectives = "Speak with Ransa Greyfeather in the Port of Zandalar for your reward.", completion = "Huntmaster, thanks to your efforts against the Alliance, our forces have been able to secure additional resources from the battlefield.\n\nThe more you continue to dominate the battlefield the more resources our forces can spare." }
WordHunterWoW_QuestEN[54627] = { title = "Paragon of the Order of Embers", description = "Your allies among the Order of Embers have requested your presence. They wish to reward you for your continued efforts on their behalf.", objectives = "Speak with Quartermaster Alcorn at Arom's Strand in Drustvar.Your allies among the Order of Embers have requested your presence. They wish to reward you for your continued efforts on their behalf." }
WordHunterWoW_QuestEN[54628] = { title = "Paragon of the Storm's Wake", description = "The grateful Storm's Wake forces have requested your presence. They wish to reward you for your continued efforts on their behalf.", objectives = "Speak with Sister Lilyana at Brennadam in Stormsong Valley.", completion = "Greetings, Huntmaster.\n\nFor some time now you have been a paragon in your efforts to aid us. Our gratitude goes beyond anything mere words can define.\n\nTake these trophies as a token of our gratitude. The more you aid us, the more we can provide you." }
WordHunterWoW_QuestEN[54629] = { title = "Paragon of the Proudmoore Admiralty", description = "The grateful leaders of the Proudmoore Admiralty have requested your presence. They wish to reward you for your continued aid to their house.", objectives = "Speak with Provisioner Fray in Boralus Harbor for your reward.", completion = "Greetings, Highlord.\n\nFor some time now you have been a paragon in your efforts for Boralus and the Proudmoore Admiralty. Our gratitude goes beyond anything mere words can define.\n\nTake these trophies as a token of our gratitude. The more you aid us, the more we can provide you." }
WordHunterWoW_QuestEN[54630] = { title = "Paragon of Talanji's Expedition", description = "Your allies among Talanji's Expedition have requested your presence. They wish to reward you for your continued efforts on their behalf.", objectives = "Speak with Provisioner Lija at the Zul'jan Ruins for your reward.", completion = "Hello, Archdruid.\n\nFor some time now you've been a paragon in your efforts for de Expedition. Our gratitude goes beyond what mere words of thanks can offer.\n\nTake dese trophies as a token of our appreciation. De more you aid us, de more we can provide you." }
WordHunterWoW_QuestEN[54631] = { title = "Paragon of the Voldunai", description = "Your allies among the Voldunai have requested your presence. They wish to reward you for your continued efforts on their behalf.", objectives = "Speak with Hoarder Jena at the Vulpera Hideaway for your reward.", completion = "Greetings, Archdruid.\n\nFor some time now you have been a paragon in your efforts to support the Voldunai. Our gratitude goes beyond anything mere words can define.\n\nTake these trophies as a token of our gratitude. The more you aid us, the more we can provide you." }
WordHunterWoW_QuestEN[54632] = { title = "Paragon of the Zandalari Empire", description = "The grateful leaders of the Zandalari Empire have requested your presence. They wish to reward you for your exceptional aid.", objectives = "Speak with Natal'hakata in Dazar'Alor for your reward.", completion = "Greetings, Farseer.\n\nFor some time now you have been a paragon in your efforts to aid de Zandalari Empire. Our gratitude goes beyond what mere words of thanks can offer.\n\nTake dese trophies as a token of our appreciation. De more you aid us, de more we can provide you." }
WordHunterWoW_QuestEN[54635] = { title = "Mekkatorque's Battle Plans", description = "So we almost got everythin' we need, except for where that airship went!\n\nMy insurance pals found out where they're hidin' that primo-info. \n\nGo and get me Mekkatorque's battle plans, then we can begin the REALLY fun part!", objectives = "Recover Mekkatorque's Battle Plans", progress = "You get me that thing yet?", completion = "This is perfect! Let's blow us up that annoying mook." }
WordHunterWoW_QuestEN[54636] = { title = "Sandbinder Sodir", description = "", objectives = "" }
WordHunterWoW_QuestEN[54638] = { title = "Beat Up the Drums", description = "", objectives = "" }
WordHunterWoW_QuestEN[54639] = { title = "A Signal in Storm Peaks", description = "It looks like the signal is being transmitted from Storm Peaks. \n\nTime to put these flying machines to work! I'll keep tracking the signal en route in order to get a cleaner read.", objectives = "Fly with your squadron to Storm Peaks.", progress = "Need something, Commander?", completion = "I've set up a cloaking device that will cover our current location. We should be safe for now." }
WordHunterWoW_QuestEN[54640] = { title = "Gnomercy!", description = "We need to give Tinkerbow some cover while she figures out our new trajectory.\n\n<The Cog Captain hands you a miniature spider tank.>\n\nIt may not look like much, but this is a fully functional spider tank. You'll just need to de-shrinkify it. Use it to distract the troggs down below by thinning their numbers.", objectives = "De-shrinkify the Assault Tank and use it to slay troggs.", progress = "Give those troggs something to worry about, Captain!", completion = "Glad you found your way here safely, Commander!" }
WordHunterWoW_QuestEN[54641] = { title = "For Gnomeregan!", description = "It's time to bring down Sparkspanner, Commander.\n\nJust give me the word, and I'll turn this machine straight towards the Halls of Stone!", objectives = "Enter the Halls of Stone and defeat Telzo Sparkspanner.", progress = "Sparkspanner needs to be defeated, for the sake of all Gnomanity.", completion = "Is everyone alright? Our tinker can set up a Medic Bot if necessary." }
WordHunterWoW_QuestEN[54642] = { title = "G.E.A.R. Up", description = "That was a close one, but we managed to defeat Sparkspanner! Gnomanity and Azeroth are saved from a threat they didn't even know about.\n\nHopefully, that's the last time we'll hear from any of Thermaplugg's old goons.\n\nWe should return to Captain Sparknozzle. He will want a full report.", objectives = "Return to Captain Tread Sparknozzle in New Tinkertown.", completion = "At attention, soldier!" }
WordHunterWoW_QuestEN[54643] = { title = "Evezon the Eternal", description = "", objectives = "" }
WordHunterWoW_QuestEN[54644] = { title = "Azerite Transport", description = "", objectives = "" }
