WordHunterWoW_QuestEN[54650] = { title = "Muk'luk", description = "", objectives = "" }
WordHunterWoW_QuestEN[54652] = { title = "The War Chest", description = "Welcome to the warfront, {name}. I am glad we have you fighting on our side.\n\nFirst things first: We need to collect resources in order to strengthen our hold on Bashal'Aran and bolster our troops.\n\nAny resources that we collect will go to the War Chest. Open the chest and see what you can use.", objectives = "Collect resources from the War Chest in Bashal'Aran.", progress = "Have you collected those resources from the War Chest?", completion = "Good. Now we can get down to business." }
WordHunterWoW_QuestEN[54654] = { title = "An Explosive Situation", description = "We have some iron available, but we could always use more.\n\nGet down to the mine at the Ruins of Lornesta. Seize it from any enemies, and get those goblins to do their job.\n\nGiving them something suitably destructive should do the trick.", objectives = "Supply Goblin Extractors with explosives at Lornesta Mine.", progress = "We need more iron if we want to win this battle!", completion = "I can hear the explosive productivity. Well done." }
WordHunterWoW_QuestEN[54655] = { title = "Lumbering Along", description = "We will need more lumber if we're going to build up Bashal'Aran into a proper fortress.\n\nYou should find an axe in the supplies we brought in for the effort. Grab it, and see what you can do with it to help us get our base rebuilt.", objectives = "Pick up a Sturdy Axe, then gather 5 Freshly-Chopped Wood from the nearby Darkwood Timber.", progress = "We need that wood to accomplish our goals here.", completion = "I thought I smelled fresh sawdust. This wood will go a long way toward building our forces here." }
WordHunterWoW_QuestEN[54656] = { title = "Darkshore Recruits", description = "We will not win unless we have the power of numbers on our side.\n\nFirst, we need the Barracks restored so Signe can do her work. Signe is one of the Dark Lady's val'kyr, and she can raise forces for us.\n\nOnce the Barracks is built, talk to Signe and recruit a troop. I'm sure they could learn a lot from fighting alongside you.", objectives = "Restore the Barracks, then speak with Signe to recruit an ally.", progress = "Have you recruited those troops?", completion = "Some of these recruits are a little... fresher than others." }
WordHunterWoW_QuestEN[54657] = { title = "Arms and Armor", description = "Keever knows troops need weapons. And armor. Armor and weapons. \n\nKeever wants Archibald to make armor and weapons for troops. You listen to Keever and talk to Archibald.", objectives = "Speak with Archibald to learn what the Armory has to offer.", progress = "We are a long way from the Undercity, yet here is where I belong.", completion = "Keever would like fancy new armor and weapons." }
WordHunterWoW_QuestEN[54658] = { title = "The Altar of Storms", description = "The Altar of Storms has been rebuilt. It is a unique kind of altar. The goblin kind.\n\nKeever is pleased. Keever wishes to wield that kind of power.\n\nGo, listen to Keever, talk to little goblin Mizzyk and find what the Altar can do.", objectives = "Speak with Mizzyk to learn what the Altar of Storms has to offer.", progress = "Keever wonders if you have seen the Altar of Storms yet.", completion = "Keever knows that with this great power, you will do responsible things.\n\nKeever knows." }
WordHunterWoW_QuestEN[54659] = { title = "An Alchemist for Everything", description = "When we first conquered Darkshore, we set up an Alchemy Lab on the shore at Gloomtide Strand to tap into this area's latent power.\n\nUnfortunately, things did not go so well and the Alliance have overrun the lab.\n\nWould you see them off, and then speak with Professor Blightwell to see what he can do for you?", objectives = "Capture Gloomtide Strand, then speak with Professor Blightwell to learn what he has to offer.", progress = "Did you find anything at Gloomtide Strand?", completion = "We Apothecaries know what we're doing, believe me. Between us we've written loads of treatises on the theory of what can be accomplished with just a few pounds of flesh." }
WordHunterWoW_QuestEN[54660] = { title = "Throwing Blight", description = "We need more firepower, and the goblins are oh so obliging, aren't they. Zarvik in particular has honed his craft ever since our conquest of Darkshore.\n\nWhy don't you talk to him and see what he's got going at the Workshop?", objectives = "Speak with Zarvik Blastwix to learn what the Workshop has to offer.", progress = "You got anything you need built?", completion = "Those Blight Throwers are sure to take down those Ancients in no time." }
WordHunterWoW_QuestEN[54661] = { title = "Echolocation", description = "Glad you're here! These bats have got to get up and start giving us some more air support.\n\nI've got a draft of a flight plan here in Darkshore. It's helped by the fact that our bats can see in the dark, when most of us can't.\n\nTalk to Avery and she'll make sure you get safely back to Bashal'Aran.", objectives = "Deliver Crankshot's Note to your commander in Bashal'Aran.", completion = "Well done. These bats will help us win the battle of the skies." }
