WordHunterWoW_QuestEN[54682] = { title = "The Missing Blade", description = "<The echo of the blade Xal'atath lingers before you. Though the consciousness that resided within the dagger is gone, the place it once occupied still resonates with power.\n\nYou sense the weapon now speaks another voice. Another purpose....\n\nYou feel compelled to warn the king that the blade may now reside in the hands of the enemy.>", objectives = "Inform King Anduin about the absence of Xal'atath.", completion = "<You tell Anduin about Xal'atath and N'Zoth. His expression darkens.>\n\nThis is grim news, champion.\n\nThe Alliance stands on the threshold of victory. If the Banshee Queen has learned of a new weapon, she will use it to keep the war going indefinitely." }
WordHunterWoW_QuestEN[54683] = { title = "The Black Blade", description = "<The blade that was known as Xal'atath rests on the ground before you. Though the consciousness that resided within the dagger is gone, it still resonates with power.\n\nAlmost as if the weapon speaks with another voice. Another purpose....\n\nYou feel a compulsion to bring this artifact to the warchief.>", objectives = "Bring the Dagger to Warchief Sylvanas Windrunner.", completion = "<As you present the dagger to Sylvanas, a faint smile curls her lips. For the briefest moment, it seems her eyes darken. A trick of the light, no doubt.>\n\nOnce again, you have proven yourself a worthy champion, <name>. This blade is the compass that will guide us to victory." }
