WordHunterWoW_QuestEN[54703] = { title = "Express Delivery", description = "The Horde appears to have misplaced some of its Azerite. It would be rude of us not to return it, don't you think?\n\nThe most efficient way is for me to teleport it back.\n\nI've enchanted the harpoons in that launcher over there. Fire them onto the Horde ships in the bay. I can use them as beacons to return the Azerite to the Horde... and send its ships on their way.", objectives = "Mark locations on the Horde ships to direct Jaina's spell.", progress = "Well done, <name>.", completion = "It appears as if the fleet won't be needed for much more than hauling wreckage out of the bay.\n\nThank you for helping me to save my people before more could be killed by the Horde. Our foes are growing bolder. Clearly, we need to strike back. Kul Tiras will fight beside the Alliance when we do." }
WordHunterWoW_QuestEN[54706] = { title = "Made in Kul Tiras", description = "Are you curious about how the Kul Tirans joined the Alliance? \n\nIt was assumed that Kul Tiras would rejoin the Alliance after everything that was done to stabilize their nation.\n\nLady Jaina Proudmoore wanted to cement the allegiance by building King Anduin a ship worthy of the Kul Tiran navy.\n\nShe wished for help in finding the best shipwright in Kul Tiras, Dorian Atwater. It wouldn't be easy, as Dorian was retired.\n\nIt all began with a trip to see Cyrus in Boralus Harbor...", objectives = "Speak to Cyrus in Boralus Harbor.", progress = "Yes?", completion = "I may be able to help you find this shipwright, <name>." }
WordHunterWoW_QuestEN[54707] = { title = "Siegeotron", description = "", objectives = "" }
WordHunterWoW_QuestEN[54708] = { title = "Home, Home On the Range", description = "<Cyrus peruses a map.>\n\nHmm... Along the road to Fort Daelin... to the north... somewhere in the Deadwash.\n\n<He points to a section of road on the map.>\n\nI've marked a spot on your map that seems likely. I think that will get you close enough. \n\nI'll report back to the Lord Admiral with what we've learned. Good luck, and I hope our shipwright is willing.", objectives = "Track down the shipwright in Stormsong Valley and deliver the Lord Admiral's Letter.", progress = "Now what's this?", completion = "<Dorian takes her time to read over the letter. Her brows steadily rise.>" }
WordHunterWoW_QuestEN[54709] = { title = "Candy Bucket", description = "", objectives = "Candy buckets like this are located in inns throughout the realms. Go ahead... take some!" }
WordHunterWoW_QuestEN[54710] = { title = "Candy Bucket", description = "", objectives = "Candy buckets like this are located in inns throughout the realms. Go ahead... take some!" }
WordHunterWoW_QuestEN[54711] = { title = "Zillie Wunderwrench and Grizzwald", description = "", objectives = "" }
WordHunterWoW_QuestEN[54712] = { title = "Spell Components", description = "", objectives = "" }
WordHunterWoW_QuestEN[54719] = { title = "Worgen in the Ore Mine", description = "", objectives = "" }
WordHunterWoW_QuestEN[54721] = { title = "I'm Too Old for This Ship", description = "If I understood this correctly, the Lord Admiral of the Kul Tiran navy wants me to come out of retirement specifically to build a ship for the king of Stormwind.\n\nCan't say I've had THAT request before.\n\n<Dorian leans back in her chair for a moment and rubs at her eyes.>\n\nI'm getting too old for this nonsense.\n\n<Dorian heaves a long sigh.>\n\nGo on out back and saddle Hurricane for me while I pack my things. We will meet you at Port Fogtide.\n\nWe're going to need a slip.", objectives = "Saddle Hurricane and meet Dorian Atwater at Port Fogtide.", progress = "I don't go anywhere without my horse, <name>.", completion = "Well. This complicates things a touch." }
WordHunterWoW_QuestEN[54722] = { title = "Turning the Tides", description = "", objectives = "" }
WordHunterWoW_QuestEN[54723] = { title = "Covering Our Masts", description = "When I was younger, I hid my ships out of vanity.\n\nI often went through a number of designs before I was satisfied. I didn't want anyone to see that. It might ruin the mystique, I reasoned.\n\nNow... I think it best to hide this ship from the likes of those tentacle-faced creeps. I don't think they intend to let us build unchallenged.\n\nGo into the port and place my wards around the main slip. \n\nYou'll see what they do.", objectives = "Place 3 Fog Wards in Port Fogtide.", progress = "Did you place the wards?", completion = "That should give us some cover. Hopefully they stay away long enough to finish construction." }
WordHunterWoW_QuestEN[54724] = { title = "Ending the Blackwood", description = "", objectives = "" }
WordHunterWoW_QuestEN[54725] = { title = "The Deep Ones", description = "I've spent my whole life on and around the sea. \n\nUntil very recently I feel like I've always had one foot in the water. I knew there were... things... best left untouched.\n\nNow they're here. In Stormsong Valley. Occupying the slip I need to build your ship.\n\nDo I really need to tell you what to do about it?", objectives = "Slay 12 drowned forces in Port Fogtide.", progress = "I never thought I would see such things in the flesh. Have you dealt with them?", completion = "All this gives me the shivers, <name>." }
WordHunterWoW_QuestEN[54726] = { title = "Frame Work", description = "Now that I have a slip to work in, I'm going to need lumber.\n\nLots of lumber.\n\nThe only lumber mill that could handle this kind of volume at such short notice would be the Algerson Lumber Yard outside of Boralus.\n\nI know this because I've made this exact request of them before.\n\nI will meet you there. Algerson might need a little persuasion.", objectives = "Meet Dorian Atwater at the Algerson Lumber Yard in Tiragarde Sound.", completion = "I overestimated Algerson's usefulness here, but don't worry. I have a plan." }
WordHunterWoW_QuestEN[54727] = { title = "Team Carry", description = "Algerson is about as useful as a legless horse. We're going to do this ourselves.\n\nThe mill is overrun with bizarre creatures. I'll handle those. You and these hearty volunteers will need to be the muscle of this operation.\n\nDon't look at me like that, {class}. It's just a little lifting.\n\nOnce we have enough lumber, Sal will meet us for a pick up. Just stay close to me and focus on not dropping my wood, yes?", objectives = "Collect 4 heavy lumber and take it to the drop-off point.", completion = "Why are you all sweaty?" }
WordHunterWoW_QuestEN[54728] = { title = "This Lumber is Haunted", description = "I don't much believe in ghosts, or hauntings for that matter.\n\nThat said, there is something wrong with this lumber. I can feel it in my bones. They're achier than normal.\n\nI only know of one group that would know what to do. They're reclusive, but we share a love of nature.\n\nSeek out Thornspeaker Birchgrove in Drustvar. I trust no one else with this.", objectives = "Seek out Thornspeaker Birchgrove in Gol Koval.", progress = "There's a deep rend in the balance, and it is centered on you. Curious.", completion = "Ah, I see... this is the source of that wrongness I felt.\n\nThis is troubling indeed, <name>." }
WordHunterWoW_QuestEN[54729] = { title = "The Bleak Hills", description = "While you are visiting Drustvar, I need you to run another errand for me.\n\nThe Wright family owned a mine up near Corlain. Years past, they supplied all the metal ore I used to build my ships.\n\nI can't imagine they're faring too well, based on what we've seen here.\n\nFind Chelsea Wright, the foreman's daughter, and see what they need to get another ore shipment together.\n\nJust tell her Dorian sent you.", objectives = "Find Chelsea Wright at the Bleak Hills Mine in Drustvar.", completion = "Boy, am I glad to see you. I thought that beast was going to eat me alive!" }
WordHunterWoW_QuestEN[54730] = { title = "Gorak Tul's Influence", description = "Long have the Thornspeakers struggled against such magics. It is a conflict as old as the Drust themselves.\n\nGorak Tul's influence, however, has vastly shifted the balance toward that of decay and death. It corrupts what would be an ordinary curse.\n\nI believe Ulfar can correct this.\n\nGo into Gol Koval. Slay our enemies, destroy their cairns, and collect their magics into this vessel.\n\nWith it, Ulfar may be able to find a way to cleanse your materials.", objectives = "Fill the Drust Vessel in Gol Koval by killing enemies and destroying cairns.", progress = "Be careful, <name>. Drust magic is older than most things that are, and older than some that were.", completion = "The concentration chills me to my bones, but it will be needed. We must hurry before the corruption can touch you." }
WordHunterWoW_QuestEN[54731] = { title = "Balance in All Things", description = "The confluence of energies around that vessel is truly disturbing. My skin crawls with the wrongness of it.\n\nWe have reached the limit of my ability to help you, {name}.\n\nGo to Ulfar, the High Thornspeaker. Arthur will carry you, if you wish it.\n\nOnly he knows enough about these ancient magics to undo the corruption that taints your materials.\n\nGo quickly. You do not want to hold that vessel longer than you must.", objectives = "Speak to Ulfar and cleanse the Filled Drust Vessel.", progress = "I sense a terrible power emanating from that vessel, <name>.", completion = "We will take what we have learned here and see what can be done about the rest of Drustvar.\n\nFor now, the Drust Vessel will be of use to you and Dorian.\n\nGive her my regards. She is an ally to the Thornspeakers, always." }
WordHunterWoW_QuestEN[54732] = { title = "Drop It!", description = "You must be the person Dorian sent to collect the ore.\n\nI got a message a short while ago requesting a rather large shipment, which in itself is a feat given the state of this place. I was on my way to our storehouse when that... beast!... cornered me.\n\nIt took my keys. I can't get you that shipment without them. Find out where that mongrel took them and bring them back.\n\nLet it be known I wouldn't do this for anyone else.", objectives = "Retrieve Chelsea Wright's keys.", progress = "<The Wicker Beast stares blankly at you.>", completion = "<The Wicker Beast sniffs the key.>" }
WordHunterWoW_QuestEN[54733] = { title = "Make it Wright", description = "<Chelsea stares in horror at the Wicker Beast.>\n\nI don't know how this happened, or why... but I know this beast. \n\n<Chelsea hastily wipes away a tear.>\n\nI've unlocked our storage chest. Thank you. Thank you so much.\n\nTell Dorian she can call upon us at any time.", objectives = "Collect Dorian's ore shipment.", completion = "A note is affixed to the chest.\n\nIt reads:\n\n\"Dorian-\n\nThe mine has been in a bad way of late, but you will be glad to know that our standards remain as high as ever. \n\nGive Sal our best,\n\nChelsea W.\nWright & Co.\"" }
WordHunterWoW_QuestEN[54734] = { title = "Summons from Dorian", description = "<The elemental has a piece of parchment whipping around madly inside its tornado.>\n\nHHsssssss.\n\n<The elemental ejects the page into your face.>\n\nHHHHSSSSSSsssshh.", objectives = "Return to Dorian Atwater at Port Fogtide.", progress = "I see my little helper found you just fine.", completion = "I'm not fond of nobles sticking their nose in my work before it's finished. Deal with this." }
WordHunterWoW_QuestEN[54735] = { title = "A Worthy Crew", description = "If Dorian really can build this ship before the day is out, we need to find a crew for the new vessel.\n\nThis crew should represent the best of Kul Tiran society, the highest naval prowess, and the faith of our people as we present this gift to Anduin.\n\nI have a captain in mind, but you'll want to speak to him yourself. I will let him decide who else he wants aboard.\n\nSeek out my brother, Tandred Proudmoore, in Boralus. He will help you fill out the ranks from there.", objectives = "Recruit a crew for the new vessel.", progress = "Have you found a suitable crew?", completion = "This is a fine group you've assembled. Very well done." }
