WordHunterWoW_QuestEN[54751] = { title = "Soggy Page", description = "", objectives = "Yes? What is it?", progress = "Yes? What is it?", completion = "Ah, another waterlogged page, excellent. I will add it to the pile to dry.\n\nThese scrolls seem to tell the tale of an ancient wanderer, who travelled a lush jungle full of danger.\n\nI would very much like to see some of the creatures depicted therein. Someday, perhaps.\n\nI have also been finding many duplicate pages. I ask myself, how can this be? And yet, here, again, we find page nine.\n\nWill you let me know if someone needs page nine?" }
WordHunterWoW_QuestEN[54754] = { title = "For the Queen", description = "<You chose not to side with the traitor Saurfang and his troll lackey.\n\nNow that you know where Saurfang is, and who is with him, you should report to Sylvanas to see if she has any further orders.>", objectives = "Meet with Lady Sylvanas Windrunner in Orgrimmar.", completion = "Your loyalty will not go unrewarded, champion. Lyana departed here only moments ago.\n\nI have dispatched the dark ranger and a contingent of loyal deathguard to apprehend the traitor Saurfang in Swamp of Sorrows.\n\nHe may come peacefully, or he may not. Your hands should not, in any case, be bloodied in this confrontation. You are to remain a hero, golden in the eyes of the people, as we have need of.\n\nAnd as for that troll you mentioned, I have special plans for him." }
WordHunterWoW_QuestEN[54755] = { title = "Not My Table", description = "<You have decided to neither follow Zekhan to Swamp of Sorrows, nor report this event back to Sylvanas.\n\nInstead, you find yourself longing to spend a sun-soaked afternoon relaxing, and you know just the spot.\n\nSometimes, it's nice to let others take care of things.>", objectives = "Head to the Steam Pools, obtain a burger and a beverage, and lay out in the sun.<You have decided to neither follow Zekhan to Swamp of Sorrows, nor report this event back to Sylvanas.\n\nInstead, you find yourself longing to spend a sun-soaked afternoon relaxing, and you know just the spot.\n\nSometimes, it's nice to let others take care of things.>You will receive:\n\nUpon completion of this quest you will gain:" }
WordHunterWoW_QuestEN[54756] = { title = "Garbage for the Garbage God", description = "Richmon, you found a thing I been looking for for a long time. Bring it to me in the Port of Zandalar, and I will grant you my favor.", objectives = "Bring Jani's First Offering to Jani's Trashpile in the Port of Zandalar.\n\nProvided item:", completion = "I remember da orphan who first carved dis offering. I remember da tears and desperation and da hope for somethin' to save dem. I remember tastin' da power in dat hope.\n\nAnd I remember da look of fear on da cruel richmon who made da child cry. \"Never again\" not just be hollow words with Jani." }
WordHunterWoW_QuestEN[54757] = { title = "The Loa of Scavengers", description = "Richmon, you bring me many shiny things. You helped some of those that no one else would. And ya dumb enough to keep comin' back to me trash piles.\n\nI like ya style.\n\nNow for da big one. Go to the steps of Dazar'alor, and find the Chronicler Ash'tari. Her chisel makes da shrines there. Tell her to build me a shrine and I will grant you my boon.\n\nUnlike the flappy Pa'ku or running Gonk, I just gonna let ya scrap your trash in my pile and I'll give ya stuff back. Anywhere my trash piles be.", objectives = "Speak with Chronicler Ash'tari at Dazar'alor.", completion = "Well, I don't have any extra statues to Jani lying around. It is not as if that... thing... has ever asked for one before. How about I just clear a spot to throw trash down on our sacred shrines?\n\nAre you sure this is not a prank? \n\nFine! But just know that if you want to put a proper loa's statue back up, speak to me." }
WordHunterWoW_QuestEN[54759] = { title = "When Spirits Whisper", description = "Ah, {name}! I have a message for you.\n\nBaine Bloodhoof asks that you join him in Thunder Bluff at once.\n\nI suggest you hurry.", objectives = "Meet with Baine Bloodhoof in Thunder Bluff.", completion = "Greetings, <name>. I am pleased you have answered my call." }
WordHunterWoW_QuestEN[54760] = { title = "The Spiritwalkers", description = "As you know, the spiritwalkers commune with our ancestors and maintain balance within the spirit realm. It is a sacred duty that links our present to our past.\n\nBut lately the spiritwalkers have been troubled by visions of chaos and turmoil. Of a rising darkness.\n\nThey tell me that the spirits have whispered your name. We are unsure why, but Spiritwalker Ussoh means to find out.\n\nSeek Ussoh on Fargaze Mesa to the south. Good luck, {name}. I believe you may need it.", objectives = "Speak with Spiritwalker Ussoh at Fargaze Mesa in Camp Narache.", completion = "Hmph. I expected you sooner. \n\nNo matter. Have a seat." }
WordHunterWoW_QuestEN[54761] = { title = "Spirit Guide", description = "The ancestors have whispered your name, {name}. Now it is time for you to reach out to them.\n\nHere in this sacred place, we spiritwalkers commune with those who came before us. Sit within the circle and light the incense.\n\nIf you open your heart, a spirit guide will present itself to you. Let us hope it will lead you to the answers we seek.", objectives = "Light the Spiritwalker's Incense at Fargaze Mesa in Camp Narache.", progress = "Have you found your guide?", completion = "What did you see?" }
WordHunterWoW_QuestEN[54762] = { title = "A Small Retreat", description = "I believe your guide was delivering a warning. The unrest within the spirit realm may be even more dire than first feared.\n\nWe must cross over at once, from a place with a strong bond to the spirit realm.\n\nIn ages past, tauren made pilgrimages to Sun Rock Retreat to engage in such a ritual. It is said that long ago, An'she himself kissed the mountain where the retreat now stands.\n\nMeet me there and we will begin the crossing.", objectives = "Meet with Spiritwalker Ussoh at Sun Rock Retreat in Stonetalon Mountains.", completion = "Shall we begin?" }
WordHunterWoW_QuestEN[54763] = { title = "Crossing Over", description = "We are ready to begin. \n\nYou will be crossing into the spirit realm. Take caution, for it can be a place of both tranquility and danger.\n\nMake contact with your spirit guide. There must be a reason it was in pain when it revealed itself to you.\n\nWhen you are ready, raise this vessel to enter the spirit realm.", objectives = "Enter the spirit realm and make contact with your spirit guide.", progress = "Are you ready to enter the spirit realm?", completion = "Your guide is a chieftain ancestor? That is a great honor.\n\nBut if your guide was under attack, then I fear balance has been lost." }
WordHunterWoW_QuestEN[54764] = { title = "Storm in Bloodhoof", description = "This is worse than I feared.\n\nThe people of Bloodhoof Village are in grave danger. Even the brave young tauren who train there are woefully unprepared for the danger that is coming.\n\nDo what you can to stop this threat. I will go to Thunder Bluff to warn the High Chieftain.", objectives = "Travel to Bloodhoof Village in Mulgore and stop the spirit attack.", completion = "You heard the horn, <name>! We are in dire need of your help." }
WordHunterWoW_QuestEN[54765] = { title = "Thank Your Guide", description = "The balance has been restored, and Thunder Bluff is safe. Thank you.\n\nWe owe our victory to your spirit's guidance. We must honor the old ways by giving thanks to the ones who came before us.\n\nTo the southwest lies a beautiful vista where my father once took me. It would be a fitting place to reflect upon all that has transpired.\n\nPlease take this offering there to honor our ancestors.", objectives = "Deliver the offering to your spirit guide on the cliffs southwest of Thunder Bluff.", completion = "<You find a set of traditional <race> vestments and a ceremonial totem.>" }
WordHunterWoW_QuestEN[54766] = { title = "Answer the Call", description = "It is fortunate that Spiritwalker Ussoh passed along your spirit guide's warning. We were able to evacuate most of the citizens.\n\nThis cursed spirit is full of malevolence and hatred. It must be destroyed, {name}!\n\nWe attack on your command.", objectives = "Stop the Malevolent Spirit.", completion = "You have saved Thunder Bluff, <class>. However, The spirit realm is growing more restless and balance is tipping. We have restored it for now. But how long until the scales are moved again and what is causing it?\n\nI do not have those answers, but I do have another favor to ask." }
WordHunterWoW_QuestEN[54781] = { title = "What's For Lunch?", description = "My Shadowtrade Mercenaries will fight for Stormarion Cores, no questions asked, but they do get hungry also!\n\nFood is quite scarce here, so we need supplies!\n\nTake a mercenary out with you and find some food for them to eat. I'll make it worth your while!", objectives = "Repel the Hordes forces assaulting Tiragarde Sound." }
