WordHunterWoW_QuestEN[54787] = { title = "Masking For a Friend", description = "The Outriggers have fought some pretty tough monsters and Horde savages aren't so much different. The Blight Specialists they brought weren't especially tough, but they were the most dangerous.\n\nKill a few of them and bring back their face masks. Okri can work his mechanical wizardry and build us better masks of our own in case any Horde scum dare show their blight-spreading faces around here again.", objectives = "Collect 4 Blight Specialist Masks.", progress = "Did you get rid of those blighted wretches?", completion = "Thank you, mainlander. I'm sure Okri can make us some top-notch gear with these." }
