WordHunterWoW_QuestEN[54843] = { title = "Remaining Threats", description = "Though our forces maintain a steady hold on Darkshore, this land still festers with enemies at every turn.\n\nDo what you can to keep them at bay, and you will be well rewarded.", objectives = "Defeat 12 rare enemies in Darkshore.", progress = "Is the deed done?", completion = "Excellent. \n\nNone will stand in our way!" }
WordHunterWoW_QuestEN[54844] = { title = "Tapping the Breach", description = "Darkshore is home to several elemental breaches which hold massive amounts of power. \n\nThe remnants of the Twilight's Hammer know this. While we were preoccupied with the Kaldorei, their elementalists have moved to exploit these locations of power, calling forth massive elementals to do their bidding.\n\nTheir actions must not go unchecked.", objectives = "Defeat 20 Twilight elementalists in Darkshore.", progress = "What of the cultist threat?", completion = "These cultists simply don't know when to give up, do they? I hope this is the last we see of them.\n\nWell done, <class>." }
WordHunterWoW_QuestEN[54845] = { title = "Buzzkill", description = "Some gnome's been goin about planting these strange machines in the woods here. I don't know what they do, but I'll be dead before I let gnomish machines sully goblin territory!\n\nFind these \"buzzboxes\" and reduce them to scrap. I'll make sure you're compensated for your troubles.", objectives = "Destroy 4 Buzzboxes in Darkshore.", progress = "Did you take care of our gnomish problem?", completion = "Thanks for the assist there, pal.\n\nIf you ask me, the only place gnomish technology belongs is the scrap heap!" }
WordHunterWoW_QuestEN[54850] = { title = "Operation: Troggageddon", description = "Tinkerbow has finished installing the guns on our flying machines, so it's time to give them a trial by fire. We've got confirmation that our target is in fact within the Halls of Stone.\n\nLet's start clearing out the forces out in front. We'll take the earliest opportunity to bring the fight to Sparkspanner!", objectives = "Clear out Sparkspanner's army." }
WordHunterWoW_QuestEN[54851] = { title = "Blessing of the Tides", description = "Dorian certainly lives up to her reputation, {name}.\n\nThis magnificent vessel is complete and now it has a crew. Two pieces remain.\n\nFirst, we must give the ship a name.\n\nThen it falls to Brother Pike to bless this vessel. As is tradition, a tidesage's blessing fortifies the ship against storms and encourages fair weather and smooth seas. It is as much ceremonial as it is practical.\n\nOnce that is done, we will set sail for Stormwind.", objectives = "Choose a name for the new vessel, then witness Brother Pike's blessing.", progress = "I chose you for this honor to thank you for all you have done for my people, and all that you have done for me.", completion = "It has been so long since I have seen such a rite performed. I was only a child.\n\nIt means a great deal to me to have had your help in this. Thank you." }
WordHunterWoW_QuestEN[54856] = { title = "Bilgewater Bandits", description = "", objectives = "" }
WordHunterWoW_QuestEN[54857] = { title = "Turning the Tides", description = "", objectives = "" }
WordHunterWoW_QuestEN[54858] = { title = "Glaive Consequences", description = "", objectives = "" }
WordHunterWoW_QuestEN[54871] = { title = "We Are Coming", description = "We must press our advantage before the Horde can further its hold on Darkshore.\n\nThe kaldorei stand ready to fight for our home, and the Gilneans stand alongside us.\n\nWe will show our enemies our fury. They will learn to fear us.\n\nRally any you can. We march at once.", objectives = "Inform Ralston Karn to prepare for the assault on Darkshore.", completion = "I will call anyone with the will to fight as soon as our supplies are in order!" }
WordHunterWoW_QuestEN[54875] = { title = "Remaining Threats", description = "We have managed to route the Horde presence in Darkshore, but several threats remain throughout the countryside.\n\nIf we wish to hold this land, they must be eliminated.", objectives = "Defeat 12 rare enemies in Darkshore.", progress = "How's your progress?", completion = "You have strengthened our position and brought some measure of safety to the people of Darkshore\n\nYou have my thanks." }
WordHunterWoW_QuestEN[54876] = { title = "Tapping the Breach", description = "We had thought the Twilight's Hammer's presence in Darkshore was snuffed out with the defeat of Deathwing. Apparently, we were mistaken.\n\nRemnants of their cult have used the conflict in Darkshore as an opportunity to re-establish their presence here. Darkshore is home to several breaches of elemental power, and it looks like they aim to use these to unleash powerful elementals to devastate the land.\n\nThis must not stand.", objectives = "Defeat 20 Twilight elementalists in Darkshore.", completion = "You have saved countless lives today. For this I am greatful.\n\nStill, I'm afraid this won't be the last we will see of the Twilight's Hammer. We must be ever vigilant." }
WordHunterWoW_QuestEN[54878] = { title = "Buzzkill", description = "Some nefarious no-goodnik is tampering with my Buzzboxes!\n\nI've been trying to get the Buzzbox network back online since we were able to drive the Horde out of Darkshore, but I'm getting no reading from boxes 456, 627, 111, and 854!  I'd be willing to bet that some stragglers from the Bilgewater Cartel are to blame!\n\nSee if you can get those Buzzboxes back online, will you? We'll need their readings if we ever want to permanently fix the corruption problem here.", objectives = "Repair 4 Buzzboxes in Darkshore.", completion = "You did it! The Buzzbox network is back online!\n\nNow, if I can only remember the passcode to this thing we'll be in business!" }
