WordHunterWoW_QuestEN[55084] = { title = "Blueprint: Encrypted Black Market Radio", description = "<This blueprint details how to build what appears to be a highly encrypted radio transmitter.\n\nYou should be able to upload the blueprint to Pascal-K1N6's database in Rustbolt.>", objectives = "Upload the blueprint to Pascal-K1N6's database.\n\nProvided item:", completion = "Have you recovered a new blueprint, my fleshy friend?\n\nI will add it to my database posthaste." }
WordHunterWoW_QuestEN[55087] = { title = "The Gathering Storm", description = "While I deal with the naga incursions, Lady Proudmoore is going to take on handling the Horde in Stormsong Valley and figuring out what happened to our spies there.\n\nYou'll find her near Proudmoore Keep.", objectives = "Report to Jaina Proudmoore near Proudmoore Keep in Boralus.", completion = "It appears the Horde activity in Stormsong Valley is more serious than we originally thought." }
WordHunterWoW_QuestEN[55088] = { title = "Lost in the Field", description = "When Shaw and I got here we discovered most of our operatives were dead. Most, but not all. \n\nGo into the field and get any of our operatives out of there. They might have more intel on what the Horde are planning here in Warfang Hold.", objectives = "Assist injured spies in Stormsong Valley.", completion = "Our people stumbled onto something really big out here!" }
WordHunterWoW_QuestEN[55089] = { title = "Shaw's Shank Redemption", description = "Hmm. Shaw said he'd check in when we got communications back but he hasn't. He's probably run into the same trouble the rest of our spies did.\n\nI'll stay here and guard the listening post. You find Shaw. He was headed for the cliff above Warfang Hold near the top of the waterfall. The peons called that area \"The Screaming Pit\" for some reason. I bet it's a real pleasant place.\n\nStab whatever he's fighting for me, okay?", objectives = "Find Mathias Shaw in The Screaming Pit above Warfang Hold.", progress = "Just in time, <name>.", completion = "They've increased security here beyond anything we expected, and with good reason." }
WordHunterWoW_QuestEN[55090] = { title = "A Gathering of Foes", description = "Before I was distracted, I was able to find out more about this Horde gathering. Sylvanas has summoned the leaders of the Horde and its allies. For what purpose, I cannot say.\n\nWe aren't in a position to strike her down--she is too well-protected. But perhaps we can learn something that will prove useful in the ongoing war.\n\nKeep your head low and take a look. I'll keep an eye out for more guards.", objectives = "Witness the Horde gathering.", completion = "I cannot help but pity Baine. Honor such as his has lost its value in the Horde.\n\nSylvanas has made a bold move. We'll go after her, but she's cunning. We need to push back the naga and gather our forces for a final strike." }
WordHunterWoW_QuestEN[55092] = { title = "Disruption of Power", description = "The naga tap into the power within nearby ley lines and have found a way to harness it.\n\nDestroy their devices before they can put that power to use against us.", objectives = "Destroy 5 Ley Line Accumulators in Spears of Azshara.", completion = "Hopefully we will never find out what they were drawing in such power for." }
WordHunterWoW_QuestEN[55094] = { title = "Stay Low, Stay Fast!", description = "It's a straight shot home. We just need to be careful.\n\nNeri's rule of survival number six: always be prepared!\n\nLet's go!", objectives = "Follow Neri Sharpfin.", completion = "Finally, some small relief. But we must not rest easy; Azshara surely has more in store for us than she lets on." }
WordHunterWoW_QuestEN[55095] = { title = "Upheaval", description = "So many lives lost... And the attacks from the naga are relentless!\n\nI apologize, {name}. This attitude is unbecoming of a king.\n\nWe have no time to lose musing of our own plight.\n\nLet us meet with Jaina and descend from this perilous place into the unknown.", objectives = "Speak with Lady Jaina Proudmoore above the waterfall.", completion = "Finally, some good news. Our champion awakens from the chaos." }
WordHunterWoW_QuestEN[55096] = { title = "Send My Father a Message", description = "My people are once again safe... for now.\n\nKing Mechagon won't stop sending his armies at us as long as he does not fear us.\n\nWe must send him a message.\n\nClimb to the top of the ramparts, and hack one of my father's projectors to proudly shine the banner of the Rustbolt Resistance big enough for the whole island to see.\n\nI'm sure that'll attract the attention of my father, King Mechagon.", objectives = "Hack a projector to display the Rustbolt Resistance emblem and defend it.", completion = "Rustbolt already looks improved, doesn't it?\n\nIt's not the first time we've had to rebuild it, and it won't be the last." }
WordHunterWoW_QuestEN[55099] = { title = "TBD NOT USED", description = "The fabled workbench of Rustbolt - MY workbench - has fallen into disrepair!\n\nThis tragedy was no doubt caused by the same ruffians and miscreants who kidnapped me and Princess Wiggles.\n\nThe VERY same ruffians and miscreants, in fact, who still show their faces in this very town on the regular.\n\nTheir presence here is a veritable slap to our collective faces!\n\nDispatch the snatchers quickly and recover my binder of blueprints. We may then commence crafting what we shall need to repair this.", objectives = "Collect the Junkyard Blueprint Book from Scrapthief Grillin." }
WordHunterWoW_QuestEN[55100] = { title = "TBD NOT USED", description = "Well, this is a fine mess!\n\nMy wondrous workbench won't be of much use until we recover those stolen blueprints.\n\nBut first thing's first, the conveyor belt must be repaired. I'll need a very specific Gizmo-matic to do it.\n\nI could craft a Gizmo-matic in my sleep... if I slept like you do, my very-susceptible-to-disease fleshy friend.\n\nBut I need material to work with.\n\nThe first lesson of junkyard tinkering: everything can be a spare part if you pummel it hard enough. Go forth and pummel!", objectives = "" }
WordHunterWoW_QuestEN[55101] = { title = "Junkyard Tinkering and You", description = "Behold, the fabled Pascal Workshop of Rustbolt -- MY workshop!\n\nCountless inventions have sprung forth into existence on this very spot, including my very finest invention, Pascal-K1N6!\n\nPascal-K1N6 can craft anything... as long as you have the blueprints for it.\n\nAnd since I have you to thank for the K1N6's safe return to Rustbolt, would you like to learn how to access his blueprints database?", objectives = "Use Pascal-K1N6 to craft a Scrap Grenade.", progress = "Remember, you can collect Spare Parts from almost anything on Mechagon.", completion = "Pascal-K1N6 is a marvel of junkyard tinkering! A wonder of the modern age!\n\nDid I mention that I invented him myself? Of course I did." }
WordHunterWoW_QuestEN[55103] = { title = "Ideas Can Come from Anywhere", description = "I didn't notice the tinkerer's spark in you when we first met.\n\nBut look at all of the blueprints you've recovered and uploaded to Pascal-K1N6's database.\n\nI was wrong. And happily so, my budding junkyard tinkering apprentice!\n\nBut this is a dangerous moment in your creative development.\n\nYou must avoid complacency!\n\nTake time off to find new ideas. Speak with builders that inspire you, reverse-engineer bots on the island, and be open to new ideas - no matter where they come from!", objectives = "Find people and things to inspire 1 new ideas in Mechagon.", completion = "I see it! The spark of new ideas in your eyes...\n\nYou've returned from your travels fresh and ready to brainstorm some blueprints!\n\nI have too. Let's discuss." }
WordHunterWoW_QuestEN[55111] = { title = "Creature Study: Zanj'ir Naga", description = "<Scrawled upon the magical scroll are Maedin's incomplete notes on the Zanj'ir naga.>", objectives = "Use Maedin's Scroll to collect data from various creatures within Nazjatar." }
WordHunterWoW_QuestEN[55116] = { title = "Getting a Clue", description = "I'm betting that one page of jibberish is a coded message. We can send it back to Stormwind to be cracked by our codebreakers or we could break some heads and find the cipher here.\n\nI'm thinking we'll just save some time and do that.\n\nThe guy in charge here probably has what we're looking for. Why don't you take him out and see if you can't find it. Even if you don't, without a leader the loyalists won't be much trouble. It's a win-win!\n\nWell, for us I guess.", objectives = "Slay Haughton Francis and recover his cipher.", progress = "Did you find a cipher? Or some kind of decoding gadget?", completion = "A decoder ring? Can't go wrong with the classics I guess.\n\n<Kelsey uses the ring to decode the message.>\n\nThis is from Ashvane alright. The date on here is pretty old though. The \"patron\" she mentions is something they're gonna want to hear about back in Boralus." }
WordHunterWoW_QuestEN[55117] = { title = "Correspondence Conundrum", description = "I think Ashvane has been in contact with her loyalists, but I don't know what their orders are.\n\nGo into their camp and see if you can't read their mail. We might find something that leads back to where Lady Ashvane is hiding or what their next move is going to be.", objectives = "Discover information about Lady Ashvane's plans.", completion = "A recipe, a personal letter.... a grocery list? Oh! Yeah, this is a coded communication. Hmmm\n\n<Kelsey rubs her chin and idly flips one of her knives as she thinks>\n\nI'm betting whoever is in charge here has the cipher. Why don't you go pay them a visit and get it for us." }
WordHunterWoW_QuestEN[55118] = { title = "Loose Ends", description = "Our campaign against the Horde is going strong, but there are some loose threads to take care of.\n\nLady Ashvane was broken out of Tol Dagor - by the Horde. We don't know where she's gone or what she is planning. I sent Kelsey out to track down some Ashvane Loyalists to get answers. She found them and has requested backup.\n\nShe's waiting for you in Freehold.", objectives = "Meet Kelsey Steelspark in Freehold.", completion = "I found a whole nest of these guys!\n\nYou ready to help me take 'em out?" }
WordHunterWoW_QuestEN[55119] = { title = "Reporting In!", description = "Well it looks like Ashvane's been out of contact for some time but this 'Patron' thing could be a problem.\n\nYou did excellent work today, {name}. Those Loyalists aren't going to be thinking about causing trouble for awhile, heh.\n\nI'll make my way back. You take the letter to the High Commander.", objectives = "Report to Halford Wyrmbane in Boralus.", progress = "Did you find anything on Ashvane?", completion = "<Wyrmbane gestures to the letter>\n\nIf this was Ashvane's last communication, perhaps her meeting with this mysterious \"patron\" of hers did not go as she planned.\n\nWe'll keep an eye on this. In the meantime, perhaps you'd better speak with our... guest." }
WordHunterWoW_QuestEN[55121] = { title = "The Laboratory of Mardivas", description = "<Several pages are devoted to notes on an experiment, a hastily written journal entry follows.>\n\nAt last, my research into the base elements has begun to bear fruit!\n\nWith careful application of the right base reagents and some arcane power I've managed to combine the essence of the elements in such a way as to create life!\n\nFurther investigation will be needed to determine what the various mixes of the elements will yield.\n\n<The writing ends here.>", objectives = "Activate the Elemental Essence Amalgamator in Mardivas's Laboratory.", progress = "<The remaining pages are filled with gibberish and strange doodles.>", completion = "<The magic of the system appears to have been drained. Perhaps after some time has passed it can be used again.>" }
WordHunterWoW_QuestEN[55122] = { title = "Murloc Mania", description = "I'm glad you made it out in one piece. \n\nJudging by the nearby shipwrecks, I think it's safe to say the missing expedition ran aground here, too.\n\nWe can't move until we've got the remaining survivors back on their feet. \n\nUnfortunately, our remaining supplies have been stolen by murlocs! \n\nI need you to recover enough first aid supplies for the wounded. \n\nThen we can begin searching for the missing expedition.", objectives = "Recover 6 First Aid Kits from Murlocs.", progress = "Did you recover the first aid kits? Don't take the murlocs lightly.", completion = "Excellent work. Let's get the survivors back on their feet." }
WordHunterWoW_QuestEN[55123] = { title = "Hunting Season", description = "", objectives = "" }
WordHunterWoW_QuestEN[55124] = { title = "Righting Wrongs", description = "Champion! I come with an urgent request from Baine Bloodhoof. He asks that you meet him at Plunder Harbor to help him with a... sensitive situation.\n\nYou must tell no one of this request, {class}. \n\nAncestors watch over you.", objectives = "Meet with Baine Bloodhoof at Plunder Harbor in Tiragarde Sound.", completion = "You're here.\n\nGood, now we can proceed." }
WordHunterWoW_QuestEN[55125] = { title = "Hunting Season", description = "", objectives = "" }
WordHunterWoW_QuestEN[55136] = { title = "Her Dog Days Are Over", description = "<The Wicker Beast gently nudges the dog's body with its snout.\n\nThe creature whines plaintively and moves to your side.\n\nIt gives a hopeful twitch of its bony tail.>", objectives = "Walk the Wicker Beast.", progress = "What's this...? I see you found my keys, but...", completion = "Oh... Oh tides below... no..." }
WordHunterWoW_QuestEN[55137] = { title = "For the Horde", description = "Thank you for meeting me upon my throne, {name}.\n\nWith our recent partnerin' with de Horde, I need worthy champions to represent the might of the Zandalari. \n\nI have chosen you to be among their ranks, {name}. Go and meet with the ambassador in Orgrimmar. \n\nWe have prepared a portal just behind you. When you are ready, step through to a new world.\n\nRemember, you bow only to the throne of Zandalar. Hold your head high, {name}.", objectives = "Meet with Ambassador Blackguard in the Orgrimmar Embassy.", completion = "Are you the new one? I'm supposed to welcome you. Here, take this letter.\n\n<Blackguard lets out an exasperated sigh.>" }
WordHunterWoW_QuestEN[55138] = { title = "Stranger in a Strange Land", description = "Hi. I'm Ambassador Blackguard.\n\nI am honored to welcome you to Orgrimmar, {race}.\n\n<He smiles unconvincingly.>\n\nAs a lifetime of adventure unfolds before you, be assured that... uh...\n\nYou know what? I've been saying this same greeting all day. Enough's enough.\n\nTalk to Chromie on top of the hourglass, then talk to your emissary. Run along.", objectives = "Find the Warchief's Command Board in Orgrimmar.", progress = "Dis land is much less... fertile than Zandalar.", completion = "So dis is it. We begin our adventures to bring honor to the Zandalari and de Horde!\n\nLoa be with you, <name>." }
WordHunterWoW_QuestEN[55142] = { title = "For the Alliance", description = "Thank you for meeting with me, {name}.\n\nI need representatives to go to Stormwind to represent our loyalty and commitment to our newly forged bond with the Alliance. \n\nI've had Yvia and her magi prepare a portal to the city for you in the Sanctum of the Sages. Once there, go to the Stormwind Embassy and meet with Ambassador Moorgard.\n\nYou will face many challenges on the long journey ahead. Remember where you came from and make your people proud!", objectives = "Take the portal to Stormwind in the Sanctum of the Sages and meet with Ambassador Moorgard in the Stormwind Embassy.", progress = "Welcome to Stormwind, <race>.", completion = "There you are! You must be <name>. We've been expecting you." }
WordHunterWoW_QuestEN[55146] = { title = "Stranger in a Strange Land", description = "Welcome to Stormwind, {race}. I invite you to explore our fair city. Since you hail from Kul Tiras, might I suggest visiting our lovely docks? They are home to our majestic fleet. I would be shocked if you were not impressed!\n\nAh, but that can wait, a bronze dragon has asked to talk to you. She is sitting under the nearby tree, on an hourglass of all things!\n\nAfter that, an emissary of Kul Tiras is waiting to welcome you to the city. Sounds like a busy day for you!\n\nHave a pleasant stay.", objectives = "Find Chromie in Stormwind City.", progress = "Enjoying your stay in Stormwind?", completion = "Wherever you venture, know that Kul Tiras is behind you." }
WordHunterWoW_QuestEN[55148] = { title = "Reclamation Rig", description = "", objectives = "You will receive:\n\nUpon completion of this quest you will gain:" }
WordHunterWoW_QuestEN[55153] = { title = "Collaborative Construction", description = "Construction projects can be found all over the island. You'll be able to build some of 'em yourself, but you're gonna need help with the bigger projects.\n\nAsk around and see what others are already working on, or just head out on your own and find a project you're interested in.\n\nConstruction projects move around and even change day-to-day, so keep an eye out for new ones while you're exploring.\n\nIf you're ever curious what construction projects are available on a given day, just ask me!", objectives = "Find a construction project in Mechagon and help build it.", completion = "Ah, I remember my first construction project...\n\n<Waren sighs wistfully.>\n\nI wonder where I put that steam-powered pacifier?" }
WordHunterWoW_QuestEN[55171] = { title = "Spy Versus Spy", description = "Naga attacks are on the rise, but that isn't all we have to deal with. We've received word of increased Horde activity near Warfang Hold in Stormsong Valley.\n\nSend some of our operatives to investigate what they are doing.", objectives = "Complete the mission \"Spy on Warfang Hold\"", progress = "Hopefully we can gather information on what they're up to in Stormsong Valley.", completion = "Damn. Most of our spies haven't made their scheduled check-ins. Whatever the Horde is doing I doubt it bodes well for us." }
WordHunterWoW_QuestEN[55173] = { title = "Northbound", description = "The quilboar kidnapped the rest of the expedition and took them to the north.\n\nI heard mention of needing more sacrifices for some sort of ritual...\n\nPlease, you must rescue them!", objectives = "Scout northward and find Austin Huxworth.", completion = "I've got some good news and some very, very bad news." }
WordHunterWoW_QuestEN[55174] = { title = "Cooking Meat", description = "Alaria is nearly starved to death. We need to get her something to eat!\n\nSlay some of the nearby wildlife for their meat. Bring whatever you find here to cook.\n\nIf we can help Alaria regain her strength, she might be able to tell us what happened to the others.\n\nI'll stay here and help stabilize her wounds.", objectives = "Get 5 Raw Meat from wildlife around the Abandoned Camp, then cook it on the campfire.", progress = "Please... I need... some food...", completion = "<Alaria quickly eats the meat that you cooked.>\n\nBy the Light... I feel so much better.\n\nYou need to keep moving... quilboar have kidnapped the expedition, including Captain Garrick's son!" }
WordHunterWoW_QuestEN[55175] = { title = "Where the Road Leads", description = "My people know many secrets about this place. If you prove yourselves worthy allies, you will be privy to them.\n\nFirst, we must regroup in Mezzamere. There, we at least have a foothold against the tide.", objectives = "Travel to Mezzamere with Okani.", completion = "So far, these ankoan have proven themselves formidable allies." }
WordHunterWoW_QuestEN[55177] = { title = "Tearing at the Seams", description = "I feel odd... weak. As though something is affecting my very existence.\n\nWould you come with me, {name}? I may need your help. At the very least, you could be a witness to whatever happens should something dire occur.", objectives = "Speak with Delormi when you're ready to leave and investigate the disturbance.", completion = "Well, this doesn't look good..." }
WordHunterWoW_QuestEN[55179] = { title = "Retaliation Coordination", description = "Master Shaw deployed a number of Alliance spies near a base the Horde have made in Stormsong Valley. When our spies stopped checking in, he took Kelsey Steelspark and went to investigate. \n\nNow Master Shaw is the one who hasn't checked in.\n\nI need someone to go in and find our missing people and give them whatever help they clearly need.", objectives = "Find Kelsey Steelspark in Stormsong Valley.", completion = "We knew someone would come when we missed our check-in. With you as our backup the Horde isn't gonna stand a chance.\n\nShaw's further in the Valley trying to figure out what is going on in Warfang Hold. I've been trying to control the chaos here. Care to lend a hand?" }
WordHunterWoW_QuestEN[55182] = { title = "Reassembly Required", description = "Master Shaw wanted me to rebuild the listening posts the Horde destroyed when they started to clear the area in preparation for whatever they are planning.\n\nI managed to salvage most of the parts for one, but I'm missing a few.\n\nFortunately for us, I've been watching the workers and they've been picking up the pieces of the destroyed machines. Go get our tech back and I can take care of the rest.", objectives = "Collect Spy Salvage from Horde Forces.", progress = "I am so excited! I love getting to work with our spy tech! Did you find what we need?", completion = "Yes! This is precisely what I needed." }
WordHunterWoW_QuestEN[55183] = { title = "Seeking Higher Ground", description = "We've only got one shot at reestablishing our communication network, so we've got to pick the right spot and I found just the right place! \n\nWhile you've been busy down here, I set up some camouflage and hauled the bulk of the machinery up there.\n\nWhat? Did you think I was just sitting here polishing my knives while you were gone?\n\nWell, okay I did that too. Anyway, I'll meet you up the hill!", objectives = "Meet Kelsey Steelspark on the hill south of Warfang Hold.", completion = "Once we get the listening post set up again, we won't have the range to reach Boralus, but we'll have plenty of power to get in touch with Master Shaw!" }
WordHunterWoW_QuestEN[55184] = { title = "Quilboar Shadow Magic", description = "Quilboar are primitive and savage. They rarely practice any magic other than geomancy.\n\nBut these particular quilboar seem to be dabbling in shadow magic. They must be stopped.\n\nSlay the quilboar in the den. They cannot spread this magic in the island!", objectives = "Slay 7 Quilboar within the Quilboar Briarpatch.", progress = "The quilboar are a powerful foe. Be careful.", completion = "Good work. I hope those quilboar learn that necromancy is not a path to power." }
WordHunterWoW_QuestEN[55185] = { title = "Listen Up!", description = "Okay! Once we get this up and running we should be able to send messages! In the valley at least.\n\nIt's gonna be a little bit tricky, but I've read the manual for these things cover to cover.\n\n<Kelsey slaps the top of the listening device.>\n\nI'm gonna put this thing back together. You watch out for the Horde.", objectives = "Protect Kelsey Steelspark in Stormsong Valley.", progress = "Woohoo! We are up and operational!", completion = "Ha! I knew I could get this thing up and running in record time.\n\nHmm. But Master Shaw isn't responding to my signal. That's no good." }
WordHunterWoW_QuestEN[55186] = { title = "Down with the Quilboar", description = "From what I can gather, the quilboar are performing a shadow ritual on one of the expedition members.\n\nTheir chief is Geolord Grek'og. He is the one who seeks to drain the life from our friend.\n\nSlay Grek'og and save the captive member of the expedition. He may know where the others were taken.", objectives = "Slay Geolord Grek'og.", completion = "Thanks for saving my life! They said this would be a run of the mill, uneventful expedition.\n\nIt definitely was NOT! And I couldn't be happier!" }
WordHunterWoW_QuestEN[55187] = { title = "Angela Test Quest Live Update", description = "", objectives = "" }
WordHunterWoW_QuestEN[55188] = { title = "Tearing at the Seams", description = "I feel odd... weak. As though something is affecting my very existence.\n\nWould you come with me, {name}? I may need your help. At the very least, you could be a witness to whatever happens should something dire occur.", objectives = "Speak with Delormi when you're ready to leave and investigate the disturbance.", completion = "Well, this doesn't look good..." }
WordHunterWoW_QuestEN[55193] = { title = "The Scout-o-Matic 5000", description = "You look like a {race} that needs help finding the scattered members of our alliance expedition!\n\nLuckily, you have happened to rescue the one and only Lindie Springstock, inventor extraordinaire! \n\nI've got my Scout-o-Matic 5000 all set to go. It'll fly up in the air and let you scout the entire area.\n\nI'll give you the honors. Use my Scout-o-Matic 5000 to find the rest of the expedition.", objectives = "Use the Scout-o-Matic 5000 to find Henry Garrick.", progress = "Give me a moment to re-size the Scout-o-Matic, then you can ride it!", completion = "There's no problem a little re-sizing can't fix! Let's find something to stomp those undead flat!" }
WordHunterWoW_QuestEN[55194] = { title = "Stocking Up on Supplies", description = "Quartermaster Richter was able to scavenge supplies from the wreckages on this island.\n\nWhy don't you visit her and see if she has anything that you need?\n\nYou'll want to be well equipped for whatever we encounter next.", objectives = "Purchase any item from Quartermaster Richter and sell any of your items to her.", progress = "Quartermaster Richter should have a few supplies that you could use.", completion = "All stocked up? That's great.\n\nPrivate Cole and Quartermaster Richter also found this bag in the nearby ruins. They thought you might make good use of it." }
WordHunterWoW_QuestEN[55195] = { title = "Reverberation", description = "Hati's spirit is bound to yours forevermore, hunter. But it also now carries a link to the Temple of Storms--as well as Silithus, I fear.\n\nThe Thunderspark shares these same bonds. By physically linking it here, you can call upon the different aspects of Hati's spirit and bind them to yourself as well.\n\nDo not worry. Skoll and I will guard the Thunderspark with our very lives! It will be safe.", objectives = "Use the Thunderspark to summon an Essence of Hati.", progress = "It warms my heart to see Hati by your side once more.", completion = "You may return here any time you wish to rekindle your bond with Hati.\n\nYou shall forever be a welcome guest in my court." }
WordHunterWoW_QuestEN[55196] = { title = "The Harpy Problem", description = "We need to find the remaining survivors of my expedition before the ogres sacrifice them for their dark ritual!\n\nI saw one of the survivors being dragged away by some harpies. They have a roost to the north.\n\nKee-La and I will meet you up there with a scouting report.", objectives = "Meet with Henry Garrick near the Harpy Roost.", completion = "It seems the harpies are up to no good. We'll need your help with this." }
WordHunterWoW_QuestEN[55208] = { title = "Kevin Live Update Test Quest", description = "", objectives = "" }
WordHunterWoW_QuestEN[55210] = { title = "Batteries Not Included", description = "You will not be sorry that you rescued my dear sister and me, {name}.\n\nWe are the vanguard of a new technological revolution, creating opportunities for all to enhance their lives with incredible technology!\n\nBut, before we can do that, we need our laboratory to be fully powered. Those ruffians from Mechagon really did a number on our equipment.\n\nFully charged energy cells are exceptionally rare around here, but I can make do with broken ones.\n\nCheck around town, in the wreckage from the last attack.", objectives = "Collect 10 Damaged Energy Cells.", progress = "Everything old can be made new again.", completion = "These are broken, but not TOO broken... Yes, I'm sure I can get these working again.\n\nYou may keep one as your recompense." }
WordHunterWoW_QuestEN[55211] = { title = "Recharging Rustbolt", description = "Our personal generator is worthless until we recharge its empty energy cells.\n\nAs my dear brother says, energy cells are the lifeblood of innovation. Everything in Mechagon needs power, and energy cells deliver that power in a wonderfully universal format.\n\nBut, once they're drained of power, most people toss the empty cells away.\n\nMost people are fools, dear test subject.\n\nWe have perfected the technology to recharge small numbers of energy cells back to full power.\n\nWill you help us test it?", objectives = "Use the NRG-100 to charge 6 generator energy cells.", progress = "We only test the best!", completion = "Wondrous work, my dear test subject!\n\nI detected unconventional electrical discharges from the NRG-100, but I see now that I was wrong to worry.\n\nIt's still in one piece. Oh, and so are you!\n\nCheer up. You've already outsurvived 5% of our test subjects!" }
WordHunterWoW_QuestEN[55213] = { title = "Energy Cells for Everyone", description = "The wondrous scuttlebutt around town is that the charging station in Bondo's Yard is going to be repaired today!\n\nThat charging station is the best way to recharge all the Empty Energy Cells that've been piling up in your bag. Or in other people's bag. Or inside the mechanical innards of robots you don't own but are legally allowed to destroy.\n\nAfter you've acquired Empty Energy Cells, help build the charging station in Bondo's Yard and charge all of your Empty Energy Cells!", objectives = "Find 5 Empty Energy Cells in Mechagon.\n\nThen, help build the Charging Station construction project and use it to charge your Empty Energy Cells.", progress = "Empty Energy Cells can always be found on the island, but the Charging Station isn't always available.\n\nChat with that wondrous Miss Gearhart if you want to know more.", completion = "Wondrous! I hope those nasty troggs let you charge up in peace.\n\nThey simply do not comprehend technology to any degree. Frankly, I'm embarrassed for them." }
WordHunterWoW_QuestEN[55214] = { title = "Seam Stress", description = "I...I need a moment, {name}.\n\n<Delormi seems disoriented and grabs your shoulder for support. She presses her hand against her forehead and stands there for a minute. \n\nFinally shaking off whatever she was feeling, she stands up straight and faces you.>\n\nThere are gaps in my memories. Things important to me, lost now. We must stop her at all costs, {name}.", objectives = "Follow Delormi through the Time Rift.", progress = "I feel so weak...", completion = "That rift, don't repair it! That's the one." }
WordHunterWoW_QuestEN[55215] = { title = "The Cycle of Life", description = "", objectives = "" }
WordHunterWoW_QuestEN[55216] = { title = "The Audition", description = "Xanjo has spoken highly of your skills, but I need to be certain of what you can do. I mean no offense, this is as much for your benefit as it is our own, as if you are not ready the task could kill you.\n\nIf you are willing, I would like to provide you with a test to see how well you can work leather.\n\nBring me three Drums of the Maelstrom that you have crafted yourself. This will prove your skill and consistency.\n\nIf your work is up to par, I will inform you of my plan.", objectives = "Craft 3 Drums of the Maelstrom and bring them to Atikka Moonchaser.", progress = "<Atikka breathes audibly in anticipation of your return.>\n\nHave you got the drums?", completion = "Tight stitching. Even tension. No tears or holes.\n\nYou'll do nicely.\n\n<Atikka leans in as he whispers.>\n\nMy plan is to make a set of drums from rare and powerful components. The drum's design will let you harness the raw, primal might of the slain beasts, and allow you to teach those Alliance dogs a lesson they won't soon forget. \n\nUsing the drums will require a special mallet, but fear not. Once our work is done, I will teach you how to craft a mallet for yourself." }
WordHunterWoW_QuestEN[55217] = { title = "Repaying the Life Debt", description = "When I heard that the Alliance attacked Dazar'alor, I couldn't help but think of those lost when they attacked Camp Taurajo. No longer can I sit idly while they continue to slaughter us!\n\nI need you to go to Thunder Bluff, find Sheza Wildmane on the Elder Rise, and ask for some of her personal collection.\n\nI won't go into detail, but she owes me a life debt, and seeing her would... bring back too many painful memories... for both of us.\n\nFind her, tell her I sent you, and that this absolves her debt.", objectives = "Speak with Sheza Wildmane in Thunder Bluff.", completion = "<You explain your mission and relation to Atikka.>\n\nI see. Of course I'm more than willing to help, especially since it's Atikka.\n\nHowever, doing so is going to take a bit more work on your end, if you don't mind." }
WordHunterWoW_QuestEN[55218] = { title = "Sheza's Prized Leather", description = "I have a stash of extremely rare leathers, or... rather, I did.\n\nI don't know how, but the Venture Company must have heard how valuable my collection was because they stole it!\n\nAnd THEN they had the audacity to leave a note offering to sell it back to me for 1,000 gold! As the \"former owner\", I'm able to \"best appreciate the value of their new acquisition.\"\n\nThe note states they'll be in the bluffs to the East until someone buys them.\n\nHowever you get the skins, consider them yours.", objectives = "Retrieve the Rare Hides.", progress = "How was she?", completion = "<You explain what happened in Mulgore.>\n\nBah! Wretched goblins and their lust of coin!\n\n<Attika takes a deep breath to steady himself.>\n\nI... Am sorry you had to see that. I just find it so infuriating when our fight is made harder so one of those green-skinned runts can steal your last copper." }
WordHunterWoW_QuestEN[55219] = { title = "Dropping by the Base", description = "When the Legion was attacking, I met with a member of the Highmountain Tauren who had a knack for making and playing drums.\n\nTorv usually keeps to himself, but he is as brilliant as he is insane.\n\nIf there is anyone who would know where we could get the raw materials for something of this magnitude, it would be him.\n\nHead to Thunder Totem, and ask Torv Dubstomp if he can think of a suitable source of scales. Preferably something still living, so its power is still fresh.", objectives = "Speak with Torv Dubstomp in Thunder Totem.", completion = "Atikka sent you? Ha! How is the old steer?!\n\nHmmm... scales you say.\n\n<His eyes flick back and forth as he looks off into the distance. His expression quickly shifts from a grimace to one of delight.>\n\nI got it!" }
WordHunterWoW_QuestEN[55220] = { title = "Bass Fishing", description = "Have you heard of people taking small golden carp as pets?\n\nWell, if it is kept in a pond free of predators, over time it can grow enormous, only limited by the food present.\n\nCenturies ago, one of these fish lived in the pond atop a mountain. It ate everything and began to starve, so my people dug a river that connected the pond to the ocean so the fish could be free.\n\nNow, fishermen talk of being attacked by an enormous golden fish in the Rockaway Shelf.\n\nKill it. Take his scales back to Atikka.", objectives = "Collect Brilliant Golden Scales.", progress = "Did you meet with Torv yet?", completion = "<After hearing your retelling of Torv's plan, Atikka bursts into laughter.>\n\nA centuries old goldfish?!\n\nI told you he was insane!\n\nAhhh, good work. Glad to see you weren't eaten by a guppy." }
WordHunterWoW_QuestEN[55221] = { title = "Picking Bones", description = "When I was sailing in, I noticed the remains of an unbelievably large beast on the nearby peninsula.\n\nWhatever it was, it must have been strong, making it the perfect source for the bone elements of the drums.\n\nGo to the peninsula, 'Xibala' I've heard it called, and fill a bag with the bones you find.\n\nIf you come across any of those damned Alliance, show them no mercy. They did this to themselves.", objectives = "Collect 18 Unwaning Bones.", progress = "Did you get the bones?\n\nDid the Alliance give you any trouble?", completion = "These look good.\n\nIt makes me even happier knowing this was something the Alliance was after, and that you mucked that up for them! Heh!" }
WordHunterWoW_QuestEN[55222] = { title = "Make Some Noise", description = "We have everything we need to craft the drum, except the Earth Mother's blessing. \n\nThe drum is but a vessel, like a cup. We need her to imbue the drum with power, filling the cup so that we may drink.\n\nIt will not be easy to convince her to assist us in creating a weapon of war, but I will implore her to protect her children.\n\nWhile I'm doing that, you will need to craft the drum itself.\n\nNot too big, though. The larger the vessel, the more power it can hold, but the harder it becomes to carry.", objectives = "Craft 6 Drums of Primal Might.", progress = "<Clearly exhausted, Atikka is trying to remain composed.>", completion = "<Atikka lets out a beleaguered breath, before turning his head to face yours, smiling weakly.>\n\nWe've done it, <name>." }
WordHunterWoW_QuestEN[55223] = { title = "Instruments of Destruction", description = "Our work is almost finished.\n\nThese drums, while powerful, are practically useless here in port.\n\nIf you want to get the most benefit from them, you'll need to spread them out. I'd suggest one for each territory here and in Kul Tiras, to help you when you are on a quest and to keep you at your strongest when you're behind enemy lines.\n\nLook for someplace centralized in each territory to place drums.\n\nOnce you return, I'll show you how to make the mallet needed to utilize the drums.", objectives = "Place the Drums of Primal Might throughout Zandalar and Kul Tiras.", completion = "I'm glad to see you back in one piece.\n\nIn hindsight, I suppose I could have shown you how to make the mallet before you left, but everything seems to have worked out well.\n\nNow then, let me show you how to make the Mallet of Thunderous Skins..." }
WordHunterWoW_QuestEN[55224] = { title = "Rank 2 - Poen test", description = "Gather corrupted ink sacs from the Nazothian Brain squids. \n\nThe naga use them to control us, let's see if it works the other way.", objectives = "Collect $1oa corrupted ink sacs.Gather corrupted ink sacs from the Nazothian Brain squids. \n\nThe naga use them to control us, let's see if it works the other way.You will learn:" }
WordHunterWoW_QuestEN[55225] = { title = "Special Juices", description = "", objectives = "" }
WordHunterWoW_QuestEN[55226] = { title = "Drive the Enemy", description = "", objectives = "Upon completion of this quest you will gain:" }
WordHunterWoW_QuestEN[55227] = { title = "The Aeonian Artisan", description = "Good day, friend!\n\nA Night Elf woman stopped by and asked who was the best leatherworker I knew who didn't mind getting their hands dirty.\n\nI gave her your name, and she asked me to ask you to find her in Boralus Harbor.\n\nShe didn't say what she needed my best student for, but the way she acted makes me think that it is for something big.\n\nHead on down to the docks and look for her. She has white hair, purple tattoos, and a pet turtle named \"Gouge\". Show her what I've taught you!", objectives = "Meet the Night Elf Leatherworker in Boralus Harbor.", completion = "Goddess be praised!\n\nWe have much to discuss." }
WordHunterWoW_QuestEN[55228] = { title = "The Audition", description = "Cassandra has spoken highly of your skills, but I need to be certain of what you can do. I mean no offense, this is as much for your benefit as it is our own, as if you are not ready the task could kill you.\n\nIf you are willing, I would like provide you with a test to see how well you can work leather.\n\nBring me three Drums of the Maelstrom that you have crafted yourself. This will prove your skill and consistency.\n\nIf your work is up to par, I will inform you of my plan.", objectives = "Craft 3 Drums of the Maelstrom and bring them to Daniss Ghostdancer.", progress = "Do you have the drums?", completion = "Clean lines. Even tension. No tears or holes.\n\nVery well.\n\nMy plan is to make a set of drums from rare and powerful components that will let you harness the raw, primal might of the slain beasts.\n\nWith this power, you will teach the Horde that home is not a place that can be burned, hope is not something that can be slain, and that we are stronger than flame. \n\nThe drums will require a special mallet to use, but once our work is done, I will teach you how to craft this mallet for yourself." }
WordHunterWoW_QuestEN[55229] = { title = "Repaying the Debt", description = "I was in Teldrassil when it was set alight. Through the panic and chaos, I knew I could not rest as long as those who did this were unpunished.\n\nI need you to go to Stormwind, find Telonis near the Lion's Rest, and ask for some of his personal collection.\n\nI managed to save him from the fires, so he owes me a great deal. I would go myself, but the loss of Teldrassil is still a fresh wound. I still need to give it time to heal.\n\nFind him, tell him I sent you, and that this will absolve his debt to me.", objectives = "Speak with Telonis in Stormwind.", completion = "<You explain your mission and relation to Daniss.>\n\nI see. Of course I'm more than willing to help. She may be a T'lara, but I do owe her my life.\n\nHowever, there is a slight issue that will need to be dealt with." }
WordHunterWoW_QuestEN[55230] = { title = "Telonis' Prized Leather", description = "I have a stash of extremely rare leathers, or... rather, I did.\n\nA group of thieves must have heard how valuable my collection was because they stole it!\n\nAnd THEN they had the audacity to leave a note offering to sell it back to me! As the \"former owner\", I'm able to \"best appreciate the value of their new acquisition.\"\n\nThe note states they'll be waiting in the foothills behind the castle, to the east, until they find another buyer.\n\nHowever you get the skins, consider them yours.", objectives = "Retrieve the Rare Hides.", progress = "How is he holding up?", completion = "<You explain what happened in Stormwind.>\n\nTypical humans. Extorting allies because only their suffering matters.\n\n<Daniss takes a deep breath to steady herself.>\n\nI am sorry, <name>. I spoke out of frustration.\n\nI'm no stranger to war, but Sylvanas' tactics have made this one exceptionally taxing. I didn't mean to discourage their... resourcefulness. I simply wish it hadn't come to it.\n\nAt this time, we must keep our faith in the Alliance." }
WordHunterWoW_QuestEN[55231] = { title = "The Other Ghostdancer", description = "When the Legion was attacking, my partner went to Val'sharah to fight the demons.\n\nMevris may be cold and headstrong, but he's goal oriented, and willing to sacrifice to achieve them. That's part of why I fell in love with him.\n\nIf there is anyone who would know where we could get the raw materials for something of this magnitude, it would be him.\n\nHead to Val'sharah, and look for him in the Temple of Elune. Tell him of our plan, and that we need his help securing scales.", objectives = "Speak with Mevris Ghostdancer in Val'sharah.", completion = "Daniss sent you? Is everything alright?\n\n<You explain the plan and need for scales.>\n\nHmmm... scales you say." }
WordHunterWoW_QuestEN[55232] = { title = "Mevris' Menace", description = "There is a hydra that has been something of a nuisance for us as of late. It lives out on the Gloaming Reef, almost directly due west of here.\n\nIt's been attacking ships that pass by, making it difficult to get supplies to and from Bradensbrook.\n\nI sent a team to handle it, but they haven't returned.\n\nGo out there, kill it, and take its scales to Daniss.\n\nAnd when you see her, tell her that I said...\n\n<Mevris pauses as he thinks of his words, and the meaning they carry.>\n\nNothing.", objectives = "Collect Brilliant Azure Scales.", progress = "Have you met with Mevris?", completion = "<After hearing your retelling of Mevris' plan, Daniss nods thoughtfully.>\n\nI'm glad you were able to assist him. He has been gone for some time now. Hopefully with this creature now deceased, there is one less obstacle before he can come home.\n\nAnd good work with the scales. These appear to be perfect for the task." }
WordHunterWoW_QuestEN[55233] = { title = "Picking Bones", description = "When I was sailing in, I heard some of the sailors talking about the Horde presence here in Tiragarde Sound.\n\nApparently they're scrounging around the remains of a massive creature that has washed ashore.\n\nWhatever it was, if the Horde wants it, we need to make sure they don't get it.\n\nFind the Horde, keep them from taking anything, and see if there are any bones from the creature we can use for our drums.\n\nShow them no mercy, {name}.", objectives = "Collect 18 Unwaning Bones.", progress = "Have you dealt with our mutual problem?", completion = "These bones look good.\n\nI'm thrilled to hear that the Horde bought nothing with their lives." }
WordHunterWoW_QuestEN[55234] = { title = "Make Some Noise", description = "We have everything we need to craft the drum, except Elune's blessing. \n\nThe drum is but a vessel, like a cup. We need her to imbue the drum with power, filling the cup so that we may drink.\n\nWith Tyrande donning the mantle of the Night Warrior, much of Elune's power is taxed. Asking for another favor is not insignificant, but I must try.\n\nWhile I'm doing that, I need you to craft the drum. Try to keep it small. The larger the vessel, the more power it can hold, but the harder it becomes to move.", objectives = "Craft 6 Drums of Primal Might.", progress = "<Clearly exhausted, Daniss is trying to remain composed.>", completion = "<Daniss lets out a beleaguered breath, before turning to face you, smiling weakly.>\n\nWe did it, <name>.\n\nThey may have called me \"T'lara\", a warrior armed only with words, but those words have given us the strength of a goddess.\n\nWith these drums, we can break the Horde." }
WordHunterWoW_QuestEN[55235] = { title = "Instruments of Destruction", description = "There is one last thing we need to do.\n\nThese drums, while powerful, are practically useless here in town.\n\nIf you want to get the most benefit from them, you'll need to spread them out. I'd suggest one for each territory here and in Zandalar, to help you when you are on a quest and to keep you at your strongest when you're behind enemy lines.\n\nLook for someplace centralized in each territory to place drums.\n\nOnce you return, I'll show you how to make the mallet needed to utilize the drums.", objectives = "Place the Drums of Primal Might throughout Zandalar and Kul Tiras.", completion = "You've returned! I take it all went well?\n\nIn retrospect, I could have shown you how to make the mallet before you left, but everything seems to have worked out well.\n\nNow then, let me show you how to make the Mallet of Thunderous Skins..." }
WordHunterWoW_QuestEN[55242] = { title = "A Goblin in Need", description = "", objectives = "" }
WordHunterWoW_QuestEN[55243] = { title = "A Daughter of Torcali", description = "It has long been remarked upon that a direhorn is de bravest beast in de jungle. That is why they are chosen as mounts for our warriors.\n\nIn this case, that bravery may not be in your favor. De little one has run off and I do not think she is hungry this time.\n\nBest find her before she gets hurt.", objectives = "Find the Child of Torcali in the Savagelands and rescue her from danger.", completion = "<The Child of Torcali holds her head high.>" }
WordHunterWoW_QuestEN[55244] = { title = "Away From the Herd", description = "<The Child of Torcali stares longingly out of her pen. Her gaze seems to be following the other nearby direhorns.\n\nPerhaps she could use a distraction.>", objectives = "Play with your direhorn.", completion = "<The Child of Torcali lovingly headbutts your leg.>" }
WordHunterWoW_QuestEN[55245] = { title = "Eat Like a Direhorn", description = "<The Child of Torcali investigates your hands for traces of food and makes a small sound of distress.>", objectives = "Feed the Child of Torcali.", progress = "<The Child of Torcali wiggles impatiently.>", completion = "<The Child of Torcali blinks trustingly up at you and makes a warm rumbling sound.>" }
WordHunterWoW_QuestEN[55246] = { title = "Even Greener Pastures", description = "Ever since Torcali gave her boon to de little one, she has been growing like a weed. Dat makes her very hungry.\n\nShe got out again to look for more things to eat. Before you ask, it is not my role to stop her from doing what she wants. Only to ensure she is safe.\n\nShe is probably fine. Bring her home, and if you have trouble bringing her home, you might try a bribe.", objectives = "Find the Child of Torcali and lead her back to her pen.", completion = "<The Child of Torcali seems very pleased with herself.>" }
WordHunterWoW_QuestEN[55247] = { title = "The Trust You've Earned", description = "I believe my loa will agree with me when I say that you have proven yourself worthy of this one's companionship.\n\nShe is large enough now that she can bear you wherever it is that you wish to go.\n\nI had de Beastlord craft a saddle for you. Go and get it and I will help you put it on your new steed's back.\n\nCongratulations, {name}.", objectives = "Retrieve the Direhorn Saddle in Warbeast Kraal.", progress = "<Li'zal rubs her head and groans.>", completion = "I could not stop her. She rammed de gate...\n\nLike a thing possessed..." }
WordHunterWoW_QuestEN[55248] = { title = "Greener Pastures", description = "You have done an adequate job keeping de little one fed, but sometimes they just want something else.\n\nI did not see where de hatchling went, but you should start where de grass is real green. You will likely find her eating it.\n\nIf you have trouble bringing her home, you might try a bribe.", objectives = "Find the Child of Torcali and lead her back to her pen.", completion = "<The Child of Torcali seems very pleased with herself.>" }
WordHunterWoW_QuestEN[55249] = { title = "Away From the Herd", description = "<The Child of Torcali stares longingly out of her pen. Her gaze seems to be following the other nearby direhorns.\n\nPerhaps she could use a distraction.>", objectives = "Help your direhorn cheer up.", completion = "<The Child of Torcali lovingly headbutts your leg.>" }
WordHunterWoW_QuestEN[55250] = { title = "A Growing Appetite", description = "<The Child of Torcali investigates your hands for traces of food and makes a small sound of distress.>", objectives = "Feed the Child of Torcali.", progress = "<The Child of Torcali wiggles impatiently.>", completion = "<The Child of Torcali blinks trustingly up at you and makes a warm rumbling sound.>" }
WordHunterWoW_QuestEN[55251] = { title = "A Daughter of Torcali", description = "It has long been remarked upon that a direhorn is de bravest beast in de jungle. That is why they are chosen as mounts for our warriors.\n\nIn this case, that bravery may not be in your favor. De little one has run off and I do not think she is hungry this time.\n\nBest find her before she gets hurt.", objectives = "Find the Child of Torcali in the Slough and rescue her from danger.", completion = "<The Child of Torcali holds her head high.>" }
WordHunterWoW_QuestEN[55252] = { title = "A Loa Without a Temple", description = "I have given some thought about your situation, {name}.\n\nIt is not your fault dat de goblin deceived us. I followed along with his scheme as well. From today, you have my forgiveness. \n\nBut dat cannot help de little one. I fear we may lose it, if we do not act. We must ask de wanderer's loa, de mountain dat moves, de great bulwark, de greatmother of direhorns, to save her child.\n\nTake dis offering to her shrine and ask for her boon... and her forgiveness.", objectives = "Deliver L'kala's offering to Torcali.", progress = "<The great direhorn looks down upon you.>", completion = "<A warm but thunderous voice enters your mind.>\n\nYou have come to redeem yourself. Good. Let us begin." }
WordHunterWoW_QuestEN[55253] = { title = "A Show of Faith", description = "<Torcali's voice enters your mind.>\n\nI have watched your efforts from afar, small thing. You have made mistakes, and one of my young has suffered for it.\n\nI do not forget, but I can forgive.\n\n<The enormous direhorn touches the offering bundle with her nose.>\n\nAs my people place faith in me, I place my faith in you. Take my blessing to my child and she will wake.", objectives = "Deliver the Blessed Offering to your direhorn hatchling in Warbeast Kraal.", completion = "<The Child of Torcali peers sleepily up at you and rumbles contentedly.>" }
WordHunterWoW_QuestEN[55254] = { title = "An Unending Sleep", description = "<The direhorn hatchling continues to sleep soundly, despite any efforts on your part to wake it.\n\nIt's probably been too long. You should speak to Beastlord L'kala.>", objectives = "Speak to Beastlord L'kala in Warbeast Kraal.", completion = "I see you have noticed de state of your hatchling.\n\nGiven it is your responsibility, I will accept dat you did not know what you were doing when we started dis whole affair.\n\nI hope you are ready to change dat." }
WordHunterWoW_QuestEN[55258] = { title = "Sleep, Eat, Repeat", description = "<The Child of Torcali pushes the sack of herbs around with her snout.\n\nShe then looks to you and stomps eagerly in place.>", objectives = "Feed the Child of Torcali.", progress = "<The Child of Torcali pushes her snout into your hand in search of food.>", completion = "<The Child of Torcali trumpets in satisfaction.>" }
WordHunterWoW_QuestEN[55264] = { title = "Calligraphy", description = "", objectives = "" }
WordHunterWoW_QuestEN[55298] = { title = "Fishing For Something Bigger", description = "There's a huge fish lurking these waters, and it's been causing lots of problems! \n\nIt eats other fish, fishermen, and a lot of expensive gear. I saw it swallow a beautiful Zigby 300 Fishing Rod along with its owner just the other day!\n\nI've got a plan, but I've lost a lot of my equipment in the waters around here. Can you help fish up some of these items for me?", objectives = "Find the Anodized Sentry Fish, Jarmouthed Goby and the Suction Tube.", progress = "Did you get me the items?", completion = "Great work, <name>.  Now I can build the Minnow Vac!" }
WordHunterWoW_QuestEN[55299] = { title = "Bottom Feeding Stinkfish", description = "<Danielle Anglers may be interested in this fish.>", objectives = "Take the fish to Danielle Anglers.\n\nProvided item:", completion = "This fish looks to have adapted to survive in the shallow water pools around the trash heaps. It smells awful, the smell probably protects it from any predators. I want to catalogue this and release it before this smell sticks to me!" }
WordHunterWoW_QuestEN[55300] = { title = "The Cycle of Life", description = "", objectives = "" }
WordHunterWoW_QuestEN[55301] = { title = "The Cycle of Life", description = "", objectives = "" }
WordHunterWoW_QuestEN[55302] = { title = "The Cycle of Life", description = "", objectives = "" }
WordHunterWoW_QuestEN[55303] = { title = "The Cycle of Life", description = "", objectives = "" }
WordHunterWoW_QuestEN[55304] = { title = "The Cycle of Life", description = "", objectives = "" }
WordHunterWoW_QuestEN[55305] = { title = "Bolted Steelhead", description = "<Danielle Anglers may be interested in this fish.>", objectives = "Take the fish to Danielle Anglers.\n\nProvided item:", completion = "This fish appears to have been manufactured! The workmanship is quite sophisticated. I want to catalogue this and release it for further observation." }
WordHunterWoW_QuestEN[55306] = { title = "Pond Hopping Springfish", description = "<Danielle Anglers may be interested in this fish.>", objectives = "Take the fish to Danielle Anglers.\n\nProvided item:", completion = "This fish has adapted itself to allow it to hop between shallow pools of water. I will catalogue it and release it back into a nearby pool.  We'll then see where it hops too!" }
WordHunterWoW_QuestEN[55307] = { title = "Shadowy Cave Eel", description = "<Danielle Anglers may be interested in this fish.>", objectives = "Take the fish to Danielle Anglers.\n\nProvided item:", completion = "This fish looks to have adapted to survive in dark caves of Mechagon. I will catalogue it and return it to a nearby cave." }
WordHunterWoW_QuestEN[55308] = { title = "Mechanical Blowfish", description = "<Danielle Anglers may be interested in this fish.>", objectives = "Take the fish to Danielle Anglers.\n\nProvided item:", completion = "A strange mechanical fish that appears to be modifying itself for survival in these waters. An amazing discovery!" }
WordHunterWoW_QuestEN[55309] = { title = "Spitting Clownfish", description = "<Danielle Anglers may be interested in this fish.>", objectives = "Take the fish to Danielle Anglers.\n\nProvided item:", completion = "This fish has developed an unusual behavior. It most likely is imitating the actions of surrounding creatures. I will catalogue it and then release it immediately." }
WordHunterWoW_QuestEN[55310] = { title = "Sludge-fouled Carp", description = "<Danielle Anglers may be interested in this fish.>", objectives = "Take the fish to Danielle Anglers.\n\nProvided item:", completion = "Something horrible has happened to this fish. It maybe worth further investigation of the waters where you found it." }
WordHunterWoW_QuestEN[55311] = { title = "Energized Lightning Cod", description = "<Danielle Anglers may be interested in this fish.>", objectives = "Take the fish to Danielle Anglers.\n\nProvided item:", completion = "This fish radiates electricity. I suspect it has been feeding on underwater power cables. A most interesting find, which I will catalogue immediately!" }
WordHunterWoW_QuestEN[55312] = { title = "Solarsprocket Barbel", description = "<Danielle Anglers may be interested in this fish.>", objectives = "Take the fish to Danielle Anglers.\n\nProvided item:", completion = "This mechanical fish appears to be powered by sunlight. I will catalogue this find and return it to its pond." }
WordHunterWoW_QuestEN[55313] = { title = "Tasty Steelfin", description = "<Danielle Anglers may be interested in this fish.>", objectives = "Take the fish to Danielle Anglers.\n\nProvided item:", completion = "This fish appears quite healthy and probably tastes quite delicious. I will catalogue this and then probably cook it for dinner." }
WordHunterWoW_QuestEN[55319] = { title = "Tonk the Terrible", description = "<This TK looks like it could be a good racer in the Roadrash Race.\n\nCrash Wheeler at the Roadrash Racetrack has the final say on what's allowed, though.>", objectives = "<This TK looks like it could be a good racer in the Roadrash Race.\n\nCrash Wheeler at the Roadrash Racetrack has the final say on what's allowed, though.>" }
WordHunterWoW_QuestEN[55320] = { title = "Vehicle: TK02[DNT]", description = "<This TK[DNT] looks like it could be a good racer in the Roadrash Race.\n\nCrash Wheeler at the Roadrash Racetrack has the final say on what's allowed, though.>", objectives = "<This TK[DNT] looks like it could be a good racer in the Roadrash Race.\n\nCrash Wheeler at the Roadrash Racetrack has the final say on what's allowed, though.>" }
