WordHunterWoW_QuestEN[55345] = { title = "The Dark Ranger's Pupil", description = "Thank the abyss you're here, champion!\n\nI am Moorgoth, tracker of fearsome foes in dark places. Anyone in the Trueshot Lodge will vouch for my credentials.\n\nDark Ranger Velonara and I are good friends, and I fear she is in peril.\n\nShe's been training an apprentice dark ranger. Newly raised, she said. At any rate, her pupil ran off after receiving a letter from his brother, and now Velonara has gone to Tirisfal Glades to find him.\n\nI have a bad feeling about all this. Could you check on her safety?", objectives = "Find Dark Ranger Velonara in Tirisfal Glades.Thank the abyss you're here, champion!\n\nI am Moorgoth, tracker of fearsome foes in dark places. Anyone in the Trueshot Lodge will vouch for my credentials.\n\nDark Ranger Velonara and I are good friends, and I fear she is in peril.\n\nShe's been training an apprentice dark ranger. Newly raised, she said. At any rate, her pupil ran off after receiving a letter from his brother, and now Velonara has gone to Tirisfal Glades to find him.\n\nI have a bad feeling about all this. Could you check on her safety?You will receive:" }
WordHunterWoW_QuestEN[55346] = { title = "The Dark Ranger's Pupil", description = "I am Moorgoth, hunter of fearsome foes and hero of the Trueshot Lodge.\n\nYou are a renowned champion of the Alliance, but I've been told you save those in peril. Please hear me out.\n\nI am friends with a ranger named Velonara. She serves the Horde, but I assure you she is a noble soul.\n\nShe's been training an apprentice ranger who disappeared after receiving a letter from his brother. Velonara has gone to Tirisfal Glades to find him.\n\nI have a bad feeling about this. Would you check on her safety?", objectives = "Find Dark Ranger Velonara in Tirisfal Glades.I am Moorgoth, hunter of fearsome foes and hero of the Trueshot Lodge.\n\nYou are a renowned champion of the Alliance, but I've been told you save those in peril. Please hear me out.\n\nI am friends with a ranger named Velonara. She serves the Horde, but I assure you she is a noble soul.\n\nShe's been training an apprentice ranger who disappeared after receiving a letter from his brother. Velonara has gone to Tirisfal Glades to find him.\n\nI have a bad feeling about this. Would you check on her safety?You will receive:" }
WordHunterWoW_QuestEN[55348] = { title = "Supplies from the Rustbolt Resistance", description = "The Resistance appreciates all the help you've given us.\n\nPlease take these supplies as a token of our gratitude, and a promise of more to come, should you continue to help us.", objectives = "Speak with Prince Erazim in Rustbolt for your reward.", completion = "The Resistance stands strong, thanks in part to your prevailing efforts.\n\nYour efficiency has earned you additional resources.\n\nPlease expend them in endeavors optimized to ensure the continued success of the resistance." }
WordHunterWoW_QuestEN[55350] = { title = "Assault: Amathet Advance", description = "The Amathet seek to claim the Forge of Origination for their own. We must not allow it to fall into their hands again!\n\nOur men are defending the entrance, but they will be overwhelmed if the entire might of the Amathet advances upon them. \n\nDo what you can to route their forces before its too late.", objectives = "Drive back the Amathet Assault in Uldum.", progress = "The Amathet must be stopped!", completion = "Hah! You showed those dusty zealots what a true warrior looks like.\n\nWell done." }
WordHunterWoW_QuestEN[55351] = { title = "The Missing Apprentice", description = "I have been training an apprentice, a young dark ranger named Prelus. He has proven an apt pupil and a quick study. But like many of the newly raised, he feels the draw of his old life calling to him.\n\nPrelus received a letter from his brother Auron asking to meet. I advised against it, but Prelus was insistent. He is long overdue to return, and I fear for his safety.\n\nThis is the location of the rendezvous. Could you help me search for evidence of what transpired? This flare gun may reveal the truth.", objectives = "" }
