WordHunterWoW_QuestEN[55451] = { title = "Paint Vial: Fireball Red", description = "<Marvelous Martini could make use of this item.>", objectives = "Deliver the item to Marvelous Martini.\n\nProvided item:", completion = "What a bold color for a mechanocat. I could see you riding this!" }
WordHunterWoW_QuestEN[55452] = { title = "Paint Vial: Fel Mint Green", description = "<Marvelous Martini could make use of this item.>", objectives = "Deliver the item to Marvelous Martini.\n\nProvided item:", completion = "A delicious color choice. I can almost taste the fel." }
WordHunterWoW_QuestEN[55454] = { title = "Paint Vial: Lemonade Steel", description = "<Marvelous Martini could make use of this item.>", objectives = "Deliver the item to Marvelous Martini.\n\nProvided item:", completion = "What a tasty color for a mechanocat!" }
WordHunterWoW_QuestEN[55455] = { title = "Paint Vial: Mechagon Gold", description = "<Marvelous Martini could make use of this item.>", objectives = "Deliver the item to Marvelous Martini.\n\nProvided item:", completion = "Good or bad, it makes a statement!" }
WordHunterWoW_QuestEN[55456] = { title = "Paint Vial: Copper Trim", description = "<Marvelous Martini could make use of this item.>", objectives = "Deliver the item to Marvelous Martini.\n\nProvided item:", completion = "A unique choice, for those that want to be different." }
WordHunterWoW_QuestEN[55457] = { title = "Paint Vial: Overload Orange", description = "<Marvelous Martini could make use of this item.>", objectives = "Deliver the item to Marvelous Martini.\n\nProvided item:", completion = "One of my favorites!" }
WordHunterWoW_QuestEN[55462] = { title = "The Wanderer's Call", description = "Greetings, small thing.\n\nDe Great Wanderer asked this one to collect you. She has a task for you and de little beast to complete.\n\nJo'nok's loa is patient, but he would not keep her waiting.", objectives = "Speak to Torcali in the Savagelands.", completion = "<The great direhorn regards you with one enormous eye. A voice enters your mind.>\n\nI am pleased by what I see. I would ask more of you, now." }
WordHunterWoW_QuestEN[55463] = { title = "Aid From Nordrassil", description = "Look at what they've done to this island, {name}.\n\nNature is nearly extinguished, its death cry falling on the deaf ears of mechagnomes.\n\nBut I have heard the teeny tiny animals of Mechagon, and bring aid from afar!\n\nIt won't be easy to restore balance to a land so severely wounded. Nature's scars run deep here.\n\nThankfully, we are not alone. I've brought living sap from Nordrassil, the World Tree of Mount Hyjal. Use it to regrow the forests and speed nature's recovery in this land.", objectives = "Kill 8 Sawblade Clearcutters and use the Living Sap of Nordrassil to regrow 8 stumps.", completion = "A small steps towards bringing balance to Mechagon.\n\nI thank you, <name>. And so do the adorable lil' animals who will find home in those trees you grew. I will report our progress back to the druids of Nordrassil." }
WordHunterWoW_QuestEN[55465] = { title = "We Must Go Deeper", description = "These shards can only do so much in their current state. They are broken and scattered... not unlike my kin.\n\nWe must bring them together.\n\nLet us go deeper into the Emerald Dream. I know of a place where we can reforge the shards into a dragonscale. With it, you can empower the Heart of Azeroth with the essence of my dragonflight. We must go to the ancient heart of the Dream, where my mother once rested.\n\nSpeak with me when you are ready to delve deeper.", objectives = "Speak to Merithra to travel deeper into the Emerald Dream.", completion = "The extent of the corruption is more dire than I thought. My mother used to love this place... and now it withers within the Void's grasp." }
WordHunterWoW_QuestEN[55466] = { title = "Vuk'laz the Earthbreaker", description = "", objectives = "" }
WordHunterWoW_QuestEN[55469] = { title = "To Zin-Azshari", description = "We need something to deal with the guardian of the Tidestone, {name}.\n\nOur new allies here say that there is a naga enclave located in the ruins of Zin-Azshari. If there is anything potent enough to counter Azshara's sorcery, it will be in the ruins of her capital city.\n\nThe First Arcanist will accompany you, champion. She will be best equipped to assist you in matters both historical and magical while you search.\n\nGood luck.", objectives = "Meet First Arcanist Thalyssra in the ruins of Zin-Azshari.", completion = "Is that what I think it is?" }
WordHunterWoW_QuestEN[55481] = { title = "Scouting the Palace", description = "We cannot hide here forever, {name}. We have to deal with Azshara.\n\nWe will need to assault her palace but we do not know what defenses she has in place. I dispatched a scouting team while you were gone and they have not reported back.\n\nI cannot afford to lose any more people. Speak with Spiritwalker Ussoh. His abilities will let us see where the scouts are.", objectives = "Speak with Spiritwalker Ussoh to observe the scouting party.", progress = "Have you spoken with Ussoh yet?", completion = "The Tidestone! Of course...." }
WordHunterWoW_QuestEN[55482] = { title = "Making the Connection", description = "A communication crystal! Have they survived this long?\n\nWe used to use these to communicate. They allowed us to project images of ourselves to other nearby crystals to see and speak with those on the other end.\n\n<Thalyssra examines the crystal for a few moments.>\n\nThe magic has long since depleted from the crystal. We will need a power source, preferably something just as old as this.\n\nCheck our surroundings, but be careful. It is too quiet out here....", objectives = "Search the ruins of Kal'methir for magical relics.", progress = "Have you found anything to power the crystal?", completion = "This should work if they have sufficient power...." }
WordHunterWoW_QuestEN[55483] = { title = "[PH] Stop Rituals", description = "", objectives = "" }
WordHunterWoW_QuestEN[55484] = { title = "[PH] Collect Cleansing Motes", description = "", objectives = "" }
WordHunterWoW_QuestEN[55485] = { title = "Terrors in the Deep", description = "Azshara knows we are here. Still, we must press on.\n\nBe careful, though. There is a... wrongness coming from the water. It is unlike the magic of old, but more ancient and terrible.\n\nTraverse the canals and find the source of corruption. If we are to search Zin-Azshari, we cannot let any relics fall into the hands of even darker powers.", objectives = "Defeat 10 corrupted creatures and the source of the corruption.", completion = "His influence is spreading..." }
WordHunterWoW_QuestEN[55486] = { title = "Secrets of Telemancy", description = "The nightborne are no strangers to this place. It was once our capital too, long ago.\n\nBefore the Sundering and erecting the shield over Suramar we used to travel freely to Zin-Azshari. Oculeth had a workshop in these estates. \n\nPerhaps it might contain some secrets or magic that went undisturbed by the survivors.", objectives = "Investigate Oculeth's old workshop.", progress = "Have you found the workshop yet?", completion = "Why am I not surprised. Still, these notes may prove useful." }
WordHunterWoW_QuestEN[55487] = { title = "[PH] Warding Scrolls", description = "", objectives = "" }
WordHunterWoW_QuestEN[55488] = { title = "Speak with the Dead", description = "So many souls perished beneath the waves. Too many sacrificed for her ambition.\n\nIt is strange that the spirits here have not departed. I wonder if they even know they are dead?\n\nStill, their knowledge might be useful to us. If you could question the spirits, they might be able to point us in the right direction.", objectives = "Question the spirits in the Highborne Estates to discover something useful.", completion = "The Javelins? I thought them lost!" }
WordHunterWoW_QuestEN[55489] = { title = "The Handmaiden's Tale", description = "The Javelins of Suramar!\n\nWielded by Azshara herself, they contain immense magical power. She has always had a fondness for bestowing favors on her favorites, but I never suspected she would give one something so valuable as one of her Javelins. This foe must be formidable indeed.\n\nNevertheless, {name}, we cannot let this opportunity pass us. Defeat the handmaiden and retrieve the relic!", objectives = "Retrieve the Javelin of Suramar.", progress = "We cannot let her get away.", completion = "This just might work." }
WordHunterWoW_QuestEN[55490] = { title = "We'll Poke Their Eye Out", description = "The Javelins were some of Suramar's finest creations before the Sundering. Their magic is ancient and potent. Perhaps strong enough to defeat Azshara's wards.\n\nHurry back to Newhome. We must tell the others of our success here. You have done well.", objectives = "Return to Lor'themar Theron in Newhome.", completion = "With this, we can secure the Tidestone." }
WordHunterWoW_QuestEN[55497] = { title = "A Friendly Face", description = "An essence of black dragonflight magic is not to be trifled with, {name}.\n\nMy flight has been the pawn of dark forces in the past. I owe it to my fallen kin to see that our power is never used for evil again.\n\nI would like to journey with you and meet your allies. Perhaps my knowledge can help you use this essence to defend our world.", objectives = "Meet with Spiritwalker Ebonhorn and Magni Bronzebeard in the Chamber of Heart.", progress = "Was MOTHER's analysis correct?", completion = "I like this tauren friend o' yers. Here's hopin' he stays free o' corruption!\n\nOkay, time tae see what MOTHER can do with that essence!" }
WordHunterWoW_QuestEN[55498] = { title = "The Shimmering Crystal", description = "Though the crystal appears familiar at first, upon contact with your finger it reveals itself as so much more. A grand, lost civilization appears in front of you. Fixtures of gold shimmer in every direction, bright feathers of purple occasionally falling from overhead. You hear the distant sounds of battle, culminating in a thunderous explosion that overwhelms all of your senses and turns your vision white.\n\nWhen your vision returns, you feel something within you pulling you toward Ashran.", objectives = "Bring the Shimmering Timewarped Crystal to Tempra in Stormshield.", completion = "I've always been fascinated with The Age of Order, but never have I found such an interesting crystal. \n\nI will study this artifact. Perhaps I chose the right time to conduct my research." }
WordHunterWoW_QuestEN[55499] = { title = "The Shimmering Crystal", description = "Though the crystal appears familiar at first, upon contact with your finger it reveals itself as so much more. A grand, lost civilization appears in front of you. Fixtures of gold shimmer in every direction, bright feathers of purple occasionally falling from overhead. You hear the distant sounds of battle, culminating in a thunderous explosion that overwhelms all of your senses and turns your vision white.\n\nWhen your vision returns, you feel something within you pulling you toward Ashran.", objectives = "Bring the Shimmering Timewarped Crystal to Kronnus in Warspear.", completion = "The Age of Order shaped much of Draenor's future in many timelines. With each new artifact we find, we learn more about their development and demise, the commonalities and dissonances between each branch.\n\nThis artifact is the most peculiar of all. You did well to bring it to me." }
WordHunterWoW_QuestEN[55500] = { title = "Save A Friend", description = "In the cave ahead is where they are holding Mak. \n\nThey torture us. They break us. \n\nDon't let them take her, too.", objectives = "Kill the Herald of the Queen to release Mak.", completion = "We are deeply in your debt, land friend." }
WordHunterWoW_QuestEN[55503] = { title = "The Direhorn and the Saurid", description = "<A gentle voice enters your mind.>\n\nI am pleased with your efforts. He will not soon forget the kindness you have shown him, and so he will not soon forget me.\n\nNow your journey will take you south. I can no longer sense one of my wayshrines. If you can determine what has happened to it and restore it, I would be grateful.", objectives = "Discover the fate of the central wayshrine.", progress = "What did you learn?", completion = "<An amused voice enters your mind.>\n\nAh, the trickster Jani thought to amuse himself at my expense. I suppose that is the payment I have earned for stepping on his tail.\n\nThank you. This shrine will once again serve the Zandalari." }
WordHunterWoW_QuestEN[55504] = { title = "Wayshrines of Zuldazar", description = "<A calm but thunderous voice enters your mind.>\n\nMy child grows under your care. I am pleased. Now, I would have your aid.\n\nThere was a time long ago when the roads of Zandalar were under my protection. Those who walked them gave praise, and in return I gave them my blessing. Fewer wander now.\n\nMy shrines remain, their purpose forgotten. You will help me to restore them.\n\nBegin in the north. See to the wayshrine there. If you find any lost travelers, see that they know my blessing through you.", objectives = "Restore the northern wayshrine and assist any travelers you come across.", progress = "Do you have de herbs?", completion = "Most of my goods have spoiled in de heat and rain, but take dis token of my appreciation.\n\nWe can finally go home." }
WordHunterWoW_QuestEN[55505] = { title = "Roo'li's Memory", description = "I was going to be a Dinomancer. Roo'li was going to grow with me as I learned.\n\n<Koo'li shakes her head.>\n\nDat future is gone now. Please, take him. Find a proper place to bury him.\n\nI... can't. De shame is too great.", objectives = "Take Roo'li's remains to Torcali.", progress = "<The great direhorn loa stares down at you.>\n\nWhat do you bring me, <name>?", completion = "<Torcali's voice rings in your mind.>\n\nHis time walking this world is done, but he will not be forgotten. He is returned to the soil, and with it his spirit lives on." }
WordHunterWoW_QuestEN[55506] = { title = "One Road Ends", description = "<A warm voice enters your mind.>\n\nThere is one more wayshrine in this region that requires your attention.\n\nFollow this road until you near its end at the Port of Zandalar.\n\nIt is there, at the start and end of so many journeys, that one of my most trafficked shrines was established. Restore it and see that any weary travelers have my blessing.\n\nWe will speak again when you are finished.", objectives = "Restore the southern wayshrine and assist any travelers you come across.", progress = "Roo'li... Oh, Roo'li....", completion = "I should have protected him, but he stood his ground. Fierce little thing.\n\n<Koo'li pats Roo'li's head.>" }
WordHunterWoW_QuestEN[55507] = { title = "Torcali's Blessing", description = "<Torcali's voice enters your mind.>\n\nYour actions speak to your intentions, {name}.\n\nI can see that my child will have the care she needs to grow strong, and grow she will. \n\nIn the coming days she will recover the strength that would have been hers, if nature had been allowed to take its course. Tend to her, earn her loyalty, and I will allow you to keep her at your side.\n\nThis is my gift to you.\n\nYou may go now. She will bring you to me when it is time.", objectives = "Return the Child of Torcali to her nest in Warbeast Kraal.", completion = "<The Child of Torcali peers trustingly up at you.>" }
WordHunterWoW_QuestEN[55508] = { title = "Victory in Wintergrasp", description = "Commander Zanneth might be satisfied with a pile of Horde corpses at his feet, but controlling Wintergrasp is of the utmost importance to the Valiance Expedition. Make sure it remains in our control.\n\nHowever, don't think we'll just let you stand around while your allies do your dirty work for you. If you're not at least a second level recruit by the end of the battle, don't come back.", objectives = "Win a Wintergrasp battleground match. You must have participated in the battle to be credited for the victory. Quest can only be auto completed while within the Battle for Wintergrasp.", completion = "Just what I wanted to hear!  A victory in Lake Wintergrasp - even a temporary one - is crucial to our overall strategy against the Horde." }
WordHunterWoW_QuestEN[55509] = { title = "Victory in Wintergrasp", description = "While Dardosh might be content with slaying our foes, it is of the utmost importance that we control Wintergrasp Fortress. Do whatever it takes to ensure Wintergrasp is ours.\n\nHowever, don't think we'll just let you stand around while your allies do your dirty work for you. If you're not at least a second level recruit by the end of the battle, don't come back.", objectives = "Win a Wintergrasp battleground match. You must have participated in the battle to gain credit for the victory. Quest can only be auto completed while within the Battle for Wintergrasp.", completion = "It is a truly great thing you have accomplished this day. Be recognized for your sacrifice!" }
WordHunterWoW_QuestEN[55510] = { title = "No Mercy for the Merciless", description = "Welcome to Wintergrasp, {name}. Your mission is simple. Defeat ten of the Horde's finest. Now, go! Bring victory to the Alliance!", objectives = "Commander Zanneth in Wintergrasp Fortress wants you to slay 10 members of the Horde. Quest can only be auto completed while within the Battle for Wintergrasp.", completion = "Glorious! Truly, you are among the champions of the Alliance." }
WordHunterWoW_QuestEN[55511] = { title = "Slay them all!", description = "Welcome to the Wintergrasp, {name}. Warlord Garrosh demands one thing: Slay them all!\n\nReturn to me when ten of the strongest members of the Alliance are dead.", objectives = "Commander Dardosh in Wintergrasp wants you to slay 10 members of the Alliance. Quest can only be auto completed while within the Battle for Wintergrasp.", completion = "Lok'tar! Victory for the Horde!" }
WordHunterWoW_QuestEN[55516] = { title = "Spark of Genius", description = "{name}, I require your assistance.\n\nA recent energy signature tripped several detection relays I installed after that unfortunate incident with Sargeras.\n\nInitial diagnostics suggest that these energies emanate from Hati, a legendary creature of lightning magic. This wolf was linked to the Titanstrike artifact, a weapon that proved instrumental in defeating the Legion!\n\nHati's spirit is still bound to Titanstrike's core, so I'll need your help. Meet me at my library in the Storm Peaks right away!", objectives = "Meet Mimiron at the Inventor's Library in the Storm Peaks.", completion = "Our scientific team simply would not be complete without Bronzebeard here.\n\nLet's begin!" }
WordHunterWoW_QuestEN[55517] = { title = "Paint Vial: Big-ol Bronze", description = "<Marvelous Martini could make use of this item.>", objectives = "Deliver the item to Marvelous Martini.\n\nProvided item:", completion = "One of my favorites!" }
WordHunterWoW_QuestEN[55519] = { title = "A Fresh Trauma", description = "Azeroth is strugglin' tae survive, but new wounds are formin' at a rapid pace.\n\nI can sense her cries o' pain risin' from the north... in a place o' ancient power...\n\n<Magni closes his eyes, as if listening to an unseen voice.>\n\nBy the Forge! Somethin's gone wrong in Mount Hyjal. The World Tree, Nordrassil, is in danger!\n\nMeet me there, {name}. There's no time tae lose!", objectives = "Meet Magni at Nordrassil in Mount Hyjal.", completion = "If we don't heal these wounds, the World Tree might not be standin' much longer." }
WordHunterWoW_QuestEN[55520] = { title = "Healing Nordrassil", description = "Azerite elementals are runnin' wild, driven mad by Azeroth's pain. They're menacin' the spirits o' nature that protect the World Tree.\n\nThe roots o' Nordrassil run deep, nurtured by these sacred waters. For the sake o' Azeroth's world soul, the tree must be defended.\n\nQuiet the restless elementals and use yer Heart o' Azeroth tae mend the wounds ye find. We cannae let Hyjal become another gapin' scar like Silithus!", objectives = "Defeat Azerite elementals and seal Azeroth's injuries at Nordrassil.", progress = "This just keeps gettin' worse. If too many wounds open up, we may not be able tae stop the cascade.", completion = "Ye did it, <name>! I can feel her pain diminishin'.\n\nAnd the Heart seems tae be even stronger now!" }
WordHunterWoW_QuestEN[55521] = { title = "Do It the Azerite Way", description = "Incredible! Ye stopped the wound from spreadin' before it could get out o' control!\n\nNordrassil should be safe again, fer now. This is a good sign that we may just be able tae reverse all the damage done tae Azeroth.\n\nLet's get back tae the Chamber o' Heart, an' see if we can put any o' that azerite ye absorbed tae good use.", objectives = "Return to the Chamber of Heart.", completion = "Additional azerite available for Heart of Azeroth. Activating now." }
WordHunterWoW_QuestEN[55522] = { title = "Return to the Heart", description = "Greetings, Champion of Azeroth.\n\nMOTHER's been monitorin' yer progress with the Heart of Azeroth, and is mighty pleased with the work you've done tae make it stronger.\n\nAt least, we think she's pleased. It's difficult tae tell at times.\n\nRegardless, come back tae the Chamber of Heart when ye've got a chance. There's more that needs doin'.", objectives = "Return to the Chamber of Heart.", completion = "The Heart o' Azeroth feels stronger than ever. I wonder what amazing powers might be locked within!" }
WordHunterWoW_QuestEN[55523] = { title = "Bring Him Some...", description = "<Mrrl points at your backpack then draws some pictures in the sand. He pulls out a pretty object from behind a rock then furiously points to himself then back at you then your bag.\n\nYou believe it might want to make a trade.>", objectives = "Locate murloc traders and obtain the items that Mrrl requires." }
WordHunterWoW_QuestEN[55524] = { title = "Bring Him Some...", description = "<Mrrl points at your backpack then draws some pictures in the sand. He pulls out a pretty object from behind a rock then furiously points to himself then back at you then your bag.\n\nYou believe it might want to make a trade.>", objectives = "Bring Mrrl 5 Ghost Food, 5 Smelly Piles of Gloop, and 5 Sea Giant Foot Dust." }
WordHunterWoW_QuestEN[55525] = { title = "Bring Him Some...", description = "<Mrrl points at your backpack then draws some pictures in the sand. He pulls out a pretty object from behind a rock then furiously points to himself then back at you then your bag.\n\nYou believe it might want to make a trade.>", objectives = "Bring Mrrl 4 Healthy Murloc Lunches, 3 Bags of Who-Knows-What, and 6 Sea Giant Foot Dust." }
WordHunterWoW_QuestEN[55526] = { title = "Bring Him Some...", description = "<Mrrl points at your backpack then draws some pictures in the sand. He pulls out a pretty object from behind a rock then furiously points to himself then back at you then your bag.\n\nYou believe it might want to make a trade.>", objectives = "Bring Mrrl 15 Extra-Slimy Snails, 3 Smelly Piles of Gloop, and 5 Ghost Food." }
WordHunterWoW_QuestEN[55527] = { title = "Bring Him Some...", description = "<Mrrl points at your backpack then draws some pictures in the sand. He pulls out a pretty object from behind a rock then furiously points to himself then back at you then your bag.\n\nYou believe it might want to make a trade.>", objectives = "Bring Mrrl 3 Ghost Food, 3 Healthy Murloc Lunches, and 3 Sea Giant Foot Dust." }
WordHunterWoW_QuestEN[55528] = { title = "Playtime's Over", description = "The troggs have been raiding our supplies since we got here, but now that we got some fire power you're going to put a stop to that!\n\nLet's teach them troggs to stay away from our stuff!", objectives = "Eliminate 12 Troggs.", progress = "Take out some troggs.", completion = "You earned your salary, <race>!" }
WordHunterWoW_QuestEN[55529] = { title = "No Backs", description = "<The murloc seems hungry. Next to it is a series of crude drawings which seems like a shopping list. Perhaps you can help the creature.>", objectives = "Bring Mrrl a Sweet Sea Vegetable, an Unidentified Mass, a Flatulent Fish, and a Slimy Naga Eyeball.", progress = "Locate murloc traders and obtain the items that Mrrl requires.", completion = "<Mrrl eats the Slimy Naga Eyeball, squeezes the Flatulent Fish, rubs the Unidentified Mass on its feet, then throws the Sweet Sea Vegetable.\n\nIt looks satisfied.>" }
WordHunterWoW_QuestEN[55530] = { title = "A Safer Place", description = "<The murloc seems to be in rough shape. Perhaps it would be safer with your allies in Newhome.>", objectives = "Escort Mrrl back to Newhome.", completion = "<Mrrl seems at home in his new spot and his family has also taken up refuge here. It is unlikely you will be able to remove this new murloc infestation.>" }
WordHunterWoW_QuestEN[55531] = { title = "What Will It Mine?", description = "<Although worn from repeated use, the pickaxe still seems salvageable. Perhaps there's something nearby that can be mined?>", objectives = "Complete the Brinestone Cove event.", progress = "What have you brought me?", completion = "Ah, what do we have here? A rare find, indeed! \n\nBrinestone is quite volatile and should only be mined with special equipment. \n\nEven then, its collection frequently disturbs the elements, so mine with caution." }
WordHunterWoW_QuestEN[55533] = { title = "MOTHER Knows Best", description = "Now that this chamber's not fallin' tae pieces anymore, we can focus on makin' the Heart stronger!\n\nMOTHER says she's finished her fancy calculations. Have a word with her, champion. See if we can further empower the amazin' gift Azeroth gave ye.", objectives = "Speak to MOTHER in the Chamber of Heart.", progress = "Report: Ready for dissemination.\n\nChampion's response: Critical.", completion = "Analysis complete. In order to prevent planetary annihilation, Heart of Azeroth must be enhanced.\n\nObjective: Seek out compatible essences. Priority: Critical." }
WordHunterWoW_QuestEN[55534] = { title = "Rustbolt Gramophone", description = "<The large gramophone that you crafted is capable of blasting music across all of Rustbolt.\n\nNow, you just need to find a good place to install it.>", objectives = "Install the gramophone in the Rustbolt bar, The Tipsy Tinkerer.\n\nProvided item:", completion = "<This looks like a great place to install the gramophone.>" }
WordHunterWoW_QuestEN[55535] = { title = "The Tipsy Tinkerer", description = "The massive kegerator that you built should be able to house all of the Rustbolt Resistance's beverages.\n\nFind a spot to set it up in Rustbolt, and let the town know it's ready for use!", objectives = "Install the Rustbolt Kegerator in Rustbolt's bar, The Tipsy Tinkerer.The massive kegerator that you built should be able to house all of the Rustbolt Resistance's beverages.\n\nFind a spot to set it up in Rustbolt, and let the town know it's ready for use!", completion = "This looks like a great place to install the kegerator." }
WordHunterWoW_QuestEN[55558] = { title = "A Bolt Hole", description = "{name}, we must seek out a powerful weapon to combat the naga who guard the Tidal Conflux. I am certain such an object would be in the hands of one of Azshara's minions.\n\nThanks to our new allies, we've tracked down the location of one of her handmaidens within the ruins of Zin-Azshari. The journey will be quite dangerous. Thankfully our allies have a location nearby that we can use as a staging ground.\n\nI've marked the location on your map, meet with me there as soon as you can.", objectives = "Meet with Shandris Feathermoon at Utama's Stand.", completion = "Yes. This place will do nicely. It is easily defended and has safe access to the ruins." }
WordHunterWoW_QuestEN[55560] = { title = "Utama's Vengeance", description = "We Ankoan are a small tribe. There are not that many of us remaining.\n\nThis place was once overrun with makrura, before Utama. They tried to hide here, from the naga, but found the makrura. They fell, in battle, to the Kil'karrok.\n\nIf you wish to show your dedication to the Ankoan, become a force of vengeance in Utama's memory. Destroy the makrura.", objectives = "Kill 10 Makrura.", progress = "We remember Utama. And honor their memory here.", completion = "You do Utama great honor by killing his foes." }
WordHunterWoW_QuestEN[55561] = { title = "What Remains of Zin-Azshari", description = "Zin-Azshari, once the capital of night elf civilization, was lost during the Sundering. Queen Azshara betrayed her people and allowed N'Zoth to corrupt them, turning them into naga.\n\nIt has now fallen into ruin and chaos.\n\nWe must see what it has become. Meet me by the statue of Azshara.", objectives = "Meet Shandris at the statue of Azshara.", completion = "You must venture deeper into the city." }
WordHunterWoW_QuestEN[55565] = { title = "Shoring Up Mana Reserves", description = "Holding back the tide walls is not an easy task, even using the Tidestone. The ebb and flow of the magical energies in the area are too inconsistent.\n\nWe need to shore up our magical reserves, which requires mana batteries, if you will. The befouled elementals along the canal here are created with exactly the elemental cores we need.\n\nThe goal is two fold. Clearing out the befouled elementals, before their corruption spreads, but also retrieving their cores, so we can keep the water at bay.", objectives = "Collect 10 Elemental cores.", progress = "How goes your hunt?", completion = "We will get these back to Admiral Proudmoore." }
WordHunterWoW_QuestEN[55569] = { title = "Echoes of Pain", description = "These spirits... they are the Highborne. They were those Azshara held close. Azshara often played favorites, but these people... they were her favorites.\n\nI do not know why their spirits are here. We should investigate further. See if you can communicate with them and find out why their spirits cling to these ruins.\n\nHow could she abandon them?", objectives = "Speak with the spirits who wander around the Highborne Estates.", completion = "I feel such sadness for these spirits. Eternally locked to this place, reliving the worst day of their lives." }
WordHunterWoW_QuestEN[55570] = { title = "Secrets in the Ruins", description = "This was once a place of great power. The highborne who lived here would host lavish parties, living in splendor.\n\nZin-Azshari was once on the shores of the Well of Eternity and drew powerful mages from all over the empire to study here. I suspect, despite the many years at the bottom of the sea, there are still treasures and powerful artifacts hidden away here.\n\nSpeak with the spirits that remain and see what you can find. There must be something to help us overcome the Guardian of the Tidestone.", objectives = "Search for items of power.", progress = "What have you discovered, <name>?", completion = "The Javelins of Azshara? I've never heard of such an item. Unless they mean the Javelins of Suramar? That would be a wondrous find!" }
WordHunterWoW_QuestEN[55571] = { title = "Help Them See the Truth", description = "The information you have gleaned concerns me, {name}. These spirits cling to this place because they still, even now, believe in Azshara and her reign. She sold their lives to the void and they still believe in her.\n\nI know we have concerns that outweigh this, but I cannot leave them here like this.\n\nShow them. Confront them and tell them of Azshara's betrayal.", objectives = "Confront the spirits about Azshara.", progress = "Have the spirits been put to rest?", completion = "Many of the spirits who haunt Zin-Azshari do not know they are dead. They will not admit it to themselves.\n\nWe might be able to help them. If you are willing to help me." }
WordHunterWoW_QuestEN[55573] = { title = "Purging the Defilers", description = "Azshara always did need everything to be about her. Everything had to have her name on it. Everything was for her glory. She forgot our people's connection to Elune. Or perhaps she believed it did not matter?\n\nAzshara and her minions have too long defiled this place with their heresy.\n\nLet us show them Elune's vengeance.", objectives = "Purge the naga from Elun'alor.", completion = "Elune's vengeance is swift and fierce. Well done, <name>." }
WordHunterWoW_QuestEN[55574] = { title = "The Javelins of Azshara", description = "These spirits keep speaking of the Javelins of Azshara. At first, I believed it to be referring to the handmaidens, who are currently holed up in Elun'alor.\n\nBut -- now I think they are referring to the Javelins of Suramar. They were powerful weapons -- long thought lost. Azshara does like to claim things as her own.\n\nWe need to defeat her handmaiden in Elun'alor regardless. Seizing the Javelins would be an amazing stroke of fortune.", objectives = "Kill the Handmaiden of Azshara.", progress = "Killing her handmaidens will drive the naga back and out of Zin-Azshari.", completion = "Killing a handmaiden alone would have been an amazing victory. Retrieving the Javelins of Suramar as well? Today is the turning point. Today, we have created the path to victory." }
WordHunterWoW_QuestEN[55575] = { title = "One Gnome's Trash", description = "The garbage in these trash heaps is full of rare metals: Dalaranium, Suramarite, even Gnomeisium! \n\nI've not seen this much easy gold to be had, since they left the vault door open in Boralus! You help me collect some of the metal, and my friend Gao will sell it on the black market.\n\nI've got a device that can tear the metal right out of the trash!", objectives = "Collect 100 rare metals using the rare metal collector.", progress = "There's gold to be made!", completion = "This is going to sell quickly, here's your share of the profits to be!" }
WordHunterWoW_QuestEN[55578] = { title = "Tol Dagor: Jewel of the Tides", description = "<As you peer at the shrine in front of you, you can't help but revel at the construction of it.\n\nSeamlessly constructed with azure jewels placed just so in a radial pattern, collapsing towards a single point.\n\nA single, empty point. An absence you assume to be a mistake. Quickly surveying the area for something that might fit there, you find nothing.\n\nHowever, there appears to be a drunk here shouting at the shrine. Perhaps he might know the whereabouts of the shrine's missing piece.>", objectives = "Speak with \"Slippery\" Salton and learn what you can about the missing centerpiece.", progress = "<Perhaps finding the missing centerpiece will give you a clue into the shrine's operation?>", completion = "<As you affix the gem back into the center of the shrine, a strange pulse emanates from it.\n\nThe shrine, now whole again, begins to hum with energy.>" }
WordHunterWoW_QuestEN[55579] = { title = "Cracking the Surface", description = "<Upon your investigation you discover that the shrine has a couple locations where jewels appeared to have been located, but no longer exist.\n\nAdditionally, the center jewel appears to have several cracks in it as well.\n\nChecking your notes, the earthen mentions having prospected the jewels from a nearby mountain to the northwest.\n\nPerhaps you can prospect the earth in that area to find more of those jewels.>", objectives = "Go to the Windshorn Hills and gather 20 Shard of Golden Beryl.", progress = "<The placement of the jewels on this shrine appear to be placed in a rather intricate fashion.>", completion = "Using your tools, you carefully shape the jewels and affix them into the empty slots on the shrine.\n\nUsing the remainder, you are able to fill in the cracks of the center jewel, giving it a flush surface.\n\nAs you place the final jewel, a similar pulse of energy radiates from the shrine as the light in the area seems to draw into it. A strange glow now emanating from the shrine leads you to believe it is once again active." }
WordHunterWoW_QuestEN[55580] = { title = "High Prospects", description = "<Inspecting the shrine, you realize that several of the gems embedded on its surface are cracked and need to be replaced.\n\nChecking your notes, you find that the earthen had extracted the gems from some earth elementals to the south.\n\nLooking at your map, you wonder if he was referring to the now ruins of a once ancient settlement that has become littered with constructs and undead.\n\nPerhaps investigating there will yield some clues as to where to find these jewels.>", objectives = "Investigate Gol Osigir for clues about the jewels that were used to construct the shrine.", progress = "<All of the cracked jewels will definitely need to be replaced.>", completion = "<You begin to remove all the cracked gems from the shrine and carefully start placing the new ones in.\n\nPlacing the final one, a pulse radiates from the shrine, as the light in the area seems to draw into it.\n\nThat strange, similar glow now emanating from the shrine leads you to believe it is once again active.>" }
WordHunterWoW_QuestEN[55581] = { title = "Sun-Speckled Dunes", description = "<Surveying the shrine, you believe that the sandy winds in this area have worn down the embedded gems, producing odd shapes and cracks in some.\n\nLooking at your notes, the earthen mentions coming across dunes sprinkled with orange gems. He said it reminded him of the soft sunlight in this area.\n\nChecking your notes, it appears that these dunes were located south of your current location.>", objectives = "Go to the location on your map where you believe these gems to be and recover 8 of them. Polish and shape them when you've collected enough.", progress = "<These gems have a very strong structure. Time, in addition to the winds, must have also taken its toll on them.>", completion = "<You carefully remove the old, weathered gems from the shrine and replace your polished gems in their place.\n\nAs you place the final gem, a similar pulse of energy radiates from the shrine as the light in the area seems to draw into it. A strange glow now emanating from the shrine leads you to believe it is once again active.>" }
WordHunterWoW_QuestEN[55582] = { title = "Atal'Dazar: Not All That Glitters...", description = "<As you observe the shrine, it's quite clear that the central jewel is badly broken and in need of replacement.\n\nYou reference your notes on the shrine and discover that these jewels came from a \"golden sanctuary\".\n\nGiven your location, that can only mean Atal'Dazar. Perhaps you could find a replacement from that ancient city.>", objectives = "Travel to Atal'Dazar and find a replacement for the broken jewel.", progress = "<When you're done replacing the central gem, you think you might still be able to sell the old one.>", completion = "<Returning to the shrine, you begin to pluck the old gem from its holding place. As you do, the gem cracks again and shatters in your hands.\n\nApparently these gems are much more fragile than you originally thought.\n\nVery carefully, you replace the gem you obtained into the slot.\n\nOnce affixed, a peaceful glow now emanating from the shrine leads you to believe it is once again active.>" }
WordHunterWoW_QuestEN[55583] = { title = "Out With the Old", description = "<Upon inspection of the shrine, you notice something... familiar. The cut of the gems looks like a primitive or simple version of the way you've learned to cut rubellites.\n\nIt's clear though that time has had its way with these gems, some eroded and chipped in places.\n\nRepairing this shrine may be as simple as replacing the old gems with newer ones of the same type and cut.>", objectives = "Cut 4 Natant Rubellites and replace the old ones with the new.", progress = "<Interesting that the cut should be so similar, you wonder how the design has persisted all these years.>", completion = "<Replacing each gem, they fit perfectly into the slots confirming your suspicions of their similarities.\n\nAs you place the final gem, the familiar pulse radiates once more from the shrine and the glow emanating from it confirms its restoration.>" }
WordHunterWoW_QuestEN[55585] = { title = "A Promising Beginning", description = "<The shrine now repaired, you find yourself eager to seek out the next shrine.\n\nPerhaps Samuel has come across more locations.>", objectives = "Return to Samuel D. Colton III in Boralus and report on your discovery.", completion = "<You recount your findings of the Shrine of Storms to Samuel.>\n\nAnd you were able to repair the shrine? That's excellent news. Perhaps the next two will have a similar situation given their age and potential disuse." }
WordHunterWoW_QuestEN[55586] = { title = "Polished Up", description = "<Samuel will surely want to hear about your progress on this shrine.\n\nYou feel as though you should report back to him as soon as you're able.>", objectives = "Return to Samuel D. Colton III in Boralus and report on your discovery.", completion = "<You recount your findings about the shrine in Drustvar to Samuel.>\n\nHow fortunate for us that the inhabitants of that area used the same rocks to create their constructs from.\n\nI suppose luck is on our side in the quest for these shrines." }
WordHunterWoW_QuestEN[55590] = { title = "Setting Things Right", description = "<Samuel will surely be interested to hear about your investigation into this shrine.\n\nMost assuredly the part where you had to fight your way through a prison.>", objectives = "Return to Samuel D. Colton III in Boralus and report on your discovery.", completion = "Oh, back already? That seemed quick. How'd it go?\n\n<You recount your finding of the shrine and the replacement of the gems.>\n\nThat does sound like quite the adventure! Excellent work, <name>." }
WordHunterWoW_QuestEN[55591] = { title = "Expedition Demolisher", description = "", objectives = "" }
WordHunterWoW_QuestEN[55592] = { title = "A Promising Beginning", description = "<The shrine now repaired, you find yourself eager to seek out the next shrine.\n\nPerhaps Seshuli has come across more locations.>", objectives = "Return to Seshuli in Dazar'alor and report on your discovery.", completion = "So de shrine used de same cut of gems we use? To think dat design has survived all dese years.\n\nYou know, dat may be de oldest recorded cut in history. Maybe even de first!\n\nBut it's good to hear you were able to repair de shrine. Maybe de other two will need to be fixed too, seeing as how dey are very old." }
WordHunterWoW_QuestEN[55593] = { title = "Insight into Our Enemies", description = "There's no telling what awaits us within this land. We cannot press forward without first knowing exactly what we're up against. \n\nOur new allies have long been embattled with the naga. They would know best how to navigate these waters. \n\nSpeak with Blademaster Okani and see if they can provide some insight into how our enemies operate.", objectives = "Speak to Blademaster Okani to learn more about the naga within Nazjatar.", completion = "You wish to know more about the naga of Nazjatar? \n\nI am afraid these waters are as new to me as they are to you, but we may still be able to help each other." }
WordHunterWoW_QuestEN[55594] = { title = "Polished Up", description = "<Seshuli will surely want to hear about your progress on this shrine.\n\nYou feel as though you should report back to her as soon as you're able.>", objectives = "Return to Seshuli in Dazar'alor and report on your discovery.", completion = "<You recount your findings about the Vol'dun shrine to Seshuli>\n\nDat desert is a fools home if ya ask me. Good thing de shrine still stands dere and you were able to fix it.\n\nI'm still reading de journal trying to gather more information for you." }
WordHunterWoW_QuestEN[55595] = { title = "Deteriorating Knowledge", description = "My clan came to Nazjatar, eager to destroy the naga queen. \n\nWe were not prepared for the darkness that she commands. \n\nOur scouts knew this land best, but their knowledge now deteriorates as their minds are controlled by Azshara's forces. \n\nFind and free our scouts, and you may still have a chance to access their knowledge.", objectives = "Rescue Imara, Adaru, and Umai from the clutches of mind-leeching Zoatroids.", completion = "Compelled to do the mindless bidding of our enemies is a fate worse than death. \n\nThere is no honor in that life." }
WordHunterWoW_QuestEN[55596] = { title = "Setting Things Right", description = "<Seshuli will surely be interested to hear about your investigation into this shrine.\n\nMost assuredly the part where you had to fight your way through Atal'Dazar.>", objectives = "Return to Seshuli in Dazar'alor and report on your discovery.", completion = "<You recount your experience at the shrine with Seshuli.>\n\nTraveled ta Atal'Dazar, eh? Dat place is quite amazing from what I remember.\n\nStill though, great job on repairing de shrine." }
WordHunterWoW_QuestEN[55597] = { title = "Bound by Honor", description = "It is true that my clan has been battling the naga for generations, but it was only in recent times that we took the fight to Nazjatar. \n\nOur leader was slain by the vile queen, and now honor binds my clan to this deep ocean. \n\nWe will avenge their death or die here trying. It is our way. \n\nYour mission aligns with our duty, so we will fight the naga together. \n\nSlay their forces and bring us one step closer to honoring our promise.", objectives = "Kill 10 naga within Zanj'ir Wash and the Deepsea Slave Pens.", completion = "You fight like an Ankoan. You bring my clan honor with your actions today." }
WordHunterWoW_QuestEN[55598] = { title = "What We Know of the Naga", description = "I owe you a debt. That much is clear. \n\nMy mind still reels from the zoatroid's influence, but I fear the others suffer more visible wounds. \n\nApply this salve to their wounds, and I will do my best to share what I know of the naga.", objectives = "Tend to the Ankoan's wounds and hear what Adaru has to say about the naga.", progress = "I will tell you what I know of the naga.", completion = "Whatever is hidden within the stronghold needs to be destroyed." }
WordHunterWoW_QuestEN[55599] = { title = "Scouting Undercover", description = "Entering the stronghold alone would be a death wish. \n\nThe Zanj'ir slaughter outsiders on sight. \n\nThe only way to get in without being killed is to appear to be under the effects of a zoatroid. \n\nEven then, the mind-shackled are put to work. \n\nYou must obey all commands, or they will know your mind is still your own. \n\nOnce the Zanj'ir believe you are mind-shackled, it should be easier to navigate their domain and uncover their secret.", objectives = "Scout Zanj'ir Terrace while pretending to be mind-shackled.", completion = "What use are you if you're not working?" }
WordHunterWoW_QuestEN[55600] = { title = "Sating Snapdragons", description = "It's time for the snapdragons to feed, but it's a job best left to someone a little more expendable. \n\nThe beasts will eat anything, including your arm if you don't move it away quickly enough. \n\nLuckily for you, they've developed a taste for Chitterspine Roe.", objectives = "Collect Chitterspine Roe and feed it to Savage Snapdragons.", completion = "I'm surprised they didn't make a meal out of you." }
WordHunterWoW_QuestEN[55601] = { title = "Coveted Crystals", description = "Locating the weapons cache should not be a problem once we have the proper tools. A little light and a lot of bioluminescent fluid is all that is needed.\n\nIt all seems rather simple, does it not? But the key is in the Deepsea Crystal used to refract the light. \n\nThe Bloodfin tribe covets these crystals, so you should have no trouble obtaining one.", objectives = "Collect a Deepsea Crystal from Hoarder Moarrgl.", progress = "Have you found the crystal?", completion = "I can see why the Bloodfin covet these crystals. The gem is unlike any I've seen before." }
WordHunterWoW_QuestEN[55602] = { title = "What Will It Lure?", description = "<Putrid and pungent, this lump of bait is the preferred food of skittering eels. Perhaps you can find infested waters nearby?>", objectives = "Chum the Eel Infested Waters.", progress = "What have you brought me?", completion = "Ah, what do we have here? A rare find, indeed! \n\nYou've been chumming the waters I see! \n\nJust be careful. \n\nEels aren't the only creatures that you'll attract with that bait." }
WordHunterWoW_QuestEN[55605] = { title = "NOT USED", description = "TBD Collect Spare Parts from anything on the island.", objectives = "Collect 200 Spare Parts in Mechagon." }
WordHunterWoW_QuestEN[55608] = { title = "Shop Project", description = "As a reward for all your help here, I was planning to fix this old mechaspider mount to give to you.\n\nI could use some more of your help though to get this project started!\n\nI'll need parts off a few of the bots nearby, and maybe you could talk to Cork Stuttgard at Bondo's Yard and see if you can get a Mechanobot Ignition system.", objectives = "Acquire Shellsteel Plating, Multi-Leg Chaindrive, and a Mechanobot Ignition.", progress = "Did you find those parts yet?", completion = "These parts will get us started, but there's a lot of work to do still." }
WordHunterWoW_QuestEN[55609] = { title = "Operation: Mechagon - The Mechoriginator", description = "My father's madness won't be contained to this island.\n\nKing Mechagon is creating a massive device capable of reversing the Curse of Flesh across the entirety of Azeroth!\n\nAny races forged by the Titans will return to their original state. For us gnomes, that means fully mechanical. For dwarves and troggs, stone. Vrykul, iron.\n\nThe list goes on, but most races aren't even ON the list. Anything not forged by the titans will be completely obliterated.\n\nWe must stop King Mechagon before it's too late!", objectives = "Enter Mechagon and defeat King Mechagon.", progress = "King Mechagon's madness threatens all of us. We must stop my father!", completion = "That robot... that AI... was not my father.\n\nMy father died the day he abandoned his body and soul for full mechanization. The day he betrayed our people.\n\nThe burden of leadership has rested on my shoulders for some time... Only now, do I feel I can embrace it.\n\nI will lead my people with wisdom, ingenuity, and humility. Thank you, <name>." }
WordHunterWoW_QuestEN[55613] = { title = "Tracking Quest", description = "", objectives = "" }
WordHunterWoW_QuestEN[55614] = { title = "Tracking Quest", description = "", objectives = "" }
WordHunterWoW_QuestEN[55617] = { title = "Expedition Siege Engine", description = "", objectives = "" }
WordHunterWoW_QuestEN[55618] = { title = "The Heart Forge", description = "Rise in Heart Forge energy levels indicates presence of black dragon essence.\n\nRecommendation: Initiate Heart Forge activation sequence.", objectives = "Speak with MOTHER to activate the Heart Forge.", progress = "Data calculations complete. Awaiting initiation of forge activation sequence.", completion = "Power source accepted. Forge activation complete." }
WordHunterWoW_QuestEN[55619] = { title = "Upgrade Your Vehicle (Optional)", description = "", objectives = "" }
WordHunterWoW_QuestEN[55622] = { title = "Drive It Away Today", description = "The mount's all polished up and looking great. We are almost done!\n\nI gave the Powercore Schematics to PASCAL-K1N6. He's ready to build us a new 500S-Cybergenic Powercore, once you get him the parts.\n\nWe install that powercore and you can drive this bot away today!", objectives = "500S-Cybergenic Powercore obtained.", progress = "Did you get the core?", completion = "They won't be stealing from us anymore!" }
WordHunterWoW_QuestEN[55625] = { title = "Pearls of Unimaginable Power", description = "Thousands of years ago, when the Well of Eternity was destroyed and this land plummeted to the depths of the ocean, a great storm of magical energy was unleashed.\n\nRemnants of this magical energy still exist today.\n\nGather the pearls from the ancient mana-infused clams. These enchanted pearls may be powerful weapons in our fight against the naga!", objectives = "Collect 8 Enchanted Pearls.", progress = "We must make use of every advantage in our fight against the naga.", completion = "You have done well. I can sense a powerful energy from emanating from within these pearls." }
WordHunterWoW_QuestEN[55627] = { title = "Tracking Quest", description = "", objectives = "" }
WordHunterWoW_QuestEN[55628] = { title = "Tracking Quest", description = "", objectives = "" }
WordHunterWoW_QuestEN[55630] = { title = "Let's Get It Started", description = "Those gnomes think busting up machinery is gonna stop a goblin like me from figuring out what all the tech in this place does?\n\nI ain't never seen a hunk of junk so busted up that ol' Skaggit and I can't get running smoother than the day it was made.\n\nTell ya what. You head around with Skaggit and see what you can piece back together.\n\nMeanwhile, I'll have a chat with our gnome friend here and see what she knows about all this tech.", objectives = "Repair the vault's machinery.", progress = "We'll have this place up and running in no time.", completion = "<Gazlowe's ears perk up and he listens intently for a few moments.>\n\nMachine sounds good. Few loose bolts and missing wires, but nothin' we'd really miss.\n\nNice work." }
WordHunterWoW_QuestEN[55632] = { title = "You Must be This Height", description = "You and the Greasemonkeys got this machine up and running even faster than I expected.\n\nThe gnome we captured is keeping her mouth shut, but that shouldn't be a problem. I can take it from here.\n\nLet me know when you're ready. I'll crank up this machine to max and we'll finally see what it can do.\n\nI hope it prints gold coins...", objectives = "Tell Gazlowe to activate the device.", progress = "That's the best use of a gnome I've ever seen!", completion = "Phew. Close call there, but the risk is gonna pay out big.\n\nDid you see the sweet tech King Mechagon was wearing? We gotta get our hands on that!" }
WordHunterWoW_QuestEN[55633] = { title = "The Sunken Chest", description = "<This waterlogged chest appears to be in salvageable condition, but it is too heavy to move due to the contents within.\n\nThe lock on the device appears to be operational.\n\nPerhaps there is a key nearby...>", objectives = "Locate the Brass Key at the bottom of the lagoon.", progress = "<The chest is locked and requires a key.>", completion = "<It takes some effort, but the lock eventually opens...>" }
WordHunterWoW_QuestEN[55635] = { title = "A Voice on the Wind", description = "<A distant, mysterious voice fills your mind.>\n\nMy enchantments are not lost...\n\nFind me...\n\nDrustvar...\n\nFallhaven...", objectives = "Seek out the source of the mysterious voice in Drustvar.", completion = "Be at ease, friend. I don't want to hurt you. Instead, I have a proposition for you.\n\nYou see, I was a druid once and the only thing I loved more than tending to the forests and creatures within them was enchanting. \n\nThen I was murdered and cursed to wander this peninsula, unable to cross river nor mountain so long as my body still exists. \n\nIf you destroy my old body and help me make a new one, I will teach you how I made the rod you disenchanted." }
WordHunterWoW_QuestEN[55636] = { title = "A Life's Work", description = "<A voice whispers to you from beyond the veil of death.>\n\nI spent more than one-thousand years researching the mysteries of the arcane before the Great Sundering tore our world apart.\n\nI perished amidst the destruction and my work was lost.\n\nSearch the area for my ancient writings and put my spirit to rest...", objectives = "Collect 6 Ancient Scrolls and 6 Arcane Tomes.", progress = "The bookcase appears empty...", completion = "With the arcane tomes and ancient scrolls restored to the bookcase, it feels as though a long held weight has been lifted from your shoulders." }
WordHunterWoW_QuestEN[55637] = { title = "Poor, Unfortunate Souls", description = "Countless lives were lost in the Great Sundering when this great city was plunged into the depths of the abyss.\n\nThe fortunate among us died quickly in the explosion, but some survived only to cling onto dear life as the cold, unforgiving ocean waves crashed down upon them.\n\nThose poor, unfortunate souls suffer a fate worse than death to this day. They drown endlessly, forced to relive the torture of their death.\n\nPut them to rest so that they may have peace at last.", objectives = "Put 8 Tortured Souls to rest.", progress = "I hear them as we speak... crying out for help. Yet, I am powerless to save them...", completion = "They will never gain back the lives they lost that day so long ago, but at least they will suffer no longer." }
WordHunterWoW_QuestEN[55638] = { title = "Making Kelpberry Wine", description = "<This is an empty kelpberry juice cask.\n\nThere is someone nearby that may appreciate a refill.>", objectives = "Deliver Kelpberry Wine to Maedin in Maedin's Challenge.", progress = "Did you bring me something?", completion = "Oh, you know exactly what this ol' girl likes!" }
WordHunterWoW_QuestEN[55639] = { title = "Who Lurks in the Pit", description = "The winds whisper of people being trapped in the pit. It seems there may be more members of the expedition within.\n\nI fear it will be up to you to make the descent and save the survivors.\n\nThere should be six in total...  though the winds say that one is farther away from the others...\n\nWith our luck, the last survivor is at the bottom of the pit.\n\nGood luck, {name}. And... make sure no spiders follow you back out.", objectives = "Rescue 5 Trapped Expedition Members.", completion = "Ralia Dreamchaser is a druid of the Cenarion Circle, an order dedicated to protecting the wilds of Azeroth.\n\nThank you for rescuing her. Her aid is sure to be of use against the ogres." }
WordHunterWoW_QuestEN[55640] = { title = "Vision of Stormwind", description = "Weaken N'Zoth by delving into his mind.You will receive:", objectives = "Complete the Vision of Stormwind." }
WordHunterWoW_QuestEN[55645] = { title = "Princely Visit", description = "This is it! The fabled Mechagon!\n\nThe greatest discovery of our age, and you're here to witness me accomplish it!\n\n<Tinkmaster Overspark puffs out his chest, brushes off his robes, and smiles confidently.>\n\nI am ready to address the Mechagon people. You may accompany me.", objectives = "Explore the nearby town with Tinkmaster Overspark.", progress = "Mechagon is not like the legends you were told.", completion = "Welcome to the Rustbolt Resistance." }
WordHunterWoW_QuestEN[55646] = { title = "The Legend of Mechagon", description = "Heya, {name}. I was just tellin' Skaggit that I was hoping I'd run into you up here!\n\nI caught wind of an Alliance operation into some old vault that opened in Tiragarde Sound.\n\nIn typical gnomish fashion, Tinkmaster Overspark is overreacting like crazy, claiming it's some lost connection to the gnome fairytale land of Mechagon.\n\n<Gazlowe scoffs.>\n\nI don't buy that for a second, but I am very interested in getting my hands on whatever tech's in that vault. You in?", objectives = "Meet Gazlowe at the Abandoned Junkheap in Tiragarde Sound.", completion = "Keep your head down! The Alliance beat us here!" }
WordHunterWoW_QuestEN[55647] = { title = "A Quick Ear Hustle", description = "Bad news. We're late.\n\nThe Alliance was already crawling all over the vault when we got here.\n\nLucky for us, some big commotion inside sent some of 'em running for the hills.\n\nMost of 'em are still down in that vault, though, including that crazy braggart Tinkmaster Overspark.\n\nLet's give 'em a few more minutes to clear out, so we don't have to go in guns blazing.", objectives = "Wait for the Alliance to leave the vault.", progress = "What'd they find down there?", completion = "Told you that Overspark was a chump.\n\nA boss has gotta respect his crew, or they won't respect him." }
WordHunterWoW_QuestEN[55648] = { title = "This is Our Vault Now", description = "Looks like the coast is clear with Overspark gone. Let's get inside that vault and see what's really going on here.\n\nMechagon or not, there'd better be some quality hardware in there to make this trip worth our time.", objectives = "Lead Gazlowe's crew into the vault.", completion = "Easy peasy. Now we just gotta get all this fancy gnomish machinery workin' again!" }
WordHunterWoW_QuestEN[55649] = { title = "Machinations for Mechagon", description = "So Mechagon ain't just a fairy tale? Gotta admit I'm surprised.\n\nBut, if the tech on that king is any indication of what they've got out there for us to swipe, I am very, very happy to be wrong!\n\nWe can't rush into this. A good crew died today. That ain't happening again on my watch.\n\nMeet me and Skaggit back in Zuldazar Harbor, and we'll build this expedition up right.", objectives = "Ride the Greasemonkey Skysneaker to Zuldazar Harbor.", completion = "Feels good to be back on Horde turf." }
WordHunterWoW_QuestEN[55650] = { title = "Only the Best Will Do", description = "You heard Gazlowe. The boss wants this expedition to go smoothly. No cutting corners, no slush.\n\nI know you've worked with Gallywix in the past. We don't run our operations like that.\n\nWe expect the best from our crews, so we pay 'em what they're worth and treat 'em well. In return, we got the best goblin crews on the planet, and they ain't goin' over to any competition.\n\nHere's a list of who and what we're gonna need to pull this off. Don't worry, Gazlowe'll cover all the costs.", objectives = "Get everything needed to launch the expedition for Mechagon.", progress = "Look, <name>, I ain't got time to hold your hand through all this. Figure it out or I'll find someone else who will.", completion = "This might be the best crew Gazlowe and I have ever assembled!" }
WordHunterWoW_QuestEN[55651] = { title = "To Mechagon!", description = "Whatever's waiting for us on the shores of Mechagon, we're going to be ready for it with this crew.\n\nI don't hold any misconceptions about how that crazy king is going to welcome us. Guns blazin', I'm sure.\n\nSo we're going in quietly on this submarine. Low profile'll keep us all safe.\n\nWhen you're ready to go, talk to Captain Krooz.", objectives = "Talk with Captain Krooz to travel to Mechagon.", completion = "Don't let the grass fool ya. Look at those bots on the shoreline. That city up ahead. That constant buzz of machinery and smog in the air.\n\nThis place is a technological gold mine." }
WordHunterWoW_QuestEN[55652] = { title = "Prospectus Bay", description = "Looks like we made it in unnoticed.\n\nSkaggit's crew can set up shop on that beach, but we gotta make sure it's safe for 'em to land first.\n\nLet's do a quick flyover to scout out how we're going to crack this place wide open.\n\nThat town up on the hill looks promising...", objectives = "Jetpack into Prospectus Bay with Gazlowe and the crew.", completion = "We'll own this whole island in no time." }
WordHunterWoW_QuestEN[55655] = { title = "Tracking Quest", description = "", objectives = "" }
WordHunterWoW_QuestEN[55657] = { title = "In the Shadow of Crimson Wings", description = "It is unlike Alexstrasza to remain out of contact for so long, particularly when the very essences of the dragonflights' power are being made manifest. \n\nWhile our allies here tend to the injured, we must seek out the Life-Binder at once.\n\nWhen you are ready, we shall ride to the Vermillion Redoubt together.", objectives = "Speak with Kalecgos to fly to the Vermillion Redoubt, locate Alexstrasza and discover the source of the threat.", progress = "We must rely on your aid once more, champion.", completion = "We owe you a great deal of gratitude. You have the support of the red dragonflight in your efforts to save Azeroth." }
WordHunterWoW_QuestEN[55658] = { title = "Clues Abound", description = "Before King Mechagon claimed this island, someone else lived here.  Buried beneath this filth and garbage is the history of a forgotten people. With your help, we shall learn about these previous inhabitants.\n\nSir Finley has marked a location where he's seen unusual artifacts. Meet him there and see if you can discover any clues.", objectives = "Discover a clue about the island's history.", progress = "Get to it, history is waiting for you!", completion = "Good show! We'll get to the bottom of this mystery in no time!" }
WordHunterWoW_QuestEN[55659] = { title = "Relics of the Sundering", description = "It's not every day that you encounter the remnants of a lost civilization beneath the ocean!\n\nI never would have imagined that I'd have the opportunity to explore the lost city of Nazjatar... and on solid ground at that!\n\nThere are many secrets here to uncover. If you come across any ancient highborne artifacts, please bring them to me. These relics could provide us with valuable clues regarding the mysteries of the Great Sundering.\n\nI feel as though we are barely scratching the surface so far...", objectives = "Collect 10 Highborne Relics.", progress = "Whatever mysteries were hidden here beneath the ocean are now waiting to be revealed!", completion = "Excellent work! Look at all of these highborne relics you've found! I will begin examining them at once." }
WordHunterWoW_QuestEN[55660] = { title = "Time Trials", description = "", objectives = "Good luck!" }
WordHunterWoW_QuestEN[55661] = { title = "Fighting Venomous With Venom", description = "There are many uses for the poison of the snapdragons.\n\nImmediate use would be to create antivenin for healing, or harvesting poison for attacking the naga.\n\nLet's get to the root of the issue, literally.\n\nUse some collected venom against a Terrormaw to weaken it. Kill one and bring me their fangs.\n\nI think we can come up with something handy from there.", objectives = "Use collected venom to weaken and kill a Snapdragon Terrormaw for their fangs.", progress = "Did you get the fangs?", completion = "Need to be careful not to scratch myself with these.\n\nWith a little learning, we should be able to create an antidote... and maybe a weapon of our own!" }
WordHunterWoW_QuestEN[55662] = { title = "Arcane Cache", description = "<The heavily reinforced chest is of naga construction and appears to be reinforced with a magical lock of some kind.\n\nMagical reinforcement aside, the cache still requires a key to unlock.\n\nThe key is most likely being held by one of the nearby naga soldiers.>", objectives = "Locate the key to the Arcane Cache.", progress = "<The chest is locked and requires a key.>", completion = "<The magical barrier dissipates as you insert the key.>" }
WordHunterWoW_QuestEN[55663] = { title = "Broken Controller", description = "It is too late for me, my friends.\n\nThe Controllers work us and work us and we have no rest.\n\nWe have lost so many. \n\nPlease, free the others! Don't let them share my fate!", objectives = "Free the slaves and destroy the Merciless Controller.", completion = "Every kelfin we set free, makes the naga a little weaker.\n\nI heal who I can." }
WordHunterWoW_QuestEN[55664] = { title = "A Blow to Morale", description = "This place is the source of all of our corruption. \n\nThe kelfin are taken and broken here. \n\nHit them where it hurts. Break their power, kill every naga you see, wreak havoc!\n\nEvery little crack we make, weakens their foundation.", objectives = "Disrupt all activities in the Shirakess Repository.", progress = "Did you damage their morale?", completion = "It's going to take them a while to clean that up, <name>!\n\nI love watching them scurry." }
WordHunterWoW_QuestEN[55665] = { title = "The Dark Garden", description = "Look, {name}, I know we have bigger battles ahead, but these gardens are horrific.\n\nInnocent creatures captured and imprisoned for the naga's amusement. \n\nThey bring them out, torture them, change them, break them... you get the idea.\n\nHelp me free those the naga have taken, and punish them for their hubris!", objectives = "Kill naga and release the poor tortured creatures held in the Imperial Garden.", progress = "Were you able to wreak some havoc in there?", completion = "I'm pretty sure I heard an otter giggle as it ran past. \n\nYour fighting skills were most rad." }
WordHunterWoW_QuestEN[55667] = { title = "Short-Supply Reward", description = "", objectives = "" }
WordHunterWoW_QuestEN[55668] = { title = "Short-Supply Reward", description = "", objectives = "" }
WordHunterWoW_QuestEN[55669] = { title = "Encrypted Radio Receiver TBD", description = "NYI - Will add Black Market viewing NPC in town", objectives = "NYI - Will add Black Market viewing NPC in townYou will receive:\n\nUpon completion of this quest you will gain:" }
WordHunterWoW_QuestEN[55670] = { title = "Amathet Raiding Fleet", description = "", objectives = "" }
WordHunterWoW_QuestEN[55672] = { title = "A Historical Mess", description = "The text on this parchment appears to be Tortollan. Is it possible that Tortollans once resided on this island?  \n\nWe need to act quickly, before the creatures in this area destroy anymore evidence. Search the area for any signs of Tortollan relics.", objectives = "12 Tortollan Relics collected.", progress = "Get to it, history is waiting for you!", completion = "Jolly good show. We'll be to the bottom of this mystery in no time!" }
WordHunterWoW_QuestEN[55681] = { title = "Crab Marks The Spot", description = "<This appears to be the remains of some kind of treasure map. However, the map is in poor condition after so many years of being subjected to the ocean.\n\nAccording to the map, the treasure should be somewhere nearby; but it's impossible to tell what exact location is from the ruined map.>", objectives = "Locate the buried treasure." }
WordHunterWoW_QuestEN[55683] = { title = "Forgotten Memories", description = "Have we met before? I'm sorry... but I don't remember your name.\n\nMy name is... Arylina... I think. My memory has been so foggy since the great explosion happened that sent us underwater.\n\nOh! But look! I can see the sun and the stars again... I wonder what happened?\n\nI used to keep a diary, but I can't find it anywhere. If I just had my diary back, I'm sure I could remember more.\n\nWill you help me find it?", objectives = "Locate Arylina's diary.", progress = "Where did I put that diary?", completion = "Oh... I remember now. This all happened so long ago. I think it's time for me to rest..." }
WordHunterWoW_QuestEN[55685] = { title = "We Come in Peace... and Profit", description = "King Mechagon won't be happy we're on his island.\n\nBut a cruel king like that is gonna have enemies. You and I know that better than most, yeah?\n\nWhile Skaggit and the crew get our foothold dug in here, you and I are gonna find some potential allies to shield us from King Mechagon's wrath.\n\nThose two guards ran into that junkheap town up the hill. That place don't smell of royalty to me... Let's check there first.", objectives = "Explore the nearby town with Gazlowe.", progress = "Mechagon is not like the legends you were told.", completion = "Welcome to the Rustbolt Resistance." }
WordHunterWoW_QuestEN[55686] = { title = "Upgrade Your Jetpack (Optional)", description = "", objectives = "" }
WordHunterWoW_QuestEN[55687] = { title = "Expedition GG-118 Micro-Jetpack", description = "", objectives = "" }
WordHunterWoW_QuestEN[55688] = { title = "A Growing Mystery", description = "This runestone could be of Vrykul origins. Is it possible that Vrykul once visited this island? \n\nWhere there's one runestone, there's usually more. The roots of lashers are drawn to the magic of runestones. If there are more buried here, the Lasher roots maybe wrapped around them!\n\nClear these lashers and see if any have runestones tangled in their roots.", objectives = "10 Ancient Runestones collected.", progress = "Get to it, history is waiting for you!", completion = "Very good, We will examine these and see where it leads us." }
WordHunterWoW_QuestEN[55693] = { title = "UNusued", description = "Get to it, history is waiting for you!", objectives = "" }
WordHunterWoW_QuestEN[55694] = { title = "There's Something in the Water", description = "The Ankoan must contend with threats from not only the naga, but also the horrors of N'Zoth. We learned early that if we allow his infection even the smallest purchase, he will grow and corrupt everything.\n\nThere is a great evil who is lingering near the waterway that flows through this place. It must be dealt with.", objectives = "Kill the Eye of the Corruptor.", completion = "Another will take it's place, eventually. Like clearing weeds from a garden, it's a constant battle against invasion." }
WordHunterWoW_QuestEN[55695] = { title = "That New Mount Smell", description = "Once every week, Mechagon expels a lot of excess oils through the outflow. That's why the place is a toxic mess!\n\nToday they expelled a batch of Golden Cogpaste. The stuff is amazing! I make air fresheners out of it. Makes any mount smell like it's brand new!\n\nCheck all the pipes in the outflow, and see if you can collect some of this paste.", objectives = "Collect 8 Golden Cogpaste.", progress = "I still could use that cogpaste.", completion = "I was running low on Air Fresheners, this will let me whip up a new batch right away!" }
WordHunterWoW_QuestEN[55696] = { title = "Test Drive", description = "There's still a lot of work to do, but it's running! We need to give the engine, brakes and gyro-balance actuator a good test. \n\nYou want to take it out for a drive and see how well they work?", objectives = "Drive it to the check point, reach Maximum speed, and test the emergency brake.", progress = "Take it for a drive!", completion = "I was afraid you may not make it back!" }
WordHunterWoW_QuestEN[55697] = { title = "A Little Leg Work", description = "The legs and shocks on this mount are shot! We'll need some new ones if we're going to get this mount crawling.\n \nA few weeks ago, Bondo and his gang rode into the Scrapbone Den hoping to scare the Troggs off. The Troggs tore their crawlers apart! The parts for those crawlers are still laying all around Scrapbone Den.\n\nSee if you can get us some of those parts from the Troggs.", objectives = "Collect 4 Mechaspider Leg and 12 Toe Springs.", progress = "We need those legs.", completion = "These parts will get us closer to being able to ride this thing!" }
WordHunterWoW_QuestEN[55701] = { title = "Snapdragon Claws", description = "Snapdragons are savage creatures that hunt in packs. Their presence in Nazjatar requires us to stay vigilant at all times.\n\nThey are crafty beasts, preferring to ambush their prey when it is weak or wounded. We will need to reduce the number of snapdragons in the area.\n\nThe last thing we need after a battle with the naga is to be finished off by a pack of blood-thirsty snapdragons!\n\nHunt down any nearby snapdragons and bring me a claw from each kill so that I may keep track of their numbers.", objectives = "Collect 10 Snapdragon Claws.", progress = "The snapdragon threat cannot be underestimated.", completion = "Good work, <name>. The fewer snapdragons in Nazjatar, the better." }
WordHunterWoW_QuestEN[55707] = { title = "First One's Free", description = "The pocket-sized computational device can accept punch cards to upgrade and modify its performance.\n\nI could give you a punch card, but a particularly crafty trogg, Moch'k Eight-Thumbs, stole my satchel full of cards. \n\nKill Moch'k Eight-Thumbs, recover my satchel, and I'll set you up with a punch card for free.", objectives = "Punchcard Satchel recovered.", progress = "Get that satchel back!", completion = "You are rather amazing for someone with so little mechanization!" }
WordHunterWoW_QuestEN[55708] = { title = "Upgraded", description = "Well, look at you, {race}...\n\n<Christy's mechanical eyes quickly scan your body.>\n\nNot as impressive as I had hoped.\n\nKing Mechagon's armies are fully mechanized. But, you... you have a severe excess of flesh and matching machinery deficiency.\n\nYes, we simply must make a few changes... Maybe a neural-cranial upgrade!\n\nBring me a few microcogs from the motospiders nearby and I'll fix you up!", objectives = "Collect 20 Microcogs.", progress = "You must be able to out-think King Mechagon in battle. Get me those parts.", completion = "Your first upgrade! Try it out some before we attach it permanently." }
WordHunterWoW_QuestEN[55712] = { title = "Upgrade Your A.T.O.M.I.K. Mk. II (Optional)", description = "", objectives = "" }
WordHunterWoW_QuestEN[55713] = { title = "Expedition A.T.O.M.I.K. Mk. II", description = "", objectives = "" }
WordHunterWoW_QuestEN[55714] = { title = "Void Cache", description = "<The heavily reinforced chest is of naga construction and appears to be reinforced with a magical lock of some kind.\n\nMagical reinforcement aside, the cache still requires a key to unlock.\n\nThe key is most likely being held by one of the nearby naga soldiers.>", objectives = "Locate the key to the Void Cache.", progress = "<The chest is locked and requires a key.>", completion = "<The magical barrier dissipates as you insert the key.>" }
WordHunterWoW_QuestEN[55715] = { title = "Feed Them All", description = "When we're doing our job right, we always have more mouths to feed!\n\nIf you could help with my stock, we could care for even more.\n\nBig, strong friends are what this revolution needs!", objectives = "Collect 10 Fathom Flesh.", progress = "Do we have enough protein?", completion = "What a great help you are! I may grow to like you land creatures." }
WordHunterWoW_QuestEN[55717] = { title = "Time for Heroics", description = "That card you found was a gold rare Huolon! \n\nI think that card belonged to Adalin Halfheight, one of our junior explorer league members.  If he dropped it, he and our other junior members maybe in trouble!\n\nWe need to find Leona Mistcaller, Dunkin Crackjaw, and Adalin Halfheight immediately!", objectives = "Leona Mistcaller, Dunkin Crackjaw, and Adalin Halfheight rescued.", progress = "Let's find these people!", completion = "You certainly are the hero they all talk about!" }
WordHunterWoW_QuestEN[55718] = { title = "Strange Discovery", description = "<A very old ring of Nightelf origin. Seems out of place on this island, perhaps Elise Starseeker will know what to make of it>", objectives = "Deliver the ring to Elise Starseeker.\n\nProvided item:", completion = "This creates more questions than answers about this islands past.\n\nI'll look into this further when I return to Ironforge." }
WordHunterWoW_QuestEN[55719] = { title = "Requisition: A Few Starfish", description = "Our forward scouts have been using starfish scales as camouflage. The trouble is that the scales deteriorate too quickly. We are going to need more scales if we want to keep tabs on naga movements.\n\nIf you happen upon any Angel Scale Starfish, please deliver them to the quartermaster as soon as possible.", objectives = "Collect 3 Angel Scale Starfish.", completion = "Thank you for your contribution." }
WordHunterWoW_QuestEN[55720] = { title = "Requisition: A Few Seaweed", description = "We have so many wounded and we are dangerously low on seaweed bandages. If you find Sticky Seaweed, please give it to the quartermaster.", objectives = "Collect 3 Sticky Seaweed.", completion = "Thank you for your contribution." }
WordHunterWoW_QuestEN[55721] = { title = "Requisition: A Few Kelp Buds", description = "We need rations for our forces. While kelp buds do not have the same delicious taste as other options, it is nutritious and plentiful near any kelp forests. This makes it our first choice for making rations.\n\nIf you happen to find any around Nazjatar, please leave your stores with the quartermaster. The ones freshly fallen from kelp are best.", objectives = "Collect 3 Fallen Kelp Buds.", completion = "Thank you for your contribution." }
WordHunterWoW_QuestEN[55722] = { title = "Requisition: A Few Pearls", description = "<This letter bears the seal of the quartermaster.>\n\nSupplies needed!\n\nWe are dangerously low on pearls. Anyone carrying Luminous Pearls, please leave your stores with the quartermaster.", objectives = "" }
WordHunterWoW_QuestEN[55723] = { title = "Requisition: A Few Carp", description = "Our local sea life is in danger! If you spot a fish out of water, please return it to the nearest lake, stream, or river. Conservation is everyone's responsibility!", objectives = "Return 3 Struggling Carps to water.", completion = "Thank you for your contribution." }
WordHunterWoW_QuestEN[55724] = { title = "Requisition: A Few Deepcoral Buds", description = "Many species feed on the deepcoral buds from the tall columns that grow in the east. Fathom rays feed on these buds especially. We use the buds as lures for fathom rays to use as mounts. But with our stores so low, we will not be able to provide the air support we need across Nazjatar.\n\nIf you could gather more Deepcoral Buds and return them to the quartermaster, you will surely be rewarded.", objectives = "Collect 3 Deepcoral Buds.", completion = "Thank you for your contribution." }
WordHunterWoW_QuestEN[55725] = { title = "Requisition: A Few Spiral Leaf", description = "We are dangerously low on our medicine stores. If you find any Spiral Leaf, please leave your stores with the quartermaster.\n\nI should warn you, Spiral Leaf is immensely poisonous. Make sure to handle it with care. Some symptoms of spiral leaf poisoning include bouts of rage, immense bursts of strength, and murderous impulses. If you are exposed, find some naga and use your murderous energy for good.", objectives = "Collect 3 Poisonous Spiral Leaf.", completion = "Thank you for your contribution." }
WordHunterWoW_QuestEN[55726] = { title = "Requisition: A Few Cone Shells", description = "If we are going to arm ourselves against the naga, we will need far more supplies and armaments. Cone Shells make most of our armor and weapons. It's light, it's strong, and it's plentiful in this region. However, our supplies are running short and our forces need support.\n\nIf you find yourself carrying Impregnable Cone Shells, please leave your stores with the quartermaster.", objectives = "Collect 3 Impregnable Cone Shell.", completion = "Thank you for your contribution." }
WordHunterWoW_QuestEN[55727] = { title = "Requisition: A Few Flotsam", description = "I have seen piles of flotsam in the sands to the west. If you could go out and scrounge anything useful from the debris, it could prove useful. Beware, that area is a hydra breeding ground and they have been growing more aggressive since the water receded.\n\nOnce you've gathered some supplies, return to the quartermaster for your reward.", objectives = "Collect 3 Piles of Flotsam.", completion = "Thank you for your contribution." }
WordHunterWoW_QuestEN[55728] = { title = "Reinforced Cache", description = "<The heavily reinforced chest is of naga construction and appears to be reinforced with a heavy-duty lock of some kind.\n\nReinforcement aside, the cache still requires a key to unlock.\n\nThe key is most likely being held by one of the nearby naga soldiers.>", objectives = "Locate the key to the Reinforced Cache.", progress = "<The chest is locked and requires a key.>", completion = "<As you turn the key you can hear the heavy latches of the chest snap open with considerable force.>" }
WordHunterWoW_QuestEN[55729] = { title = "The Resistance Needs YOU!", description = "Rustbolt isn't usually in this level of malfunction.\n\nKing Mechagon attacked our town last night. His mechanical armies captured many members of the Rustbolt Resistance and destroyed as much as they could before we drove them out.\n\nThe prisoners are being processed at Junkwatt Depot. After that, they'll be transferred down into King Mechagon's underground city... for full mechanization.\n\nWe can't let that happen. Will you help me rescue them?", objectives = "Ride with Prince Erazmin to Junkwatt Depot.", completion = "This is where they process all prisoners before sending them into King Mechagon's city for reprogramming." }
WordHunterWoW_QuestEN[55730] = { title = "Rescuing the Resistance", description = "King Mechagon is ruthlessly efficient. He only expends resources to kidnap those he deems worthy.\n\nThe rest, he... discards.\n\n<Prince Erazmin grimaces.>\n\nWe will deal with my father, King Mechagon, another day.\n\nThis information is more immediately relevant in that my father's predictability means our top scientists, engineers, and tinkerers should all be trapped, alive, somewhere in this depot.\n\nWe will find them, and break them out.", objectives = "Rescue the Rustbolt Resistance members.", progress = "My father is short-sighted. He judges the worthiness of an individual in its current state. He fails to truly see their potential.", completion = "My father is short-sighted. He judges the worthiness of an individual in its current state. He fails to truly see their potential." }
WordHunterWoW_QuestEN[55731] = { title = "My Father's Armies", description = "My father was once a good leader. He envisioned a brighter future for his people, and did everything in his power to help us acquire it.\n\nBut when his vision became misaligned with the dreams of his people, he failed to adapt. Instead, he grew rigid, forcing his will on others.\n\nIn secret experiments, he began fully mechanizing the bodies of those who resisted him.\n\nIt was horrible to watch... there was nothing left of the original gnomes who followed him willingly.\n\nOnly robots remained. Slaves.", objectives = "Kill 12 Mechagon forces in Junkwatt Depot.", progress = "If we don't stop my father here, we will all share these poor gnomes' fates.", completion = "If we don't stop my father, we will all share these poor gnomes' fates." }
WordHunterWoW_QuestEN[55732] = { title = "An Old Scar", description = "We've got a new problem, champion. Another grievous wound has opened up, this time at the Maelstrom!\n\nThe shaman there are in deep trouble, an' they need our help!\n\nSpeak tae MOTHER. She'll get ye tae the Maelstrom. I'll meet ye there.", objectives = "Speak to MOTHER to travel to the Maelstrom.", completion = "I expected things tae be bad, but it's even worse than I thought!" }
WordHunterWoW_QuestEN[55734] = { title = "Drill Rig Construction", description = "<Prince Erazmin sifts through the resources you both collected.>\n\nYes... This appears to be sufficient material to repair that drill rig.\n\nI'll do what I can with the parts that I have, but you will need to complete the repairs with yours.\n\nWhen you're ready, return to that broken drill rig we found and open it up.\n\nTogether, we'll have it up and running in no time.", objectives = "Contribute Spare Parts and Energy Cells to the Broken Drill Rig construction project.", progress = "You didn't lose your parts did you?", completion = "Keep an eye out for other construction projects across the island.\n\nThere's always something to build in Mechagon." }
WordHunterWoW_QuestEN[55735] = { title = "Defending the Maelstrom", description = "The shaman of the Earthen Ring are powerful, but this is more than even they can handle! And from the sound o' it, some o' their own are still trapped down below.\n\nLike ye did in Nordrassil, use yer Heart of Azeroth tae seal up the wounds inflicted here. An' lay any crazed elementals tae rest before they make even more o' a mess.", objectives = "Defeat Azerite elementals and seal Azeroth's injuries at the Maelstrom.", progress = "This just keeps gettin' worse. If too many of these wounds open up, we may not be able tae heal the damage.", completion = "That was close! If ye hadn't stopped the spread of these wounds in time, I don't know what might've happened!" }
WordHunterWoW_QuestEN[55736] = { title = "Welcome to the Resistance", description = "Life in the Rustbolt Resistance is not easy, {name}.\n\nBut it is yours. We will not order you around or force you to fight. Mechagon is a land of endless opportunities, and you may chase whichever opportunities you see fit.\n\nOf course, if you'd like suggestions for which improvements you most require, myself or any of the other mechagnomes in town will be happy to advise you of your current weaknesses.\n\nBut, for now, I ask simply that you walk with me to my workshop.", objectives = "Tour Rustbolt with Prince Erazmin.", completion = "I wonder, what will you choose to do next?" }
WordHunterWoW_QuestEN[55737] = { title = "At the Azerite Time", description = "Ye did it! Ye stopped the damage before it could get any worse!\n\nThe Maelstrom will always be a place o' great history an' pain fer Azeroth, but any little bit we do will make things better. Who knows, maybe we can even heal Silithus one day!\n\nI'll meet ye back in the Chamber o' Heart. MOTHER's sure tae be interested in what happened here.", objectives = "Return to the Chamber of Heart.", completion = "Heart examination complete. Additional Azerite amplification activated." }
WordHunterWoW_QuestEN[55738] = { title = "TBD NOT USED", description = "TBD", objectives = "TBD" }
WordHunterWoW_QuestEN[55739] = { title = "Back to the Chamber", description = "The Heart o' Azeroth is gettin' stronger every day, and it's makin' a difference.\n\nMake yer way tae the Chamber o' Heart, champion. Yer talents are needed.", objectives = "Return to the Chamber of Heart.", completion = "The Heart o' Azeroth never ceases tae amaze me. Well done, champion!" }
WordHunterWoW_QuestEN[55740] = { title = "TBD NOT USED", description = "TBD", objectives = "TBD" }
WordHunterWoW_QuestEN[55742] = { title = "Bundle of Corroded Parts", description = "", objectives = "" }
WordHunterWoW_QuestEN[55743] = { title = "More Recycling", description = "<Recycling is fun and profitable. The Recyclerizer DX-82 stands ready to receive more scrap metal.>", objectives = "Collect 1 Bundle of Recyclable Parts", progress = "<WARNING 3.6.4 - Y: Keep all appendages clear of doors or risk irreversible limb recyclerization.>", completion = "You deposit the bundle of parts into the Recyclerizer DX-82.  The doors close and the machine surges to life, a slight buzzing sound begins emanating from within. The sound increases in frequency, the slight buzz giving way to a high-pitched whirring. The machine shakes violently, seemingly ready to explode..." }
WordHunterWoW_QuestEN[55750] = { title = "WANTED: Lady Naz'jess", description = "Wanted for attacks against the Alliance!\n\nLady Naz'jess is responsible for leading several raids and ambushes against our soldiers. Extreme caution advised!\n\nUpon completion of the mission, report to Lieutenant Hawkins for commendation.", objectives = "Retrieve the head of Lady Naz'jess.", progress = "Have anything to report?", completion = "Well done, <class>. Lady Naz'jess was a formidable foe and a high-ranking commander among the naga." }
WordHunterWoW_QuestEN[55751] = { title = "The Heart of the Water", description = "You see a lot up here. \n\nEven the water is a slave to the will of the naga.\n\nI believe we can help them reform away from here.\n\nBring back what you can!", objectives = "Collect 15 Living Droplets from water elementals in Azsh'ari Terrace.", progress = "Did you free them?", completion = "Well done, <race>!\n\nWe will hope for the best!" }
WordHunterWoW_QuestEN[55752] = { title = "We Stand United", description = "The work ye've done tae empower the Heart o' Azeroth cannae be understated! With this power, we might just stand a chance o' savin' the world.\n\nIt's been a long fight fer certain, an' there is still more tae do. But fer now, we've got a little gift fer ye!\n\nLet me know when yer ready, champion.", objectives = "Speak to Magni.", progress = "Ain' it incredible, champion? There's no tellin' how powerful the Heart may yet become!", completion = "Amazin' isn't it? Tae see the dragonflights united in support o' Azeroth. Some o' them may be battered an' bruised, but they're still fightin'.\n\nBear their gifts well, Champion of Azeroth." }
WordHunterWoW_QuestEN[55753] = { title = "Knock His Bot Off", description = "I need to rebuild the main powercore. It's a 500S Mekronic so I'll need the operational schematics to get the work done. Only person I know who has a copy of that is Bondo Bigblock.\n\nWe're going to need Bondo's help to finish this. Maybe if you ask him, he'll lend us his schematics.", objectives = "Acquire the powercore schematics from Bondo Bigblock.", progress = "Did you make a deal with Bondo?", completion = "Great work <name>. All that's left is to rebuild this power core." }
WordHunterWoW_QuestEN[55763] = { title = "The Rescue of Meredy Huntswell", description = "Our expedition's mage, Meredy Huntswell, is being held by the harpies!\n\nWe've got to stop their ritual and rescue Meredy.\n\nYou lead the charge. Kee-La and I will back you up if things look dire.", objectives = "Rescue Meredy Huntswell from the harpy's necromantic ritual.", completion = "Ye rescued me from a grim fate! Bein' a practicin' mage, I always figured one of me own spells would do me in, not a harpy!" }
WordHunterWoW_QuestEN[55764] = { title = "Harpy Culling", description = "The harpies are preparing for a dreadful assault, {name}. \n\nThey plan to attack our allies back at camp! \n\nHarpies swoop in and snatch their victims before bringing them back to their nests... to feast.\n\nWe have to stop them. Slay the harpies and their worgs to ensure their forces are too weak to stage an assault.", objectives = "Defeat 10 harpies and their allies.", progress = "We must do what we can to fight the harpy menace. Take them down, as well as their worgs.", completion = "That should keep our camp safe for now. We must hurry and stop whatever these ogres have planned." }
WordHunterWoW_QuestEN[55765] = { title = "Bugs, Lots of 'Em!", description = "You got a problem with mechanical bugs, so the Roughriders are here to sort this mess out!\n\nIn my experience, this big of an outbreak must have some sort of queen bug behind it all. We gonna go in, kill a lot of bugs till we find the leader of 'em all.\n\nHorde or Alliance don't matter, you're with the Roughriders today. Let's kill some bugs!", objectives = "Exterminate 20 motospiders.", progress = "Do your job!", completion = "You took the battle to them. You are a Roughrider!" }
WordHunterWoW_QuestEN[55766] = { title = "She Sells These Shells", description = "Suva is so proud of her seashells. \n\nAfter everything she has done for our people, helping her supplies is the least we can do!\n\nHead down the hill and pick up some of the shiniest seashells you can find!\n\nYou will make her day.", objectives = "Collect 8 seashells.", progress = "<Excited clicks and squeaks.>", completion = "<Suva's feelers are twitching joyfully.>" }
WordHunterWoW_QuestEN[55767] = { title = "Misdirection", description = "We came in friendship and those pesky murlocs jumped us and stole my treasure.\n\nThey threw it in one of those big clams and ran off into the village.\n\nThey keep moving them around and I have no idea where it is now!\n\nCan you please help?", objectives = "Find Dani's Treasure.", progress = "Any luck?", completion = "That's it! Dexter was so sad!\n\nThey thought they were so clever.\n\nNext time they're getting a kick to the dorsal fin." }
WordHunterWoW_QuestEN[55768] = { title = "Emergent Sea Weeds", description = "There is a special kind of kelp that only grows near the vents.\n\nOur healers use these to help treat our friends in Newhome.\n\nMy kind don't have much of a chance down there, but you do!\n\nGather up some of the vent kelp sprouts in the Dragon's Teeth Basin and bring them to Nevin.", objectives = "Gather 10 vent kelp sprouts.", progress = "Were you able to find the special vent kelp?", completion = "These are perfect! \n\nA little kelp goes a long way!" }
WordHunterWoW_QuestEN[55770] = { title = "WANTED: Commander Sarj'eth", description = "Wanted for attacks against the Alliance!\n\nCommander Sarj'eth is responsible for leading several raids and ambushes against our soldiers.\n\nLast seen near the vicinity of this command poster.\n\nExtreme caution advised!\n\nUpon completion of the mission, report to Lieutenant Hawkins for commendation.", objectives = "Retrieve the head of Commander Sarj'eth.", progress = "Have anything to report?", completion = "Well done, <class>. Sarj'eth was a formidable foe and a high-ranking commander among the naga." }
WordHunterWoW_QuestEN[55771] = { title = "WANTED: Lord Ha'kass", description = "Wanted for attacks against the Alliance!\n\nLord Ha'kass is responsible for leading several raids and ambushes against our soldiers.\n\nLast seen near the vicinity of this command poster.\n\nExtreme caution advised!\n\nUpon completion of the mission, report to Lieutenant Hawkins for commendation.", objectives = "Retrieve the head of Lord Ha'kass.", progress = "Have anything to report?", completion = "Well done, <class>. Lord Ha'kass was a formidable foe and a high-ranking commander among the naga." }
WordHunterWoW_QuestEN[55772] = { title = "WANTED: Lady Narjiss", description = "Wanted for attacks against the Alliance!\n\nLady Narjiss is responsible for leading several raids and ambushes against our soldiers. Extreme caution advised!\n\nUpon completion of the mission, report to Lieutenant Hawkins for commendation.", objectives = "Retrieve the head of Lady Narjiss.", progress = "Have anything to report?", completion = "Well done, <class>. Lady Narjiss was a formidable foe and a high-ranking commander among the naga." }
WordHunterWoW_QuestEN[55773] = { title = "WANTED: Gler'thogg", description = "Wanted for attacks against the Alliance!\n\nGler'thogg is responsible for the gruesome deaths of several of our best soldiers. Extreme caution advised!\n\nUpon completion of the mission, report to Lieutenant Hawkins for commendation.", objectives = "Retrieve the Eye of Gler'thogg.", progress = "Have anything to report?", completion = "Well done, <class>. Gler'thogg was a formidable foe and a high-ranking commander among the naga." }
